  ui_story_5033_50330101_2_dialog_content = "Olha, mãe! Aquela pessoa ali caiu enquanto caminhava!",
  ui_story_5033_50330101_3_dialog_content = "Espere aqui. Deixe-me ir dar uma olhada.",
  ui_story_5033_50330101_4_dialog_content = "O-o que é isso...?",
  ui_story_5033_50330101_5_dialog_content = "<size=45>Aaaaah!</size>",
  ui_story_5033_50330101_6_dialog_content = "<color=#e8d9bb>Uma rua desconhecida em Umbraton</color>",
  ui_story_5033_50330101_7_dialog_content = "(Estou atrasado...)",
  ui_story_5033_50330101_8_dialog_content = "Tem certeza de que não viu mais ninguém por perto?",
