  ui_story_5033_50330101_21_dialog_content = "Espera aí!",
  ui_story_5033_50330101_22_dialog_content = "(Ainda há respirações fracas vindo dele, ele poderia...)",
  ui_story_5033_50330101_23_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_5033_50330101_24_dialog_content = "Desculpe, Shadowlord, tudo o que restou foi a vítima. As testemunhas não viram mais ninguém.",
  ui_story_5033_50330101_25_dialog_content = "Quem foi a seiva azarada?",
  ui_story_5033_50330101_26_dialog_content = "O forasteiro que fez fortuna apostando em cavalos. Ele caiu do lado de fora de sua casa. Parecia que ele estava a caminho de algum lugar. Mas...",
  ui_story_5033_50330101_27_dialog_content = "Com base na minha inspeção preliminar, acho que ele ainda pode ser salvo.",
  ui_story_5033_50330101_28_dialog_content = "Devemos aproveitar esta oportunidade.",
  ui_story_5033_50330101_29_dialog_content = "Vou enviar alguém para ressuscitá-lo agora mesmo. Você fica no caso.",
  ui_story_5033_50330101_30_dialog_content = "Alguma coisa sobre o perpetrador desta vez?",
  ui_story_5033_50330101_31_dialog_content = "Se ligarmos este crime a casos anteriores, os ferimentos na vítima são idênticos ao <color=#FFB400>assassinato da freira</color> há vários anos.",
  ui_story_5033_50330101_32_dialog_content = "Um detalhe crucial foi esquecido em todas as investigações anteriores.",
  ui_story_5033_50330101_33_dialog_content = "Todas as vítimas sofreram um pequeno corte em seus corpos antes de desmaiar de repente por um motivo que ainda não foi determinado.",
  ui_story_5033_50330101_34_dialog_content = "Os cortes são sempre pequenos demais para serem vistos a olho nu e não parecem letais.",
  ui_story_5033_50330101_35_dialog_content = "Mas após uma inspeção mais próxima da nossa vítima mais recente, estou bastante confiante de que é um ferimento de faca.",
