  ui_story_5033_50330101_42_dialog_content = "Aja com rapidez e cautela.",
  ui_story_5033_50330101_43_dialog_content = "Eu devo.",
  ui_story_5033_50330101_44_dialog_content = "<color=#e8d9bb>Um mês depois, na Home Goods Convention em Umbraton</color>",
  ui_story_5033_50330101_45_dialog_content = "<size=45>Extra, extra!</size>",
  ui_story_5033_50330101_46_dialog_content = "Novidades da Umbraton acabadas de sair do forno! Garanta já sua deliciosa prensa!",
  ui_story_5033_50330101_47_dialog_content = "(Quem descreve um jornal assim?!)",
  ui_story_5033_50330101_48_dialog_content = "Ei!",
  ui_story_5033_50330101_49_dialog_content = "PlayerName! Que visão rara! Você está sozinho em Umbraton?",
  ui_story_5033_50330101_50_dialog_content = "(Oh não, eu fui pego!)",
  ui_story_5033_50330101_51_dialog_content = "Então, que tal pegar uma cópia? Você não quer perder isso apenas em!",
  ui_story_5033_50330101_52_dialog_content = "\"Umbraton tem sido atormentado por <color=#FFB400>assassinatos em série misteriosos</color> nas últimas semanas\"...",
  ui_story_5033_50330101_53_dialog_content = "\"Várias pessoas ligadas ao <color=#FFB400>mercado negro</color> foram encontradas mortas em suas casas\"...",
  ui_story_5033_50330101_54_dialog_content = "\"As vítimas mostraram <color=#FFB400>sinais peculiares de luta</color>, e o assassino ainda está foragido\"...",
  ui_story_5033_50330101_55_dialog_content = "Como é isso? Você está com vontade de pegar o papel agora?",
  ui_story_5033_50330101_56_dialog_content = "Não, eu estou bem! Não estou aqui para comprar um jornal hoje.",
  ui_story_5033_50330101_57_dialog_content = "Vamos, PlayerName, você já está aqui. Você tem que comprar alguma coisa!",
  ui_story_5033_50330101_58_dialog_content = "Na verdade...",
  ui_story_5033_50330101_59_dialog_content = "<color=#e8d9bb>Alguns dias atrás em Cloud Gardens</color>",
  ui_story_5033_50330101_60_dialog_content = "(Ufa, finalmente, Cloud Gardens está mais apresentável agora.)",
  ui_story_5033_50330101_61_dialog_content = "(Estou trabalhando no projeto há tanto tempo que mereço uma pausa.)",
  ui_story_5033_50330101_62_dialog_content = "Mas isso ainda não é bom o suficiente.",
  ui_story_5033_50330101_63_dialog_content = "O que?! Como você sabia o que eu era...",
  ui_story_5033_50330101_64_dialog_content = "Seu rosto me disse que você estava prestes a desistir, PlayerName.",
  ui_story_5033_50330101_65_dialog_content = "Colocamos os móveis básicos no lugar, mas ainda está muito vazio e simples.",
  ui_story_5033_50330101_66_dialog_content = "Aqui!",
  ui_story_5033_50330101_67_dialog_content = "Uau, o que é essa pilha?",
  ui_story_5033_50330101_68_dialog_content = "Catálogos de expositores para a convenção anual Umbraton Home Goods!",
  ui_story_5033_50330101_69_dialog_content = "Você não quer saber por quantas conexões eu tive que passar para coletar todos eles!",
  ui_story_5033_50330101_70_dialog_content = "... Você está planejando isso desde sempre, não é.",
  ui_story_5033_50330101_71_dialog_content = "Não vamos nos debruçar sobre os pequenos detalhes!",
  ui_story_5033_50330101_72_dialog_content = "De qualquer forma, a renovação não é uma questão trivial. Esta é a sua casa, afinal.",
  ui_story_5033_50330101_73_dialog_content = "Agora imagine finalmente chegar em casa e relaxar depois de uma longa viagem. O que você vê?",
  ui_story_5033_50330101_74_dialog_content = "Oh, eu gostaria de me enrolar em uma poltrona reclinável.",
  ui_story_5033_50330101_75_dialog_content = "Qual é a sensação da poltrona para você, é feita de cetim macio ou couro fresco?",
  ui_story_5033_50330101_76_dialog_content = "Couro para uma poltrona reclinável, é claro! E ficaria mais legal.",
  ui_story_5033_50330101_77_dialog_content = "Ver? Mobiliário e decoração não apenas ajudam no contentamento, mas também são uma boa maneira de mostrar seu estilo!",
  ui_story_5033_50330101_78_dialog_content = "Todas as coisas que entram em sua casa devem ser escolhidas com cuidado.",
  ui_story_5033_50330101_79_dialog_content = "WW-Espere um minuto!",
  ui_story_5033_50330101_80_dialog_content = "Você não está tentando me fazer ler todos esses folhetos, está?",
  ui_story_5033_50330101_81_dialog_content = "Não é como se você tivesse algo para fazer nos próximos dias!",
  ui_story_5033_50330101_82_dialog_content = "E você tem que lidar pessoalmente com cada etapa da reforma, de qualquer maneira.",
  ui_story_5033_50330101_83_dialog_content = "Tudo bem agora, não há tempo para bate-papo.",
  ui_story_5033_50330101_84_dialog_content = "Temos que nos preparar. Comprar é uma guerra, você sabe!",
