  ui_story_5033_50330101_87_dialog_content = "Sim, Oficial Vice!",
  ui_story_5033_50330101_88_dialog_content = "Assim, nós folheamos os folhetos por quatro dias inteiros com muito pouco sono.",
  ui_story_5033_50330101_89_dialog_content = "Uau, impressionante!",
  ui_story_5033_50330101_90_dialog_content = "Sim. Vice estava tão focada no laser que ela poderia queimar através deles com os olhos.",
  ui_story_5033_50330101_91_dialog_content = "Achei que tudo que eu tinha que fazer era seguir Vice pela convenção.",
  ui_story_5033_50330101_92_dialog_content = "No entanto...",
  ui_story_5033_50330101_93_dialog_content = "<color=#e8d9bb>Pouco antes da partida</color>",
  ui_story_5033_50330101_94_dialog_content = "Oh Deus, eu sinto muito, PlayerName!!!",
  ui_story_5033_50330101_95_dialog_content = "Acabei de receber uma tarefa urgente do Comandante Hiiro...",
  ui_story_5033_50330101_96_dialog_content = "Então, acabei vindo sozinho sem nenhuma pista ou orçamento em mente.",
  ui_story_5033_50330101_97_dialog_content = "Mas que pena, PlayerName. A convenção foi <color=#FFB400>cancelada</color> no último minuto.",
  ui_story_5033_50330101_98_dialog_content = "O quê?!",
  ui_story_5033_50330101_99_dialog_content = "É devido aos assassinatos em série que deixaram todos nervosos.",
  ui_story_5033_50330101_100_dialog_content = "Por questões de segurança, a Umbraton cancelou todas as grandes reuniões por enquanto.",
  ui_story_5033_50330101_101_dialog_content = "R-Sério?!",
  ui_story_5033_50330101_102_dialog_content = "Que sorte podre...",
  ui_story_5033_50330101_103_dialog_content = "Não fique todo deprimido. Umbraton tem um monte de coisas à venda.",
