  ui_story_5033_50330101_109_dialog_content = "Essa cor é muito bonita.",
  ui_story_5033_50330101_110_dialog_content = "Cartões postais também podem ser decoração de casa, você sabe.",
  ui_story_5033_50330101_111_dialog_content = "Sinta-se livre para olhar através deles. Eles destacam diferentes cidades e locais ao redor de Umbraton.",
