  ui_story_5033_50330101_117_dialog_content = "(Nunca estive lá. Seria bom dar uma olhada em algum momento.)",
  ui_story_5033_50330101_118_dialog_content = "(Afinal, a terapia de varejo moderada melhora o humor.)",
  ui_story_5033_50330101_119_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5033_50330101_120_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5033_50330101_121_dialog_content = "Meu cartão postal!!!",
  ui_story_5033_50330101_122_dialog_content = "Nossa... Para onde foi?",
  ui_story_5033_50330101_123_dialog_content = "Parem aí, vocês dois!",
  ui_story_5033_50330101_124_dialog_content = "Huff... Huff...",
  ui_story_5033_50330101_125_dialog_content = "...",
  ui_story_5033_50330101_126_dialog_content = "(Que homem de aparência estranha. Esse tipo de visual é a última moda em Umbraton?)",
  ui_story_5033_50330101_127_dialog_content = "(Espere, por que ele parece familiar?)",
  ui_story_5033_50330101_128_dialog_content = "Eu não tenho ideia por que você nos parou...",
  ui_story_5033_50330101_129_dialog_content = "Mas obrigado mesmo assim, PlayerName.",
  ui_story_5033_50330101_130_dialog_content = "Bem, já que o homem foi pego...",
  ui_story_5033_50330101_131_dialog_content = "Eu posso tirar daqui.",
  ui_story_5033_50330101_132_dialog_content = "Corax?! Por que você está vestido assim?",
  ui_story_5033_50330101_133_dialog_content = "Por favor, senhor, eu imploro, não tenho nada a ver com isso!",
  ui_story_5033_50330101_134_dialog_content = "A menos que você me dê algo que valha a pena...",
  ui_story_5033_50330101_135_dialog_content = "Vou levá-lo direto para o Shadowlord.",
  ui_story_5033_50330101_136_dialog_content = "Mas eu não sei de nada!",
  ui_story_5033_50330101_137_dialog_content = "É mesmo?",
  ui_story_5033_50330101_138_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5033_50330101_139_dialog_content = "Não, não! Ok, eu vou falar, apenas deixe isso de lado!",
  ui_story_5033_50330101_140_dialog_content = "Fiz negócios com eles com certeza, mas não matei ninguém!",
  ui_story_5033_50330101_141_dialog_content = "Todos eles começaram a fazer negócios obscuros e usaram seu dinheiro para explorar o submundo criminoso de Umbraton!",
  ui_story_5033_50330101_142_dialog_content = "Isso é tudo notícia velha. Algo mais?",
  ui_story_5033_50330101_143_dialog_content = "A-E...",
  ui_story_5033_50330101_144_dialog_content = "Antes de morrer, todos eles visitaram <color=#FFB400>Euphoria</color>!",
  ui_story_5033_50330101_145_dialog_content = "Supostamente, o <color=#FFB400>Grim Reaper</color> aparece lá!",
  ui_story_5033_50330101_146_dialog_content = "Ceifador?",
  ui_story_5033_50330101_147_dialog_content = "E-Isso mesmo... Qualquer um que não obedece ao Ceifador...",
  ui_story_5033_50330101_148_dialog_content = "Ele arrebata a vida deles alguns dias depois!",
  ui_story_5033_50330101_149_dialog_content = "Eles devem ter morrido por causa do Ceifador, de quem não se fala!",
  ui_story_5033_50330101_150_dialog_content = "Mas já não é Euphoria...",
  ui_story_5033_50330101_151_dialog_content = "É melhor você estar dizendo a verdade.",
  ui_story_5033_50330101_152_dialog_content = "Eu sou, eu juro!",
  ui_story_5033_50330101_153_dialog_content = "...",
  ui_story_5033_50330101_154_option_content = "Aumento de Força!",
  ui_story_5033_50330101_155_dialog_content = "Uh, ele está dizendo a verdade, Corax.",
  ui_story_5033_50330101_156_dialog_content = "Não sinto nada além de estresse e medo.",
  ui_story_5033_50330101_157_dialog_content = "Obrigado pela grande ajuda, PlayerName.",
  ui_story_5033_50330101_158_dialog_content = "O-o que você está fazendo agora?!",
  ui_story_5033_50330101_159_dialog_content = "Eu gostaria que você fosse para Euphoria comigo.",
  ui_story_5033_50330101_160_dialog_content = "Agora mesmo?!",
  ui_story_5033_50330101_161_dialog_content = "Estou sob a ordem do Shadowlord para ir lá e investigar os assassinatos em série em Umbraton.",
  ui_story_5033_50330101_162_dialog_content = "Vou explicar o resto no caminho.",
  ui_story_5033_50330101_163_dialog_content = "Para evitar que seu Colossus chame atenção desnecessária, pegaremos um dirigível.",
  ui_story_5033_50330101_164_dialog_content = "Vejo você no Shuttle Hub amanhã de manhã.",
  ui_story_5033_50330101_165_dialog_content = "Quer dizer, eu queria conferir Euphoria, mas...",
  ui_story_5033_50330101_166_dialog_content = "Bem, então, até amanhã.",
  ui_story_5033_50330101_167_dialog_content = "Espere, deixe-me terminar!",
  ui_story_5033_50330101_168_dialog_content = "Você poderia pelo menos me deixar pensar sobre isso...",
  ui_story_5033_50330201_1_dialog_content = "<color=#e8d9bb>Centro de transporte</color>",
  ui_story_5033_50330201_2_dialog_content = "(Bem, aqui estou eu. Cheguei aqui antes do prometido...)",
  ui_story_5033_50330201_3_dialog_content = "(Eu raramente venho aqui desde que viajo em Soroz.)",
  ui_story_5033_50330201_4_dialog_content = "(Eu gostaria de poder enviar um cartão postal de volta para Eraveil... Se ao menos eu não tivesse perdido o que eu tinha ontem.)",
  ui_story_5033_50330201_5_dialog_content = "Meu cartão postal... Ugh...",
  ui_story_5033_50330201_6_dialog_content = "Perdoe-me por ouvir seu lamento.",
  ui_story_5033_50330201_7_dialog_content = "Se você está chateado com um cartão-postal,",
  ui_story_5033_50330201_8_dialog_content = "Acontece que eu tenho um em mim. Aqui, pegue.",
  ui_story_5033_50330201_9_dialog_content = "Uau, de jeito nenhum! É a mesma foto, mesmo!",
  ui_story_5033_50330201_10_dialog_content = "Eu não posso aceitar isso. Eu nem te conheço...",
  ui_story_5033_50330201_11_dialog_content = "Combina mais com você. Pegue-o, e eu posso chamá-lo de minha boa ação do dia.",
  ui_story_5033_50330201_12_dialog_content = "Realmente, mantenha-o. Eu não preciso mais.",
  ui_story_5033_50330201_13_dialog_content = "Você não?",
  ui_story_5033_50330201_14_dialog_content = "Sim, porque eu vou voltar.",
  ui_story_5033_50330201_15_dialog_content = "Faz quatorze anos desde a última vez que estive em Euphoria.",
  ui_story_5033_50330201_16_dialog_content = "Desculpe por divagar.",
  ui_story_5033_50330201_17_dialog_content = "Tudo bem, ainda estou esperando alguém aparecer. Então, como devo te chamar?",
  ui_story_5033_50330201_18_dialog_content = "...",
  ui_story_5033_50330201_19_dialog_content = "Ana está bem.",
  ui_story_5033_50330201_20_dialog_content = "Eu estou PlayerName. Esta seria a minha primeira vez em Euphoria.",
  ui_story_5033_50330201_21_dialog_content = "Parece que você conhece bem. Importa-se de me contar um pouco sobre isso?",
  ui_story_5033_50330201_22_dialog_content = "Percebi que o cartão-postal o chamava de \"<color=#FFB400>País das Maravilhas</color>\".",
  ui_story_5033_50330201_23_dialog_content = "Está correto. Para os forasteiros da época, certamente poderia ser considerado uma espécie de país das maravilhas.",
  ui_story_5033_50330201_24_dialog_content = "Eles vieram em busca da felicidade que não encontravam em nenhum outro lugar.",
  ui_story_5033_50330201_25_dialog_content = "No entanto, o que mais seduziu não foi o ambiente acolhedor ou a paisagem",
  ui_story_5033_50330201_26_dialog_content = "mas sim o próspero <color=#FFB400>mercado negro</color> nas sombras de seus prédios únicos.",
  ui_story_5033_50330201_27_dialog_content = "Mercado negro?!",
  ui_story_5033_50330201_28_dialog_content = "A Umbraton também não tem? Por que ir para a Euforia?",
  ui_story_5033_50330201_29_dialog_content = "Começou bem parecido com Umbraton, mas Euphoria era uma propriedade legalmente privada.",
  ui_story_5033_50330201_30_dialog_content = "Como você provavelmente pode imaginar, cruzar os limites para ganho pessoal e desejo era comum lá.",
  ui_story_5033_50330201_31_dialog_content = "Grandes cassinos, fabricantes de armas particulares... Tudo o que você pode imaginar estava lá.",
  ui_story_5033_50330201_32_dialog_content = "Isso soa ainda mais liberal do que Umbraton.",
  ui_story_5033_50330201_33_dialog_content = "Obrigado pela prima. Estou ansioso pela visita.",
  ui_story_5033_50330201_34_dialog_content = "Mas temo que você só ficará desapontado se for para Euphoria com alguma noção preconcebida.",
  ui_story_5033_50330201_35_dialog_content = "Como assim?",
  ui_story_5033_50330201_36_dialog_content = "Algum tempo depois que eu saí, Euphoria de repente desapareceu.",
  ui_story_5033_50330201_37_dialog_content = "Eu nunca ouvi ninguém mencionar o nome desde então.",
  ui_story_5033_50330201_38_dialog_content = "Como se a cidade tivesse sido propositalmente esquecida.",
  ui_story_5033_50330201_39_dialog_content = "Uma cidade esquecida, hein...",
  ui_story_5033_50330201_40_dialog_content = "PlayerName!",
  ui_story_5033_50330201_41_dialog_content = "Desculpe a espera.",
  ui_story_5033_50330201_42_dialog_content = "Está bem. Tenho conversado com essa freira aqui que também vai para a Euphoria.",
  ui_story_5033_50330201_43_dialog_content = "Anne, este é Corax. Ele está viajando comigo.",
  ui_story_5033_50330201_44_dialog_content = "O dirigível está prestes a decolar. Devemos embarcar agora.",
  ui_story_5033_50330201_45_dialog_content = "É raro encontrar um voo para Euphoria, então não vamos perdê-lo.",
  ui_story_5033_50330201_46_dialog_content = "T-Tá...",
  ui_story_5033_50330201_47_dialog_content = "<color=#e8d9bb>No dirigível</color>",
  ui_story_5033_50330201_48_dialog_content = "De qualquer forma, eu oficialmente peguei o caso do Shadowlord um mês atrás.",
  ui_story_5033_50330201_49_dialog_content = "Umbraton tem visto crimes violentos recentemente visando vários locais de comércio clandestino, bem como aqueles envolvidos no comércio.",
  ui_story_5033_50330201_50_dialog_content = "Os eventos estão prejudicando a economia.",
  ui_story_5033_50330201_51_dialog_content = "Tem que ser uma investigação secreta por uma série de razões.",
  ui_story_5033_50330201_52_dialog_content = "Pelo testemunho daquele homem ontem, eu só tenho que ir lá.",
  ui_story_5033_50330201_53_dialog_content = "Então você está dizendo que cada pista está apontando para Euphoria?",
  ui_story_5033_50330201_54_dialog_content = "Ah, falando no <color=#FFB400>assassinato da freira</color> que começou tudo, temos alguém antes de nós que pode ajudar.",
  ui_story_5033_50330201_55_dialog_content = "...",
  ui_story_5033_50330201_56_dialog_content = "Sem problemas, posso cooperar.",
  ui_story_5033_50330201_57_dialog_content = "Relaxe, eu só quero fazer algumas perguntas simples.",
  ui_story_5033_50330201_58_dialog_content = "Você conhece uma freira chamada <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330201_59_dialog_content = "Eu conheço ela, sim.",
  ui_story_5033_50330201_60_dialog_content = "Mas tudo o que sei é que ela foi transferida de Euphoria para Umbraton. Ela fez...?",
  ui_story_5033_50330201_61_dialog_content = "Ela foi uma das primeiras vítimas.",
  ui_story_5033_50330201_62_dialog_content = "... Que ela descanse em paz.",
  ui_story_5033_50330201_63_dialog_content = "Talvez esse seja o destino de nós, freiras.",
  ui_story_5033_50330201_64_dialog_content = "Não poderia escapar nem mesmo deixando Euphoria, suponho.",
  ui_story_5033_50330201_65_dialog_content = "Não tentando ser rude, mas você não parece particularmente surpreso.",
  ui_story_5033_50330201_66_dialog_content = "As freiras não têm mais lugar na Euforia.",
  ui_story_5033_50330201_67_dialog_content = "Se você for pego sozinho nas ruas e não tiver dinheiro suficiente,",
  ui_story_5033_50330201_68_dialog_content = "até mesmo como você morre depende do destino decidir.",
  ui_story_5033_50330201_69_dialog_content = "Parece um lugar tranquilo...",
  ui_story_5033_50330201_70_dialog_content = "No entanto, você está pilotando um dirigível para Euphoria como nós.",
  ui_story_5033_50330201_71_dialog_content = "Procurei me livrar de tudo indo embora.",
  ui_story_5033_50330201_72_dialog_content = "Mas há algo me chamando de volta agora.",
  ui_story_5033_50330201_73_dialog_content = "... Quer saber, não tenho nada a esconder. Vou voltar para <color=#FFB400>ver um amigo</color>.",
  ui_story_5033_50330201_74_dialog_content = "Acho que não vamos seguir o mesmo caminho.",
  ui_story_5033_50330201_75_dialog_content = "Acho que estamos quase lá, a julgar pela paisagem abaixo.",
  ui_story_5033_50330201_76_dialog_content = "<color=#e8d9bb>Uma rua em Euphoria</color>",
  ui_story_5033_50330201_77_dialog_content = "Acho que é aqui que nos despedimos.",
  ui_story_5033_50330201_78_dialog_content = "Boa sorte com o seu caso.",
  ui_story_5033_50330201_79_dialog_content = "Obrigada. Se cuida também.",
  ui_story_5033_50330201_80_dialog_content = "(Ela saiu com pressa. Ela também não parecia tão preocupada com sua segurança...)",
  ui_story_5033_50330201_81_dialog_content = "<color=#e8d9bb>Cow, caw—</color>",
  ui_story_5033_50330201_82_dialog_content = "É desolado aqui, assim como Anne disse.",
  ui_story_5033_50330201_83_dialog_content = "Os prédios estão em ruínas ou vandalizados, e não há uma pessoa à vista...",
  ui_story_5033_50330201_84_dialog_content = "Acho que esse chamado País das Maravilhas não passa de uma vila abandonada, afinal.",
  ui_story_5033_50330201_85_dialog_content = "Então você também já ouviu falar do apelido de Euphoria, hein?",
  ui_story_5033_50330201_86_dialog_content = "Não fique desapontado. Recebi algumas informações úteis de Taki antes de sair.",
  ui_story_5033_50330201_87_dialog_content = "Bem, então vamos colocar esse show na estrada...",
  ui_story_5033_50330201_88_dialog_content = "Hum?",
  ui_story_5033_50330201_89_dialog_content = "O que foi?",
  ui_story_5033_50330201_90_dialog_content = "Sinto algo estranho no ar...",
  ui_story_5033_50330201_91_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330201_92_dialog_content = "<size=45>Ah!!!</size>",
  ui_story_5033_50330201_93_dialog_content = "Assim como o relatório disse, os céus nublados perpétuos e o nevoeiro denso da área são um playground natural para os Eclipsites...",
  ui_story_5033_50330201_94_dialog_content = "Seja qual for o tipo de Eclipsitos que sejam, teremos que lutar contra eles!",
  ui_story_5033_50330201_95_dialog_content = "Lâmina de gelo!",
  ui_story_5033_50330202_1_dialog_content = "<size=45>Lâmina de gelo!!</size>",
  ui_story_5033_50330202_2_dialog_content = "Sai daí, PlayerName!",
  ui_story_5033_50330202_3_dialog_content = "<size=45>Boa!</size>",
  ui_story_5033_50330202_4_dialog_content = "(Já passei por esse mesmo cenário exato um milhão de vezes até agora!)",
  ui_story_5033_50330202_5_dialog_content = "(Há uma garra Eclipsite gigante acima da minha cabeça.)",
  ui_story_5033_50330202_6_dialog_content = "(Se eu não me abaixar, minha cabeça vai se abrir em um segundo.)",
  ui_story_5033_50330202_7_dialog_content = "Ficar longe!!",
  ui_story_5033_50330202_8_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5033_50330202_9_dialog_content = "...",
  ui_story_5033_50330202_10_dialog_content = "Isso é um machado? Eles estão realmente lutando contra Eclipsites com machados?",
  ui_story_5033_50330202_11_dialog_content = "<color=#e8d9bb>*Corte com machado*</color>",
  ui_story_5033_50330202_12_dialog_content = "<color=#e8d9bb>*Axe balançando e cortando*</color>",
  ui_story_5033_50330202_13_dialog_content = "Eles parecem oscilações aleatórias, mas atingiram os sinais vitais da mesma forma.",
  ui_story_5033_50330202_14_dialog_content = "Obviamente, esses caras sabem como lidar com Eclipsites.",
  ui_story_5033_50330202_15_dialog_content = "Você está bem, PlayerName? Você não parece magoado.",
  ui_story_5033_50330202_16_dialog_content = "Estou bem, só um pouco assustado.",
  ui_story_5033_50330202_17_dialog_content = "Eles são euforianos locais?",
  ui_story_5033_50330202_18_dialog_content = "Tenha cuidado como você esfola-los. A pele do peito tem que estar inteira.",
  ui_story_5033_50330202_19_dialog_content = "Puxe as unhas, corte os chifres. Ah, e os olhos também...",
  ui_story_5033_50330202_20_dialog_content = "Ai!",
  ui_story_5033_50330202_21_dialog_content = "Eu disse para você ter cuidado, seu bastardo! Dê-me essa faca!",
  ui_story_5033_50330202_22_dialog_content = "O olho está arruinado. Coloque-o na pilha de lixo e queime-o.",
  ui_story_5033_50330202_23_dialog_content = "Eles estão dissecando o Eclipsite? O que eles querem com tudo isso?",
  ui_story_5033_50330202_24_dialog_content = "...",
  ui_story_5033_50330202_25_dialog_content = "Hora de ir, PlayerName.",
  ui_story_5033_50330202_26_dialog_content = "Agora? Mas eles me salvaram, eu não deveria agradecê-los?",
  ui_story_5033_50330202_27_dialog_content = "Ouça com atenção.",
  ui_story_5033_50330202_28_dialog_content = "Olhe atentamente para o que eles estão fazendo.",
  ui_story_5033_50330202_29_dialog_content = "Eles não estavam tentando te salvar. O foco deles não estava em você para começar.",
  ui_story_5033_50330202_30_dialog_content = "A pele e os órgãos do Eclipsite, é isso que eles estão procurando. Provavelmente para vender a preços muito baratos - um por 200, dois por 300.",
  ui_story_5033_50330202_31_dialog_content = "Eles provavelmente estão seguindo os Eclipsites há algum tempo. Nós éramos apenas transeuntes colaterais.",
  ui_story_5033_50330202_32_dialog_content = "A euforia, cidade esquecida como é, claramente segue um conjunto de regras totalmente diferente.",
  ui_story_5033_50330202_33_dialog_content = "<size=33>Se não formos agora, este lugar vai nos sugar e nos engolir inteiros.</size>",
  ui_story_5033_50330202_34_dialog_content = "OK. Então vamos-",
  ui_story_5033_50330202_35_dialog_content = "Esperem, vocês forasteiros.",
  ui_story_5033_50330202_36_dialog_content = "Você não pode simplesmente ir e vir como quiser aqui.",
  ui_story_5033_50330202_37_dialog_content = "<size=45>Não nos lembramos de ter dado permissão para você sair!</size>",
  ui_story_5033_50330202_38_dialog_content = "<color=#e8d9bb>Claro!</color>",
  ui_story_5033_50330202_39_dialog_content = "Não me diga que você não conhece as regras da Euforia.",
  ui_story_5033_50330202_40_dialog_content = "Ele acabou de abrir um buraco no chão...",
  ui_story_5033_50330202_41_dialog_content = "<size=33>Acho que agora é tarde demais.</size>",
  ui_story_5033_50330202_42_dialog_content = "Dizem que Euphoria é um lugar hospitaleiro que faz com que todos se sintam bem-vindos.",
  ui_story_5033_50330202_43_dialog_content = "É claro que essa hospitalidade deve ser retribuída.",
  ui_story_5033_50330202_44_dialog_content = "Aqui está. Faça sua contagem.",
  ui_story_5033_50330202_45_dialog_content = "Você vem aqui.",
  ui_story_5033_50330202_46_dialog_content = "Quem eu?",
  ui_story_5033_50330202_47_dialog_content = "Quem mais? <size=33>Conte isso lá atrás.</size>",
  ui_story_5033_50330202_48_dialog_content = "Quanto a você... Fale, de onde você veio?",
  ui_story_5033_50330202_49_dialog_content = "Nós somos...",
  ui_story_5033_50330202_50_dialog_content = "(Por que Corax apenas olhou para mim? Agora provavelmente não é hora de ser sincero.)",
  ui_story_5033_50330202_51_dialog_content = "(Mas este é um município de Umbraton, então talvez possamos fazê-los recuar se descobrirem que somos de lá.)",
  ui_story_5033_50330202_52_dialog_content = "Somos de Eraveil, ao norte de Lumopolis. É uma pequena cidade isolada do resto do mundo.",
  ui_story_5033_50330202_53_dialog_content = "Hã?",
  ui_story_5033_50330202_54_dialog_content = "Eraveil...",
  ui_story_5033_50330202_55_dialog_content = "Quem diabos você está tentando enganar?",
  ui_story_5033_50330202_56_dialog_content = "É verdade.",
  ui_story_5033_50330202_57_dialog_content = "(Ele com certeza está vendendo com uma cara séria.)",
  ui_story_5033_50330202_58_dialog_content = "(Ele provavelmente também está tentando sugerir que eles são super incultos...)",
  ui_story_5033_50330202_59_dialog_content = "Uh, chefe, acho que Eraveil é um lugar real.",
  ui_story_5033_50330202_60_dialog_content = "Multar. Próxima pergunta: o que você faz e por que está aqui?",
  ui_story_5033_50330202_61_dialog_content = "Estamos aqui para negócios, vendendo lixo, você sabe como é. Apenas tentando raspar.",
  ui_story_5033_50330202_62_dialog_content = "Então por que você não tem nada com você?",
  ui_story_5033_50330202_63_dialog_content = "Estamos apenas vasculhando o local. E nós trouxemos oferendas, não trouxemos?",
  ui_story_5033_50330202_64_dialog_content = "Quanto a quem somos, ele é meu motorista. E eu, eu...",
  ui_story_5033_50330202_65_dialog_content = "<size=45>Terminei de contar!</size>",
  ui_story_5033_50330202_66_dialog_content = "Eu tenho 1.235 no total! <size=33>Isso é muito dinheiro, chefe. Esses dois são ricos.</size>",
  ui_story_5033_50330202_67_dialog_content = "Tudo bem.",
  ui_story_5033_50330202_68_dialog_content = "Visto que fizemos a nossa oferta, acho que podemos cancelar esta pequena cerimónia de boas-vindas.",
  ui_story_5033_50330202_69_dialog_content = "Estaremos a caminho agora. Não há necessidade de nos acompanhar.",
  ui_story_5033_50330202_70_dialog_content = "Você desembolsou o dinheiro, mas não o suficiente.",
  ui_story_5033_50330202_71_dialog_content = "Como assim?",
  ui_story_5033_50330202_72_dialog_content = "O preço acabou de subir.",
  ui_story_5033_50330202_73_dialog_content = "Quantos?",
  ui_story_5033_50330202_74_dialog_content = "20.000.",
  ui_story_5033_50330202_75_dialog_content = "E isso vai fazer?",
  ui_story_5033_50330202_76_dialog_content = "Vamos ver primeiro.",
  ui_story_5033_50330202_77_dialog_content = "Eles estão nos roubando, Corax! Eles não nos deixarão ir, mesmo se lhes dermos todo o nosso dinheiro.",
  ui_story_5033_50330202_78_dialog_content = "Relaxar.",
  ui_story_5033_50330202_79_dialog_content = "Eu tenho 20.000 em mim. Você pode até pedir mais, mas você mesmo terá que vir buscar.",
  ui_story_5033_50330202_80_dialog_content = "Há apenas dois de nós e uma dúzia de vocês. Não há razão para você ter medo.",
  ui_story_5033_50330202_81_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5033_50330202_82_dialog_content = "<size=45>Oof!</size>",
  ui_story_5033_50330202_83_dialog_content = "Chefe!!!!",
  ui_story_5033_50330202_84_dialog_content = "Você tem um maldito desejo de morte?!",
  ui_story_5033_50330202_85_dialog_content = "(Mas seu braço estava quebrado!)",
  ui_story_5033_50330202_86_dialog_content = "(Estava pendurado como um macarrão molhado.)",
  ui_story_5033_50330202_87_dialog_content = "(No entanto, ele se regenerou em um segundo.)",
  ui_story_5033_50330202_88_dialog_content = "Pare de gritar tão alto. Seu braço está bem.",
  ui_story_5033_50330202_89_dialog_content = "Veja por si mesmo.",
  ui_story_5033_50330202_90_dialog_content = "Mas estava quebrado, e eu senti isso!",
  ui_story_5033_50330202_91_dialog_content = "V-você—",
  ui_story_5033_50330202_92_dialog_content = "Guarde o dinheiro. São exatamente 20.000. Você não queria saber o que eu faço para viver?",
  ui_story_5033_50330202_93_dialog_content = "Eu sou um médico.",
  ui_story_5033_50330202_94_dialog_content = "Eu posso curá-lo, e posso quebrar todos os ossos do seu corpo também.",
  ui_story_5033_50330202_95_dialog_content = "Não só você, mas todos atrás de você também.",
  ui_story_5033_50330202_96_dialog_content = "...",
  ui_story_5033_50330202_97_dialog_content = "Então, estamos livres para sair agora?",
  ui_story_5033_50330202_98_dialog_content = "Você apenas espera! Você vai se arrepender disso!",
  ui_story_5033_50330301_1_dialog_content = "(Nós finalmente nos livramos deles...)",
  ui_story_5033_50330301_2_dialog_content = "Por que você perdeu tanto tempo com eles, Corax?",
  ui_story_5033_50330301_3_dialog_content = "Você poderia simplesmente ter esquecido o nome de Istvan.",
  ui_story_5033_50330301_4_dialog_content = "Eles podem parecer malvados, mas são apenas um bando de rufiões de rua.",
  ui_story_5033_50330301_5_dialog_content = "De jeito nenhum eles desafiariam o Senhor das Sombras de Umbraton.",
  ui_story_5033_50330301_6_dialog_content = "Essa teria sido a saída mais fácil, mas haveria repercussões.",
  ui_story_5033_50330301_7_dialog_content = "Umbraton é poderoso, mas o Shadowlord prefere manter as coisas discretas.",
  ui_story_5033_50330301_8_dialog_content = "Trazê-lo à tona teria sido visto como uma provocação.",
  ui_story_5033_50330301_9_dialog_content = "É por isso que você estava me sinalizando mais cedo?",
  ui_story_5033_50330301_10_dialog_content = "Sim. Mas é para nossa própria segurança e também para a privacidade do Senhor das Sombras.",
  ui_story_5033_50330301_11_dialog_content = "... Isso é realmente sério?",
  ui_story_5033_50330301_12_dialog_content = "Muitos euforianos odeiam Umbraton. \"Muitos\" é um eufemismo, na verdade.",
  ui_story_5033_50330301_13_dialog_content = "Os dois não conduzem nenhum negócio adequado um com o outro há anos.",
  ui_story_5033_50330301_14_dialog_content = "<color=#FFB400>Doze anos atrás</color>, o Darkover varreu Umbraton e todas as regiões vizinhas.",
  ui_story_5033_50330301_15_dialog_content = "Cidades de todos os tamanhos caíram, forçando Umbraton a passar por uma reestruturação.",
  ui_story_5033_50330301_16_dialog_content = "Havia caos por toda parte, e Euphoria foi uma das cidades mais atingidas.",
  ui_story_5033_50330301_17_dialog_content = "Os Eclipsites que Umbraton derrotou todos invadiram o caminho para a Euforia.",
  ui_story_5033_50330301_18_dialog_content = "Mas o Shadowlord não tinha forças naquela época, então ele não podia ajudar ninguém.",
  ui_story_5033_50330301_19_dialog_content = "Depois que a guerra acabou, a teoria da conspiração \"A Umbraton usou Darkover para arruinar a Euphoria\" começou a circular.",
  ui_story_5033_50330301_20_dialog_content = "Mas eu pensei que Anne disse que Euphoria era de propriedade privada?",
  ui_story_5033_50330301_21_dialog_content = "O dono acabou de abandoná-lo?",
  ui_story_5033_50330301_22_dialog_content = "Isso era verdade, mas tornou-se terra de ninguém após a invasão do Eclipsite.",
  ui_story_5033_50330301_23_dialog_content = "Os sobreviventes se uniram e formaram muitas <color=#FFB400>pequenas cooperativas</color>.",
  ui_story_5033_50330301_24_dialog_content = "Algumas das instalações de abastecimento puderam ser recuperadas após reparos básicos.",
  ui_story_5033_50330301_25_dialog_content = "Assim que a população do entorno começou a crescer, alguns locais voltaram a funcionar.",
  ui_story_5033_50330301_26_dialog_content = "As cooperativas também evoluíram gradualmente para <color=#FFB400>gangues</color>.",
  ui_story_5033_50330301_27_dialog_content = "A euforia com certeza passou por mudanças drásticas...",
  ui_story_5033_50330301_28_dialog_content = "Portanto, esta paisagem diante de nós é o resultado de uma cidade estagnada após uma guerra.",
  ui_story_5033_50330301_29_dialog_content = "As ruas podem estar vazias agora, mas definitivamente há olhos nas sombras nos observando.",
  ui_story_5033_50330301_30_dialog_content = "Tudo bem, precisamos nos mexer e tentar passar despercebidos.",
  ui_story_5033_50330301_31_dialog_content = "Antes de sair, Taki me deu duas opções e contatou seus contatos para ambas.",
  ui_story_5033_50330301_32_dialog_content = "A opção A é visitar <color=#FFB400>Gustav</color> no Euphoria's Odd Jobs.",
  ui_story_5033_50330301_33_dialog_content = "A opção B é encontrar <color=#FFB400>Nekoyashiki</color>, um Odd Jobs em roaming.",
  ui_story_5033_50330301_34_dialog_content = "Isso soa como uma escolha entre algo \"oficial\" e algo \"informal\".",
  ui_story_5033_50330301_35_dialog_content = "O que você acha, PlayerName?",
  ui_story_5033_50330301_36_option_content = "Gustav de Biscates em Euphoria.",
  ui_story_5033_50330301_37_dialog_content = "Um trabalho estranho local respeitável, como Taki, teria informações mais confiáveis.",
  ui_story_5033_50330301_38_dialog_content = "Além disso, um Odd Jobs oficial teria mais conexões, portanto, mais leads.",
  ui_story_5033_50330301_39_dialog_content = "Isso faz sentido, mas...",
  ui_story_5033_50330301_40_dialog_content = "Seremos expostos quando formos lá.",
  ui_story_5033_50330301_41_dialog_content = "Todas as outras gangues com conexões lá vão saber de nós.",
  ui_story_5033_50330301_42_dialog_content = "Isso soa meio perigoso...",
  ui_story_5033_50330301_43_option_content = "Nekoyashiki, os biscates de roaming.",
  ui_story_5033_50330301_44_dialog_content = "Ele parece enigmático, e ninguém vai notar se tentarmos encontrá-lo.",
  ui_story_5033_50330301_45_dialog_content = "E um Odd Jobs em roaming pode ter informações confidenciais.",
  ui_story_5033_50330301_46_dialog_content = "Você tem razão.",
  ui_story_5033_50330301_47_dialog_content = "Contatos como esse são realmente mais seguros.",
  ui_story_5033_50330301_48_dialog_content = "Vamos encontrar este Nekoyashiki, então.",
  ui_story_5033_50330301_49_dialog_content = "Mas ele é confiável?",
  ui_story_5033_50330301_50_dialog_content = "Não é uma questão de confiabilidade, mas de confiabilidade, com Odd Jobs.",
  ui_story_5033_50330301_51_dialog_content = "Porque só nós podemos determinar o que é confiável?",
  ui_story_5033_50330301_52_dialog_content = "Muito esperto.",
  ui_story_5033_50330301_53_dialog_content = "Para Gustav, Nekoyashiki é apenas peixe pequeno.",
  ui_story_5033_50330301_54_dialog_content = "Se você acabar indo com ele, será difícil localizá-lo.",
  ui_story_5033_50330301_55_dialog_content = "Seu paradeiro é imprevisível, mas ele deixa símbolos, geralmente em algum lugar do prédio em que está...",
  ui_story_5033_50330301_56_dialog_content = "Foi o que Taki me disse. Quanto ao símbolo...",
  ui_story_5033_50330301_57_dialog_content = "Será que é um <color=#FFB400>grafite em forma de cicatriz</color>?",
  ui_story_5033_50330301_58_dialog_content = "Como você sabe, PlayerName?",
  ui_story_5033_50330301_59_dialog_content = "Acabei de ver um. Veja, está na placa daquele restaurante.",
  ui_story_5033_50330301_60_dialog_content = "Como se estivesse acenando para nós virmos.",
  ui_story_5033_50330301_61_dialog_content = "Eu sabia que nada escapava desses vendedores de informações.",
  ui_story_5033_50330301_62_dialog_content = "<color=#828282>Crec...</color>",
  ui_story_5033_50330301_63_dialog_content = "Alguém em?",
  ui_story_5033_50330301_64_dialog_content = "Está tão quieto aqui. Este restaurante está abandonado?",
  ui_story_5033_50330301_65_dialog_content = "... Não!",
  ui_story_5033_50330301_66_dialog_content = "Desça, Corax!",
  ui_story_5033_50330301_67_dialog_content = "<color=#e8d9bb>Whoosh... Bang!</color>",
  ui_story_5033_50330301_68_dialog_content = "Droga, senti falta deles.",
  ui_story_5033_50330301_69_dialog_content = "Fora do caminho. Minha vez!",
  ui_story_5033_50330301_70_dialog_content = "<color=#e8d9bb>Whoosh... Bang!</color>",
  ui_story_5033_50330301_71_dialog_content = "Você novamente?! Nós viemos em paz!",
  ui_story_5033_50330301_72_dialog_content = "Estávamos lentos no empate da última vez.",
  ui_story_5033_50330301_73_dialog_content = "Você irritou as pessoas erradas quando quebrou o braço do chefe.",
  ui_story_5033_50330301_74_dialog_content = "<size=33>Não estamos no lugar certo?</size>",
  ui_story_5033_50330301_75_dialog_content = "<size=33>De jeito nenhum, as informações de Taki nunca estão erradas.</size>",
  ui_story_5033_50330301_76_dialog_content = "<size=33>Provavelmente há mais nessa situação do que pensamos.</size>",
  ui_story_5033_50330301_77_dialog_content = "Deixa para lá. Vamos, precisamos nos defender.",
  ui_story_5033_50330301_78_dialog_content = "Hã?",
  ui_story_5033_50330301_79_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5033_50330301_80_dialog_content = "Você se atreve a lutar de volta?",
  ui_story_5033_50330301_81_dialog_content = "Graah...",
  ui_story_5033_50330301_82_dialog_content = "Eclipsites, em cima da turma? Que bagunça.",
  ui_story_5033_50330301_83_dialog_content = "Devemos nos livrar dos Eclipsitas primeiro!",
  ui_story_5033_50330302_1_dialog_content = "Graah...",
  ui_story_5033_50330302_2_dialog_content = "Há muitos deles. Temos que fazer uma pausa para isso, PlayerName!",
  ui_story_5033_50330302_3_dialog_content = "Para onde?!",
  ui_story_5033_50330302_4_dialog_content = "Vamos sair daqui primeiro!",
  ui_story_5033_50330302_5_dialog_content = "Eles estão fugindo, chefe!",
  ui_story_5033_50330302_6_dialog_content = "Pegue eles!",
  ui_story_5033_50330302_7_dialog_content = "<color=#e8d9bb>Um beco na Euforia</color>",
  ui_story_5033_50330302_8_dialog_content = "Arf, arf...",
  ui_story_5033_50330302_9_dialog_content = "(Não faço ideia de onde estou agora...)",
  ui_story_5033_50330302_10_dialog_content = "Grah!!!",
  ui_story_5033_50330302_11_dialog_content = "(E eu tenho Eclipses na minha cola!)",
  ui_story_5033_50330302_12_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5033_50330302_13_dialog_content = "Hum...",
  ui_story_5033_50330302_14_dialog_content = "Maldições... Retroceda!",
  ui_story_5033_50330302_15_dialog_content = "Ei, como é que os Eclipsites foram atrás deles?",
  ui_story_5033_50330302_16_dialog_content = "<size=45><color=#e8d9bb>Grito!</color></size>",
  ui_story_5033_50330302_17_dialog_content = "Quem está aí?!",
  ui_story_5033_50330302_18_dialog_content = "(Foi um som estranho...)",
  ui_story_5033_50330302_19_dialog_content = "Ah...",
  ui_story_5033_50330302_20_dialog_content = "(Os Eclipses também se foram!)",
  ui_story_5033_50330302_21_dialog_content = "Acabei de sair por um tempo, mas os bandidos tomaram conta da minha base...",
  ui_story_5033_50330302_22_dialog_content = "Vá em frente e me agradeça. Eu conto o resgate como seu primeiro pedido.",
  ui_story_5033_50330302_23_dialog_content = "Sr. <color=#FFB400>Nekoyashiki</color>, presumo?",
  ui_story_5033_50330302_24_dialog_content = "Se não fosse por causa de Taki, eu não estaria lidando com vocês e suas formalidades elegantes.",
  ui_story_5033_50330302_25_dialog_content = "Apenas me chame de Nekoyashiki.",
  ui_story_5033_50330302_26_dialog_content = "O que aconteceu lá? O que foi aquele grito?",
  ui_story_5033_50330302_27_dialog_content = "Para sobrevivência. Não sei por que, mas gritar da maneira certa os afasta.",
  ui_story_5033_50330302_28_dialog_content = "Não sou bom com armas, mas posso pelo menos me defender com alguns gritos contra os Eclipsitas.",
  ui_story_5033_50330302_29_dialog_content = "Em uma pitada, posso até usá-los da maneira que acabei de fazer.",
  ui_story_5033_50330302_30_dialog_content = "Então, vocês confiam em mim agora, amigos de Taki?",
  ui_story_5033_50330302_31_dialog_content = "Isso foi impressionante. Eu acho que é algo privado apenas para você.",
  ui_story_5033_50330302_32_dialog_content = "Par para o curso. Agora me diga o que você quer saber.",
  ui_story_5033_50330302_33_dialog_content = "Eu sou Corax, e isso é PlayerName. Estamos aqui para investigar uma recente cadeia de assassinatos em série em Umbraton.",
  ui_story_5033_50330302_34_dialog_content = "Eu sei muito pouco sobre o assassino agora, exceto por certo modus operandi.",
  ui_story_5033_50330302_35_dialog_content = "Importa-se de dar mais detalhes?",
  ui_story_5033_50330302_36_dialog_content = "Especificamente, todas as vítimas morreram de uma laceração estranha.",
  ui_story_5033_50330302_37_dialog_content = "Um pequeno corte que não deveria ser fatal. As vítimas tropeçavam como um zumbi antes de morrer de repente.",
  ui_story_5033_50330302_38_dialog_content = "(Eles descobriram isso, exatamente como <color=#FFB400>ela</color> previu.)",
  ui_story_5033_50330302_39_dialog_content = "Hmm, essa é uma maneira difícil de ir.",
  ui_story_5033_50330302_40_dialog_content = "Parece que você não deve ser subestimado, se você fosse capaz de traçar seu caminho até aqui apenas a partir disso.",
  ui_story_5033_50330302_41_dialog_content = "Apenas <color=#FFB400>ela</color> conheceria a história associada a essa técnica em toda a Euforia.",
  ui_story_5033_50330302_42_dialog_content = "?!",
  ui_story_5033_50330302_43_dialog_content = "Por favor elabore.",
  ui_story_5033_50330302_44_dialog_content = "Vou levá-lo para ver <color=#FFB400>Sangue de Corvo</color>. Eles sabem mais do que eu.",
  ui_story_5033_50330302_45_dialog_content = "<color=#e8d9bb>Cow, caw...</color>",
  ui_story_5033_50330302_46_dialog_content = "Vejo que os corvos já estão aqui.",
  ui_story_5033_50330302_47_dialog_content = "Isso significa que eles recebem vocês dois, visitantes de Umbraton.",
  ui_story_5033_50330302_48_dialog_content = "<color=#e8d9bb>Em outro beco não muito tempo atrás</color>",
  ui_story_5033_50330302_49_dialog_content = "(Oh não, um beco sem saída!)",
  ui_story_5033_50330302_50_dialog_content = "<color=#e8d9bb>Plop, plop, plop...</color>",
  ui_story_5033_50330302_51_dialog_content = "(Pólux e Casta me seguiram?!)",
  ui_story_5033_50330302_52_dialog_content = "(Eu não quero morrer aqui!)",
  ui_story_5033_50330302_53_dialog_content = "Você insiste em procurar problemas, então agora o problema veio para encontrá-lo.",
  ui_story_5033_50330302_54_dialog_content = "M-Mas eu não fiz nada além de pedir dinheiro aos dois visitantes...",
  ui_story_5033_50330302_55_dialog_content = "Que negócios a Raven's Blood tem com eles?",
  ui_story_5033_50330302_56_dialog_content = "Não pense que vocês podem rastejar até o topo só porque os traficantes obscuros estão caindo como moscas!",
  ui_story_5033_50330302_57_dialog_content = "A euforia nunca se submeterá a vocês duas loucas!",
  ui_story_5033_50330302_58_dialog_content = "É isso que você acha?",
  ui_story_5033_50330302_59_dialog_content = "Não se aproxime! Eu tenho uma faca!",
  ui_story_5033_50330302_60_dialog_content = "Eu disse não se aproxime mais!!",
  ui_story_5033_50330302_61_dialog_content = "Nngh, minha faca! O-o que você pensa que está fazendo?!",
  ui_story_5033_50330302_62_dialog_content = "Um punhal não é suficiente para se proteger. É mais perigoso do que você jamais será.",
  ui_story_5033_50330302_63_dialog_content = "Tente uma arma mais adequada para você na próxima vez.",
  ui_story_5033_50330302_64_dialog_content = "Eu não entendo o que você quer dizer.",
  ui_story_5033_50330302_65_dialog_content = "Acabei de te salvar de todos aqueles Eclipses. Você ainda não entendeu a situação em que se encontra?",
  ui_story_5033_50330302_66_dialog_content = "Você é muito denso para descobrir isso?",
  ui_story_5033_50330302_67_dialog_content = "Os ingratos não vivem muito na euforia.",
  ui_story_5033_50330302_68_dialog_content = "Eca! Mantenha essa faca longe de mim! Ok, eu vou falar, vou te contar tudo o que sei!",
  ui_story_5033_50330302_69_dialog_content = "Você foi enganado para vir aqui sem saber como segurar uma adaga.",
  ui_story_5033_50330302_70_dialog_content = "Vou lhe dar uma pequena noção de quão pouco seu empregador se importa com sua vida.",
  ui_story_5033_50330302_71_dialog_content = "Se eu usar seu pescoço como suporte depende de quão cooperativo você é.",
  ui_story_5033_50330302_72_dialog_content = "Eu disse que vou falar!",
  ui_story_5033_50330302_73_dialog_content = "Muitos moradores como eu foram reunidos para fazer uma emboscada na cidade.",
  ui_story_5033_50330302_74_dialog_content = "Colocar em emboscada?",
  ui_story_5033_50330302_75_dialog_content = "Sim, o chefe não achou que era hora de fazer uma jogada ainda.",
  ui_story_5033_50330302_76_dialog_content = "Ele queria que nos infiltássemos na gangue e nos misturássemos com eles nos bares e mesas de jogo.",
  ui_story_5033_50330302_77_dialog_content = "É só isso?",
  ui_story_5033_50330302_78_dialog_content = "Você nunca se perguntou o que eles queriam que você fizesse a seguir?",
  ui_story_5033_50330302_79_dialog_content = "M-Mova a lâmina para longe!",
  ui_story_5033_50330302_80_dialog_content = "Certo, então ouvi algo circulando pela gangue alguns dias atrás.",
  ui_story_5033_50330302_81_dialog_content = "Quem nos contratou queria que espalhássemos alguns <color=#FFB400>rumores</color> pela cidade.",
  ui_story_5033_50330302_82_dialog_content = "Isso é tudo que eu sei, eu juro! Eu nem sei que tipo de rumores!",
  ui_story_5033_50330302_83_dialog_content = "Entendi.",
  ui_story_5033_50330302_84_dialog_content = "Você não vai me deixar ir? Eu te disse tudo o que sei!",
  ui_story_5033_50330302_85_dialog_content = "Deixe-me oferecer-lhe outra lição sobre a casa sobre sobreviver em Euphoria...",
  ui_story_5033_50330302_86_dialog_content = "Não confie em ninguém aqui.",
  ui_story_5033_50330302_87_dialog_content = "Ah!",
  ui_story_5033_50330302_88_dialog_content = "Toda vez, você apenas os derruba e os joga no lixo.",
  ui_story_5033_50330302_89_dialog_content = "Se as pessoas descobrissem que o estimado Pólux era realmente tão misericordioso...",
  ui_story_5033_50330302_90_dialog_content = "Como eles ainda podiam acreditar na reputação associada ao nome?",
  ui_story_5033_50330302_91_dialog_content = "Eles não deveriam. É melhor não confiar em ninguém na Euphoria. Especialmente eu.",
  ui_story_5033_50330302_92_dialog_content = "<color=#e8d9bb>Cow, caw...</color>",
  ui_story_5033_50330302_93_dialog_content = "Hmm, algo está acontecendo do lado de Nekoyashiki.",
  ui_story_5033_50330302_94_dialog_content = "Sim, eles rastrearam Nekoyashiki como eu previa.",
  ui_story_5033_50330302_95_dialog_content = "Embora mais cedo do que eu pensava.",
  ui_story_5033_50330302_96_dialog_content = "Vamos para o <color=#FFB400>lugar de sempre</color> e esperar por Nekoyashiki e os dois convidados de Umbraton como falamos.",
  ui_story_5033_50330302_97_dialog_content = "Isso não é nada de você, Pollux. Mais uma vez, por que estamos nos encontrando com eles?",
  ui_story_5033_50330302_98_dialog_content = "Eu tenho um motivo oculto. Eu sei que o Shadowlord os enviou.",
  ui_story_5033_50330302_99_dialog_content = "É sobre as <color=#FFB400>crianças</color>?",
  ui_story_5033_50330302_100_dialog_content = "As crianças, e a Euforia também, é claro.",
  ui_story_5033_50330302_101_dialog_content = "Estou esperando uma tempestade chegar e lavar a sujeira.",
  ui_story_5033_50330302_102_dialog_content = "Casta—",
  ui_story_5033_50330302_103_dialog_content = "Claro?",
  ui_story_5033_50330302_104_dialog_content = "Quando o céu de Euphoria se tornou um cinza lamacento perpétuo?",
  ui_story_5033_50330302_105_dialog_content = "Milímetros...",
  ui_story_5033_50330302_106_dialog_content = "Quando começou, eu me pergunto?",
  ui_story_5033_50330401_1_dialog_content = "O Sangue do Corvo que você mencionou... É uma das muitas gangues da Euphoria?",
  ui_story_5033_50330401_2_dialog_content = "Na verdade, você tomou a decisão certa de procurar minha ajuda.",
  ui_story_5033_50330401_3_dialog_content = "Se você tivesse ido para qualquer outra pessoa, você teria que pular aros para encontrar o Sangue de Raven.",
  ui_story_5033_50330401_4_dialog_content = "A gangue é composta por apenas duas mulheres: <color=#FFB400>Pollux</color> e <color=#FFB400>Casta</color>, mas elas ainda são páreo para as principais gangues.",
  ui_story_5033_50330401_5_dialog_content = "Pollux não é de lutas de poder entre gangues. Há apenas um punhado de pessoas capazes de encontrá-los.",
  ui_story_5033_50330401_6_dialog_content = "Pollux é a \"ela\" que você mencionou?",
  ui_story_5033_50330401_7_dialog_content = "Sim.",
  ui_story_5033_50330401_8_dialog_content = "Ela sabia da sua chegada em Euphoria e estava esperando que você viesse até mim.",
  ui_story_5033_50330401_9_dialog_content = "Mais ouvidos no chão é essencial para a sobrevivência aqui, certo?",
  ui_story_5033_50330401_10_dialog_content = "Ha, você não vai me pegar argumentando contra isso, especialmente com visitantes de tal prestígio.",
  ui_story_5033_50330401_11_dialog_content = "De qualquer forma, ela me disse para trazer vocês para ela eu mesmo. Para o \"local de sempre\", como ela disse.",
  ui_story_5033_50330401_12_dialog_content = "Espero que ela seja útil na minha investigação.",
  ui_story_5033_50330401_13_dialog_content = "Você está suspeitando dela?",
  ui_story_5033_50330401_14_dialog_content = "Calma, não vou prender ninguém sem motivo.",
  ui_story_5033_50330401_15_dialog_content = "Mesmo que eu tenha um suspeito em mente, ainda quero provas concretas antes de prender alguém.",
  ui_story_5033_50330401_16_dialog_content = "Por quê? O que você está esperando, outra vítima para ser cortada?",
  ui_story_5033_50330401_17_dialog_content = "Eu nunca desejaria que mais pessoas inocentes fossem vítimas.",
  ui_story_5033_50330401_18_dialog_content = "Este é um assunto muito sério, Sr. Nekoyashiki. Espero que você possa tratá-lo com algum respeito.",
  ui_story_5033_50330401_19_dialog_content = "Meu, meu, você tem um pau na bunda, não é? Só acho sua suspeita absurda.",
  ui_story_5033_50330401_20_dialog_content = "Isso não parece muito convincente vindo de mim, já que sou amigo deles, hein?",
  ui_story_5033_50330401_21_dialog_content = "De qualquer forma, vou levá-lo para onde eles estão esperando primeiro.",
  ui_story_5033_50330401_22_dialog_content = "Então você pode decidir por si mesmo.",
  ui_story_5033_50330401_23_dialog_content = "(Ele parece muito seguro de sua inocência...)",
  ui_story_5033_50330401_24_dialog_content = "Então, onde é esse lugar que você está falando?",
  ui_story_5033_50330401_25_dialog_content = "Ah, estamos quase lá.",
  ui_story_5033_50330401_26_dialog_content = "Estamos indo para uma <color=#FFB400>antiga igreja</color>. Costumava ser um espetáculo para ser visto, antes de ser abandonado.",
  ui_story_5033_50330401_27_dialog_content = "(Uma igreja?)",
  ui_story_5033_50330401_28_dialog_content = "As freiras não têm mais lugar na Euforia.",
  ui_story_5033_50330401_29_dialog_content = "(As freiras se foram, mas a igreja ainda está aqui, hein?)",
  ui_story_5033_50330401_30_dialog_content = "<color=#e8d9bb>Euforia: A Igreja Antiga</color>",
  ui_story_5033_50330401_31_dialog_content = "É tão degradado como todos os outros edifícios.",
  ui_story_5033_50330401_32_dialog_content = "E como todos os outros prédios, só serve para abrigo.",
  ui_story_5033_50330401_33_dialog_content = "A euforia nunca teve um salvador, e ninguém aqui reza mais para o deus da luz.",
  ui_story_5033_50330401_34_dialog_content = "A cidade foi limpa de freiras nos últimos anos. Esta igreja não pertence mais a nenhuma denominação.",
  ui_story_5033_50330401_35_dialog_content = "As freiras foram expurgadas? Por quem?",
  ui_story_5033_50330401_36_dialog_content = "Se eu soubesse, não teria vivido o suficiente para estar aqui hoje.",
  ui_story_5033_50330401_37_dialog_content = "Talvez fosse apenas o destino deles. Você não negocia com a Morte.",
  ui_story_5033_50330401_38_dialog_content = "O onipresente Grim Reaper arrebata sua vida alguns dias depois!",
  ui_story_5033_50330401_39_dialog_content = "Eles devem ter morrido por causa do Ceifador, de quem não se fala!",
  ui_story_5033_50330401_40_dialog_content = "(Isso soa exatamente como o que aquele homem disse...)",
  ui_story_5033_50330401_41_dialog_content = "(Os assassinatos em série, as freiras massacradas... Será tudo obra do Ceifador?)",
  ui_story_5033_50330401_42_dialog_content = "Falando nisso, encontramos uma freira no caminho para cá.",
  ui_story_5033_50330401_43_dialog_content = "Nos despedimos depois de chegar. Eu me pergunto como ela está agora.",
  ui_story_5033_50330401_44_dialog_content = "O que? Isso é verdade?!",
  ui_story_5033_50330401_45_dialog_content = "Sim, ela veio conosco de Umbraton. Ela era obviamente uma freira.",
  ui_story_5033_50330401_46_dialog_content = "(Uma freira de Umbraton?)",
  ui_story_5033_50330401_47_dialog_content = "Devias avisar ao Raven's Blood quando os encontrares. Tenho certeza que eles ficarão felizes em ouvir isso.",
  ui_story_5033_50330401_48_dialog_content = "<color=#e8d9bb>Enquanto isso, em outro beco</color>",
  ui_story_5033_50330401_49_dialog_content = "...?",
  ui_story_5033_50330401_50_dialog_content = "O que há de errado, Pólux?",
  ui_story_5033_50330401_51_dialog_content = "Não me diga que esses punks ainda estão por aí.",
  ui_story_5033_50330401_52_dialog_content = "Não, não são eles.",
  ui_story_5033_50330401_53_dialog_content = "Mas é a única coisa que tenho certeza. O rastro vem e vai, que está além deles.",
  ui_story_5033_50330401_54_dialog_content = "Ninguém em Euphoria pode fazer isso.",
  ui_story_5033_50330401_55_dialog_content = "Relaxar. Pode ser apenas um gato.",
  ui_story_5033_50330401_56_dialog_content = "Venha, vamos. As crianças estão esperando, e Nekoyashiki deve aparecer em breve.",
  ui_story_5033_50330401_57_dialog_content = "Vá em frente. Quero voltar para aquele distrito comercial.",
  ui_story_5033_50330401_58_dialog_content = "Eu realmente não acho que esses punks valem o seu tempo.",
  ui_story_5033_50330401_59_dialog_content = "Quem se importa com eles?",
  ui_story_5033_50330401_60_dialog_content = "Eu só quero fazer algumas surpresas para as crianças.",
  ui_story_5033_50330401_61_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330401_62_dialog_content = "...",
  ui_story_5033_50330401_63_dialog_content = "(Ela... sentiu minha presença?)",
  ui_story_5033_50330401_64_dialog_content = "<color=#e8d9bb>Miau...</color>",
  ui_story_5033_50330401_65_dialog_content = "Miau!",
  ui_story_5033_50330401_66_dialog_content = "Mate Pólux.",
  ui_story_5033_50330401_67_dialog_content = "...",
  ui_story_5033_50330401_68_dialog_content = "(... A paciência é uma virtude esquecida, ao que parece.)",
  ui_story_5033_50330401_69_dialog_content = "<color=#e8d9bb>*Rasga o papel*</color>",
  ui_story_5033_50330401_70_dialog_content = "Hã?",
  ui_story_5033_50330401_71_dialog_content = "<size=45>Ah!</size>",
  ui_story_5033_50330401_72_dialog_content = "(No momento ideal.)",
  ui_story_5033_50330401_73_dialog_content = "(Eu vou destruir você junto com este pedaço de lixo.)",
  ui_story_5033_50330502_1_dialog_content = "<color=#e8d9bb>Gangue Istvan em Umbraton</color>",
  ui_story_5033_50330502_2_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5033_50330502_3_dialog_content = "Parece que vem uma tempestade.",
  ui_story_5033_50330502_4_dialog_content = "Um monte de nuvens, o que significa que a sombra se espalhará por Umbraton.",
  ui_story_5033_50330502_5_dialog_content = "É apenas uma questão de tempo antes de atingir a Euphoria também.",
  ui_story_5033_50330502_6_dialog_content = "Está preocupado com a investigação de Corax?",
  ui_story_5033_50330502_7_dialog_content = "Não.",
  ui_story_5033_50330502_8_dialog_content = "Estou apenas esperando o tempo mudar.",
  ui_story_5033_50330502_9_dialog_content = "Nos últimos dias, ganhei uma nova perspectiva sobre o caso de Corax.",
  ui_story_5033_50330502_10_dialog_content = "Mas ainda não tenho provas definitivas, então é apenas especulação pessoal.",
  ui_story_5033_50330502_11_dialog_content = "Sem problemas. Vamos ouvir isso.",
  ui_story_5033_50330502_12_dialog_content = "Só percebi enquanto escaneava jornais velhos.",
  ui_story_5033_50330502_13_dialog_content = "Quatorze anos atrás, algo aconteceu em Euphoria que causou um grande alvoroço em Umbraton.",
  ui_story_5033_50330502_14_dialog_content = "Na época, o local era mais conhecido como \"País das Maravilhas\".",
  ui_story_5033_50330502_15_dialog_content = "Você provavelmente sabe sobre o incidente melhor do que eu.",
  ui_story_5033_50330502_16_dialog_content = "Hmm, eu me lembro do <color=#FFB400>Incidente de Gêmeos</color>...",
  ui_story_5033_50330502_17_dialog_content = "Sim. Foi quando a luta clandestina era a moda em Euphoria e deixou muita gente rica.",
  ui_story_5033_50330502_18_dialog_content = "Até o capitão dos mercenários em Euphoria deixou de depender de comissões por dinheiro.",
  ui_story_5033_50330502_19_dialog_content = "Isso não é nada incomum. As únicas comissões que restaram para eles provavelmente estavam lutando naquelas arenas subterrâneas, de qualquer maneira.",
  ui_story_5033_50330502_20_dialog_content = "Que ironia.",
  ui_story_5033_50330502_21_dialog_content = "De qualquer forma, alguém estava puxando as cordas nos bastidores e, sob suas ordens, o capitão treinou duas estrelas em ascensão.",
  ui_story_5033_50330502_22_dialog_content = "Eram duas meninas muito jovens treinadas sob dois regimes totalmente diferentes pelo capitão...",
  ui_story_5033_50330502_23_dialog_content = "Um passou por treinamento interno de mercenários e se especializou em seu estilo de luta.",
  ui_story_5033_50330502_24_dialog_content = "A outra se juntou a outros mercenários no campo em combate real, treinando sua adaptabilidade para todas as situações.",
  ui_story_5033_50330502_25_dialog_content = "Euphoria os chamou de gêmeos Gêmeos do grupo mercenário.",
  ui_story_5033_50330502_26_dialog_content = "No entanto, o primeiro show oficial que eles conseguiram ...",
  ui_story_5033_50330502_27_dialog_content = "Foi uma <color=#FFB400>luta até a morte</color> uns contra os outros em uma arena.",
  ui_story_5033_50330502_28_dialog_content = "Deixe-me adivinhar. Não houve nenhum show de histeria emocional e um matou o outro à queima-roupa, certo?",
  ui_story_5033_50330502_29_dialog_content = "Sim.",
  ui_story_5033_50330502_30_dialog_content = "Não há relatos de como a luta aconteceu, mas de acordo com as fofocas de testemunhas oculares...",
  ui_story_5033_50330502_31_dialog_content = "A criança que sobreviveu ficou gravemente ferida com pequenas lacerações por todo o corpo. Ela estava praticamente morta.",
  ui_story_5033_50330502_32_dialog_content = "Após esse incidente, ela desapareceu completamente, para nunca mais ser vista.",
  ui_story_5033_50330502_33_dialog_content = "O público perdeu o interesse por ela no caos que atingiu Umbraton alguns anos depois, de qualquer maneira.",
  ui_story_5033_50330502_34_dialog_content = "Você acha que a garota que morreu na verdade <color=#FFB400>ainda vive</color>.",
  ui_story_5033_50330502_35_dialog_content = "Sim.",
  ui_story_5033_50330502_36_dialog_content = "Isso é muito simples, não é? Não estou duvidando que ela não poderia ter sobrevivido, só que...",
  ui_story_5033_50330502_37_dialog_content = "Não podemos ter certeza de que ela é a única que conhece essa técnica.",
  ui_story_5033_50330502_38_dialog_content = "Afinal, Euphoria não é mais o lugar que costumava ser.",
  ui_story_5033_50330502_39_dialog_content = "Antes da Crise de Darkover, aquela companhia mercenária ostentava alguns membros que podiam exercer essas habilidades, e eles ensinavam outros...",
  ui_story_5033_50330502_40_dialog_content = "São muitos suspeitos em potencial.",
  ui_story_5033_50330502_41_dialog_content = "Você está certo, e é por isso que isso é apenas especulação.",
  ui_story_5033_50330502_42_dialog_content = "No entanto, digamos que houve um sobrevivente daquela partida de morte malfadada, e eles viveram anonimamente até agora.",
  ui_story_5033_50330502_43_dialog_content = "Não seria uma coisa boa para Umbraton ou Euphoria.",
  ui_story_5033_50330502_44_dialog_content = "Você sabe qual é a coisa mais difícil para um participante regular de lutas clandestinas?",
  ui_story_5033_50330502_45_dialog_content = "Não é sobrevivência, é? Uma vez que a vida e a morte são apenas par para o curso lá.",
  ui_story_5033_50330502_46_dialog_content = "Está prontamente cortando os tecidos podres do seu corpo.",
  ui_story_5033_50330502_47_dialog_content = "Algo tão simples?",
  ui_story_5033_50330502_48_dialog_content = "Porque o tecido velho impede a formação de tecido saudável.",
  ui_story_5033_50330502_49_dialog_content = "Com o tempo, arruína seu físico e rouba o privilégio de competir.",
  ui_story_5033_50330502_50_dialog_content = "Isso seria um trabalho para um médico, certo?",
  ui_story_5033_50330502_51_dialog_content = "Eu teria o médico em quem mais confiava para lidar com isso.",
  ui_story_5033_50330502_52_dialog_content = "Mas, novamente, a outra garota supostamente também não sobreviveu?",
  ui_story_5033_50330502_53_dialog_content = "No mínimo, isso prova que nem todos que são submetidos a essa técnica de lâmina morrem.",
  ui_story_5033_50330502_54_dialog_content = "<color=#e8d9bb>Bata, bate, bate—</color>",
  ui_story_5033_50330502_55_dialog_content = "Tio Istvan? A vítima que Corax encontrou... Ele está acordado agora.",
  ui_story_5033_50330502_56_dialog_content = "Ah, fale do diabo.",
  ui_story_5033_50330601_1_dialog_content = "Fale.",
  ui_story_5033_50330601_2_dialog_content = "<color=#828282>Crec...</color>",
  ui_story_5033_50330601_3_dialog_content = "Olha, todo mundo! Nekoyashiki está de volta!",
  ui_story_5033_50330601_4_dialog_content = "Silêncio. Não tão alto, Latan. Estou procurando Casta, você a viu?",
  ui_story_5033_50330601_5_dialog_content = "Casta saiu para pegar o pão. Você quer que eu vá buscá-la?",
  ui_story_5033_50330601_6_dialog_content = "Vá dizer a ela que temos convidados de Umbraton.",
  ui_story_5033_50330601_7_dialog_content = "Ok! Você pode brincar com os outros enquanto eu vou buscá-la!",
  ui_story_5033_50330601_8_dialog_content = "Você nos trouxe alguma guloseima, Nekoyashiki?",
  ui_story_5033_50330601_9_dialog_content = "De nada.",
  ui_story_5033_50330601_10_dialog_content = "Venha aqui, Nekoyashiki! Abaixe-se, encontrei algo legal para você!",
  ui_story_5033_50330601_11_dialog_content = "E-ei, não me puxe assim, garoto...",
  ui_story_5033_50330601_12_dialog_content = "Uau... Por que há tantas crianças aqui?",
  ui_story_5033_50330601_13_dialog_content = "Esses garotos foram todos levados pelo Raven's Blood, e... Ai! Ei, para que você está puxando meu cabelo?!",
  ui_story_5033_50330601_14_dialog_content = "Heehe! Olha, eu encontrei essa barata outro dia! Não foi fácil pegar... Você gostou?",
  ui_story_5033_50330601_15_dialog_content = "Seu pequeno patife, venha aqui!",
  ui_story_5033_50330601_16_dialog_content = "Oh não, Nekoyashiki é louco! Fugir!!",
  ui_story_5033_50330601_17_dialog_content = "Parece que ele não tem tempo para me explicar as coisas agora.",
  ui_story_5033_50330601_18_dialog_content = "Não há muito o que explicar.",
  ui_story_5033_50330601_19_dialog_content = "A maioria dessas crianças acabou aqui depois de serem abandonadas nas ruas.",
  ui_story_5033_50330601_20_dialog_content = "Alguns ficaram órfãos depois que seus pais foram mortos pela violência de gangues, e outros foram resgatados do submundo do crime.",
  ui_story_5033_50330601_21_dialog_content = "Até que um lar seguro e adequado seja encontrado para eles, essas crianças estão sob a proteção do Raven's Blood. Somos nós.",
  ui_story_5033_50330601_22_dialog_content = "Você deve ser o Casta que Nekoyashiki mencionou.",
  ui_story_5033_50330601_23_dialog_content = "Nós estamos-",
  ui_story_5033_50330601_24_dialog_content = "Não há necessidade de apresentações; sabemos exatamente por que você está aqui e o que está investigando. Vamos esperar Pollux voltar antes de conversarmos.",
  ui_story_5033_50330601_25_dialog_content = "Eu ainda preciso alimentar esses patifes.",
  ui_story_5033_50330601_26_dialog_content = "Isso é bom. Não nos importamos de esperar.",
  ui_story_5033_50330601_27_dialog_content = "Tudo bem, todos! Está quase na hora da soneca, então termine de comer seu pão e vá direto para a cama!",
  ui_story_5033_50330601_28_dialog_content = "Beleza!",
  ui_story_5033_50330601_29_dialog_content = "*Estremecendo* Eles finalmente soltam meu cabelo... Essas crianças são outra coisa.",
  ui_story_5033_50330601_30_dialog_content = "Se você terminou, vamos continuar nossa conversa.",
  ui_story_5033_50330601_31_dialog_content = "Já que sou o membro do Odd Jobs, vou colocar todos a par da situação.",
  ui_story_5033_50330601_32_dialog_content = "Em relação aos nossos dois convidados aqui, eu entendo que Taki apontou você na minha direção.",
  ui_story_5033_50330601_33_dialog_content = "No entanto, Raven's Blood tem muito mais conhecimento sobre Euphoria e pode ajudá-lo muito mais do que eu.",
  ui_story_5033_50330601_34_dialog_content = "Quanto a vocês, senhoras do Raven's Blood, eu trouxe as pessoas que vocês pediram, então agora vou deixar o resto com vocês.",
  ui_story_5033_50330601_35_dialog_content = "Vou embora agora, pois ainda tenho outros assuntos a tratar.",
  ui_story_5033_50330601_36_dialog_content = "Apenas vá, não venha nos incomodar com sua presença irritante. Ligaremos para você se precisarmos de você.",
  ui_story_5033_50330601_37_dialog_content = "Ai, isso dói. Me jogar de lado quando terminar de me usar?",
  ui_story_5033_50330601_38_dialog_content = "Você é o único que disse que estava saindo, então saia já. Ainda tenho pão para servir.",
  ui_story_5033_50330601_39_dialog_content = "Deixa eu te ajudar, Casta!",
  ui_story_5033_50330601_40_dialog_content = "Eu também posso ajudar! Eu também posso ajudar!",
  ui_story_5033_50330601_41_dialog_content = "Tudo bem, então. Latan, você pode dividir este pão entre as crianças mais novas. Schewe, você pode distribuir a manteiga e garantir que os pequenos recebam mais.",
  ui_story_5033_50330601_42_dialog_content = "Sim!",
  ui_story_5033_50330601_43_dialog_content = "Claro, eu sei onde está a manteiga. Eu vou buscá-lo!",
  ui_story_5033_50330601_44_dialog_content = "Desculpe, mas tenho que perguntar... Como as crianças sofreram esses ferimentos?",
  ui_story_5033_50330601_45_dialog_content = "Você achou que os órfãos sem-teto teriam facilidade nas ruas de Euphoria?",
  ui_story_5033_50330601_46_dialog_content = "Eles foram feridos por outras pessoas, então fizemos curativos em suas feridas... Simples assim.",
  ui_story_5033_50330601_47_dialog_content = "Você se importaria se eu desse uma olhada em seus ferimentos? Era uma vez um médico.",
  ui_story_5033_50330601_48_dialog_content = "Um médico, hein?",
  ui_story_5033_50330601_49_dialog_content = "Posso ver que suas feridas foram embrulhadas com muito cuidado e as bandagens estão bem limpas.",
  ui_story_5033_50330601_50_dialog_content = "Mas algumas das crianças parecem um pouco pior para o desgaste. Eles vão exigir alguma atenção extra.",
  ui_story_5033_50330601_51_dialog_content = "Heh, deve ser nosso dia de sorte. Você terá que esperar até que eles terminem de comer, no entanto.",
  ui_story_5033_50330601_52_dialog_content = "(Hmm? Alguém está puxando minha mão?)",
  ui_story_5033_50330601_53_dialog_content = "Sim? Tem algo errado, garotinha?",
  ui_story_5033_50330601_54_dialog_content = "Hum... N-Nekoyashiki disse que deixou alguns doces no seu bolso...",
  ui_story_5033_50330601_55_dialog_content = "A-E que eu deveria te perguntar se eu quero um pouco.",
  ui_story_5033_50330601_56_dialog_content = "Quando Nekoyashiki colocou doces no meu bolso? Por que eu não sabia disso...",
  ui_story_5033_50330601_57_dialog_content = "Huh? Olhe para isso. Realmente há doces no meu bolso!",
  ui_story_5033_50330601_58_dialog_content = "E-então... Posso tomar um pouco?",
  ui_story_5033_50330601_59_dialog_content = "Claro que você pode! Aqui está. Desculpe mantê-lo esperando.",
  ui_story_5033_50330601_60_dialog_content = "Obrigada!",
  ui_story_5033_50330601_61_dialog_content = "Ei! Não coma tantos doces logo antes de uma refeição!",
  ui_story_5033_50330601_62_dialog_content = "Ah... Tá bom.",
  ui_story_5033_50330601_63_dialog_content = "<color=#e8d9bb>Grrido...</color>",
  ui_story_5033_50330601_64_dialog_content = "Com fome?",
  ui_story_5033_50330601_65_dialog_content = "S-Desculpe. Toda aquela correria abriu o apetite. Eu não posso fazer nada sobre meu estômago roncando, infelizmente.",
  ui_story_5033_50330601_66_dialog_content = "Mas prometo que não estou aqui para roubar pão das crianças.",
  ui_story_5033_50330601_67_dialog_content = "Hah, vocês dois são uma dupla bastante interessante. Um médico que virou assassino e uma criança no corpo de um adolescente.",
  ui_story_5033_50330601_68_dialog_content = "Talvez Pollux estivesse certo em convidá-lo aqui, afinal.",
  ui_story_5033_50330601_69_dialog_content = "Concedido, é sempre mais inteligente trabalhar com o pessoal da Umbraton do que contra eles.",
  ui_story_5033_50330601_70_dialog_content = "Esse cheiro - é croissants!",
  ui_story_5033_50330601_71_dialog_content = "Isso mesmo, e eu trouxe bastante para todos, então todos vocês podem comer o suficiente hoje.",
  ui_story_5033_50330601_72_dialog_content = "Vá cumprimentar nossos convidados, Pollux. Eu mesmo posso entregar isso. Tudo bem, quem quiser um croissant, vem comigo!",
  ui_story_5033_50330601_73_dialog_content = "Beleza!",
  ui_story_5033_50330601_74_dialog_content = "Vocês dois são mais do que bem-vindos para ter alguns também.",
  ui_story_5033_50330601_75_dialog_content = "Obrigado, vamos nos ajudar então.",
  ui_story_5033_50330601_76_dialog_content = "Aqui, PlayerName.",
  ui_story_5033_50330601_77_dialog_content = "Th-Obrigado...",
  ui_story_5033_50330601_78_dialog_content = "Desculpe, eu deveria ajudar, mas tudo que fiz foi tornar as coisas mais difíceis.",
  ui_story_5033_50330601_79_dialog_content = "Não seja tão duro consigo mesmo.",
  ui_story_5033_50330601_80_dialog_content = "Afinal, encontramos alguém com quem podemos trabalhar aqui em quem podemos confiar. Isso é muito melhor do que eu esperava.",
  ui_story_5033_50330601_81_dialog_content = "Milímetros. Alguém que administraria um abrigo em Euphoria só para crianças...",
  ui_story_5033_50330601_82_dialog_content = "Aposto que eles não são apenas super fortes. Eles também devem ser muito gentis.",
  ui_story_5033_50330601_83_dialog_content = "Você nos lisonjeia. Mas, na verdade, cuidar de todas essas crianças não é tarefa fácil.",
  ui_story_5033_50330601_84_dialog_content = "Você não considerou enviá-los para um lugar melhor?",
  ui_story_5033_50330601_85_dialog_content = "Umbraton tem muitos orfanatos com todas as comodidades que eles podem precisar.",
  ui_story_5033_50330601_86_dialog_content = "Claro que já pensamos nisso. É por isso que decidimos trabalhar com você.",
  ui_story_5033_50330601_87_dialog_content = "Mas nem todos são capazes de ver os órfãos de Euphoria como qualquer outra criança. Preciso encontrar um lugar disposto a aceitá-los.",
  ui_story_5033_50330601_88_dialog_content = "Entendi.",
  ui_story_5033_50330601_89_dialog_content = "Nem todas as crianças estão dispostas a deixar este lugar. Além disso, Euphoria e Umbraton não têm se dado bem ultimamente...",
  ui_story_5033_50330601_90_dialog_content = "Eu gostaria de esperar até que as coisas se acalmem antes de encontrar soluções de longo prazo.",
  ui_story_5033_50330601_91_dialog_content = "Eu entendo. No que diz respeito às crianças, posso garantir que a Umbraton as receberá de braços abertos.",
  ui_story_5033_50330601_92_dialog_content = "E já que vamos investigar as coisas por um tempo, talvez possamos dar uma mãozinha por aqui também?",
  ui_story_5033_50330601_93_dialog_content = "Oh, certo! Quando a freira chegar aqui, talvez ela possa ajudar com as crianças.",
  ui_story_5033_50330601_94_dialog_content = "Freira? Você está dizendo que a igreja enviou uma freira para nossa igreja?",
  ui_story_5033_50330601_95_dialog_content = "Eu penso que sim. Enquanto estávamos no dirigível para Euphoria, encontramos uma freira que disse que estava vindo para cá.",
  ui_story_5033_50330601_96_dialog_content = "Honestamente, eu pensei que ela já estaria aqui...",
  ui_story_5033_50330601_97_dialog_content = "A Euphoria não vê uma freira há muito tempo. Talvez eles simplesmente não desejem vir.",
  ui_story_5033_50330601_98_dialog_content = "Mas esta igreja ainda está de pé. Mesmo que seja um pouco decrépito, não acho que isso os impediria de querer vir aqui.",
  ui_story_5033_50330601_99_dialog_content = "Sabe, foi uma freira que me deu meu nome quando me encontrou vagando pelas ruas de Euphoria há muito tempo.",
  ui_story_5033_50330601_100_dialog_content = "Mas depois que saí da igreja, perdi contato com ela.",
  ui_story_5033_50330601_101_dialog_content = "Então, cerca de oito ou nove anos atrás, ouvi dizer que ela resgatou um monte de crianças do caos. Ela foi para Umbraton na esperança de economizar mais, apenas para morrer em um acidente no caminho.",
  ui_story_5033_50330601_102_dialog_content = "Como resultado, esta igreja caiu em desuso e até vandalismo.",
  ui_story_5033_50330601_103_dialog_content = "E foi aí que vocês dois...",
  ui_story_5033_50330601_104_dialog_content = "Correto. Foi quando Casta e eu estabelecemos a Raven's Blood e decidimos consertar este lugar para que pudesse receber crianças errantes mais uma vez.",
  ui_story_5033_50330601_105_dialog_content = "Mas se a igreja enviou uma nova freira para assumir o controle, então talvez seja melhor.",
  ui_story_5033_50330601_106_dialog_content = "\"Tudo do melhor\"? Você não pode estar falando sério, certo, Pollux?",
  ui_story_5033_50330601_107_dialog_content = "Eu pensei... Achei que você diria que por nós, ninguém jamais tomaria o lugar da <color=#FFB400>Irmã Matilda</color>.",
  ui_story_5033_50330601_108_dialog_content = "Ninguém a está substituindo, Casta.",
  ui_story_5033_50330601_109_dialog_content = "Parece que vocês dois têm um vínculo emocional muito forte com essa Irmã Matilda.",
  ui_story_5033_50330601_110_dialog_content = "Eu mesmo sou um órfão eufórico. Irmã Matilda foi quem me acolheu.",
  ui_story_5033_50330601_111_dialog_content = "Se não fosse por ela, não há como dizer o que as gangues daqui teriam feito comigo. Quanto a Pollux...",
  ui_story_5033_50330601_112_dialog_content = "Isso é o suficiente para relembrar por um dia, Casta. É a nossa vez de ouvir o Sr. Corax e saber sobre sua investigação.",
  ui_story_5033_50330601_113_dialog_content = "Eu já sei a essência do que está acontecendo, graças a Nekoyashiki.",
  ui_story_5033_50330601_114_dialog_content = "Uma série de assassinatos misteriosos ocorreram em Umbraton, e você suspeita que o assassino está de alguma forma ligado à Euphoria.",
  ui_story_5033_50330601_115_dialog_content = "Acho que vocês dois estarão mais do que dispostos a me ajudar assim que souberem de mais detalhes sobre minha investigação.",
  ui_story_5033_50330601_116_dialog_content = "Por quê?",
  ui_story_5033_50330601_117_dialog_content = "Dói-me dizer-lhe... Mas a Irmã Matilda não morreu num acidente.",
  ui_story_5033_50330601_118_dialog_content = "Aprendemos com a igreja local que as feridas misteriosas em seu corpo eram exatamente as mesmas das outras vítimas do caso.",
  ui_story_5033_50330601_119_dialog_content = "O quê?!",
  ui_story_5033_50330601_120_dialog_content = "<color=#e8d9bb>*Estilhaçar*</color>",
  ui_story_5033_50330601_121_dialog_content = "<size=45>O que você disse agora?! Diga de novo!</size>",
  ui_story_5033_50330601_122_dialog_content = "Por favor, acalme-se, você está assustando as crianças.",
  ui_story_5033_50330601_123_dialog_content = "...",
  ui_story_5033_50330601_124_dialog_content = "E-está tudo bem pessoal, não tenham medo... Casta ficou um pouco nervosa, só isso.",
  ui_story_5033_50330601_125_dialog_content = "Desculpas, crianças. Acabamos de receber uma notícia muito chocante.",
  ui_story_5033_50330601_126_dialog_content = "Nós, adultos, vamos sair para continuar nossa conversa. Venha nos encontrar se precisar de alguma coisa, e certifique-se de comer toda a sua comida, ok?",
  ui_story_5033_50330601_127_dialog_content = "Tá bom...",
  ui_story_5033_50330601_128_dialog_content = "As crianças ainda parecem um pouco abaladas. Vou ficar e fazer-lhes companhia.",
  ui_story_5033_50330601_129_dialog_content = "Obrigada, PlayerName.",
  ui_story_5033_50330601_130_dialog_content = "Vamos lá. Ainda temos <size=45>muito o que discutir</size>.",
  ui_story_5033_50330701_1_dialog_content = "Mastigar, mastigar, mastigar...",
  ui_story_5033_50330701_2_dialog_content = "...",
  ui_story_5033_50330701_3_dialog_content = "Por que você não está comendo, Latan?",
  ui_story_5033_50330701_4_dialog_content = "Você continua olhando para fora. Você está preocupado com eles?",
  ui_story_5033_50330701_5_dialog_content = "Sim... Quase nunca vemos Casta tão brava.",
  ui_story_5033_50330701_6_dialog_content = "Ou Pollux... Embora ela parecesse muito mais calma do que Casta, eu poderia dizer que ela estava furiosa.",
  ui_story_5033_50330701_7_dialog_content = "Algo muito, muito ruim deve ter acontecido.",
  ui_story_5033_50330701_8_dialog_content = "Você descobriu tudo isso por si mesmo, hein?",
  ui_story_5033_50330701_9_dialog_content = "(Que criança perspicaz ela é.)",
  ui_story_5033_50330701_10_dialog_content = "Sim eu fiz.",
  ui_story_5033_50330701_11_dialog_content = "Normalmente, não importa o que aconteça ou que tipo de notícias Nekoyashiki traz para eles,",
  ui_story_5033_50330701_12_dialog_content = "eles nunca mostram qualquer sinal de estar chateado. Não na nossa frente, pelo menos.",
  ui_story_5033_50330701_13_dialog_content = "Essa foi a primeira vez que os vimos com tanta raiva, ou os ouvimos gritar assim.",
  ui_story_5033_50330701_14_dialog_content = "Não se preocupe muito com isso, ok? Assim que descobrirmos tudo, tenho certeza de que eles não ficarão mais bravos.",
  ui_story_5033_50330701_15_dialog_content = "Será que... Tem algo a ver com a Irmã <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330701_16_dialog_content = "Você também ouviu isso?",
  ui_story_5033_50330701_17_dialog_content = "Uh-huh, eu estava ouvindo vocês o tempo todo.",
  ui_story_5033_50330701_18_dialog_content = "Bem, posso dizer que sim, tem algo a ver com a Irmã Matilda.",
  ui_story_5033_50330701_19_dialog_content = "Quanto ao resto dos detalhes, ainda temos muito a investigar.",
  ui_story_5033_50330701_20_dialog_content = "Mas assim que terminarmos nosso trabalho, tenho certeza de que Pollux e Casta compartilharão o resto com você.",
  ui_story_5033_50330701_21_dialog_content = "Ah... Tá bom.",
  ui_story_5033_50330701_22_dialog_content = "Hum?",
  ui_story_5033_50330701_23_dialog_content = "Tem algum problema?",
  ui_story_5033_50330701_24_dialog_content = "Eu pensei ter visto alguém lá fora agora... Atrás de você, ali.",
  ui_story_5033_50330701_25_dialog_content = "<color=#828282>Crec...</color>",
  ui_story_5033_50330701_26_dialog_content = "Eu não vejo ninguém.",
  ui_story_5033_50330701_27_dialog_content = "Estranho... talvez eu tenha imaginado? Eu poderia jurar que vi alguém passar...",
  ui_story_5033_50330701_28_dialog_content = "Talvez eles estejam se escondendo? Vou tentar sentir a presença deles...",
  ui_story_5033_50330701_29_dialog_content = "Como assim?",
  ui_story_5033_50330701_30_dialog_content = "Er... Simplificando, eu tenho um poder especial que me permite encontrar pessoas sem vê-las. É uma coisa minha.",
  ui_story_5033_50330701_31_dialog_content = "Eu sou muito sensível ao Lumina, assim como ao Darkflow.",
  ui_story_5033_50330701_32_dialog_content = "Isso soa tão legal!",
  ui_story_5033_50330701_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330701_34_dialog_content = "Eu posso sentir três pessoas muito poderosas naquele corredor lá fora. Devem ser Corax, Casta e Pollux.",
  ui_story_5033_50330701_35_dialog_content = "Há também alguns Eclipsitos perambulando pela área, mas eles ainda estão bem longe da igreja.",
  ui_story_5033_50330701_36_dialog_content = "E além disso... tudo o que sinto são pessoas comuns.",
  ui_story_5033_50330701_37_dialog_content = "Oh... Talvez eu estivesse apenas vendo coisas, afinal.",
  ui_story_5033_50330701_38_dialog_content = "Não, acho que você está um pouco ansioso. Vamos voltar para dentro da igreja e esperar Pollux e os outros, ok?",
  ui_story_5033_50330701_39_dialog_content = "Não queremos que esses Eclipses nos vejam aqui.",
  ui_story_5033_50330701_40_dialog_content = "Tá bom.",
  ui_story_5033_50330701_41_dialog_content = "Boa menina, vá e termine de comer.",
  ui_story_5033_50330701_42_dialog_content = "Espero que tudo esteja indo bem no final de Corax...",
  ui_story_5033_50330701_43_dialog_content = "Fui designado para este caso há cerca de um mês.",
  ui_story_5033_50330701_44_dialog_content = "O Senhor das Sombras precisava de alguém para examinar os cadáveres, e foi precisamente quando descobri sinais do método de matar preferido do assassino.",
  ui_story_5033_50330701_45_dialog_content = "<color=#e8d9bb>Há um mês...</color>",
  ui_story_5033_50330701_46_dialog_content = "Está dizendo que viu esses tipos de feridas em um paciente que morreu há alguns dias?",
  ui_story_5033_50330701_47_dialog_content = "De fato, e um paciente bizarro, por sinal. Sua condição estava longe de ser crítica, mas ele morreu do mesmo jeito.",
  ui_story_5033_50330701_48_dialog_content = "Estou começando a pensar que ele não morreu de sua doença...",
  ui_story_5033_50330701_49_dialog_content = "Acredito que um assassino em série está por trás dessas mortes.",
  ui_story_5033_50330701_50_dialog_content = "Houve algum relato recente de mortes estranhas como esta?",
  ui_story_5033_50330701_51_dialog_content = "Sim, mas seus corpos já foram enterrados... A menos que você precise de mim para escavá-los?",
  ui_story_5033_50330701_52_dialog_content = "Eu faço. Precisamos reavaliar suas causas de morte.",
  ui_story_5033_50330701_53_dialog_content = "Todas as nossas descobertas devem ser relatadas ao Senhor das Sombras também.",
  ui_story_5033_50330701_54_dialog_content = "Tudo bem, mas eu não gosto disso...",
  ui_story_5033_50330701_55_dialog_content = "E esse cara? Eu o enterro?",
  ui_story_5033_50330701_56_dialog_content = "D-Não seja tão apressado. Ele ainda está respirando... Talvez eu consiga salvá-lo.",
  ui_story_5033_50330701_57_dialog_content = "Ah, acomode-se.",
  ui_story_5033_50330701_58_dialog_content = "Há cicatrizes estranhas nos corpos das vítimas.",
  ui_story_5033_50330701_59_dialog_content = "Além disso, o culpado repetiu o crime várias vezes.",
  ui_story_5033_50330701_60_dialog_content = "Se não fosse pelo recente aumento desses assassinatos quase idênticos, talvez nunca tivéssemos descoberto que isso foi obra de um serial killer.",
  ui_story_5033_50330701_61_dialog_content = "Embora tenhamos determinado um MO, ainda temos que encontrar outras pistas úteis.",
  ui_story_5033_50330701_62_dialog_content = "Durante minha investigação, descobri que o corpo de uma pessoa que morreu anos atrás em um suposto acidente tinha as mesmas cicatrizes das vítimas do serial killer.",
  ui_story_5033_50330701_63_dialog_content = "Uma das dicas que recebemos foi de uma igreja local. Eles nos deram o arquivo do acidente da Irmã Matilda.",
  ui_story_5033_50330701_64_dialog_content = "Como você ligou o assassino a Euphoria? Onde está o bastardo?!",
  ui_story_5033_50330701_65_dialog_content = "Ainda não sabemos a identidade do assassino. Quanto a como eles estão conectados à Euphoria... É apenas especulação do nosso lado.",
  ui_story_5033_50330701_66_dialog_content = "Rumores dizem que Euphoria é assombrada por um Grim Reaper.",
  ui_story_5033_50330701_67_dialog_content = "Um Ceifador que supostamente só aparece diante daqueles que ousam perturbar a paz na Euforia ou quebrar suas regras.",
  ui_story_5033_50330701_68_dialog_content = "Ele aparece sem um som, tira a vida de suas vítimas sem deixar um rastro de sua presença.",
  ui_story_5033_50330701_69_dialog_content = "Sobre o que exatamente você está falando?",
  ui_story_5033_50330701_70_dialog_content = "O assassino usa uma arte de assassinato de alto nível.",
  ui_story_5033_50330701_71_dialog_content = "Um que, segundo rumores, não deixa vestígios, nem mesmo uma única gota de sangue.",
  ui_story_5033_50330701_72_dialog_content = "Não. Definitivamente deixa algo para trás.",
  ui_story_5033_50330701_73_dialog_content = "Cicatrizes. Concedido, eles só se parecem com marcas de arranhões comuns.",
  ui_story_5033_50330701_74_dialog_content = "Pollux, você conhece essa técnica?",
  ui_story_5033_50330701_75_dialog_content = "Claro que sim... porque <color=#FFB400>também posso usar</color>.",
  ui_story_5033_50330701_76_dialog_content = "O quê?!",
  ui_story_5033_50330702_1_dialog_content = "Acabamos o pão há muito tempo... Por que Casta não voltou para nos dizer para irmos para a cama?",
  ui_story_5033_50330702_2_dialog_content = "Ouvi Casta dizer que precisa ir ao médico depois de comer.",
  ui_story_5033_50330702_3_dialog_content = "Então esse cara é médico?",
  ui_story_5033_50330702_4_dialog_content = "Sim, o bronzeado é um médico.",
  ui_story_5033_50330702_5_dialog_content = "Então, quando eles vão voltar?",
  ui_story_5033_50330702_6_dialog_content = "Vamos apenas dormir por enquanto.",
  ui_story_5033_50330702_7_dialog_content = "Tenho certeza que eles estarão de volta depois que acordarmos.",
  ui_story_5033_50330702_8_dialog_content = "Latan está certo, todos. É hora da soneca, então descanse um pouco e tudo estará resolvido quando você acordar.",
  ui_story_5033_50330702_9_dialog_content = "Hmph... Parece que você está apenas dizendo isso.",
  ui_story_5033_50330702_10_dialog_content = "Acha que somos um bando de crianças de três anos?",
  ui_story_5033_50330702_11_dialog_content = "Ahh! Y-Você é o garoto de antes! Aquele que tentou dar aquela barata para Nekoyashiki...",
  ui_story_5033_50330702_12_dialog_content = "Hehe, isso mesmo.",
  ui_story_5033_50330702_13_dialog_content = "Você está apenas tentando nos enganar para tirarmos nossas sonecas, não é? Bem, nós não estamos comprando isso!",
  ui_story_5033_50330702_14_dialog_content = "Conte-nos o que vocês estão fazendo aqui, e não ouse mentir!",
  ui_story_5033_50330702_15_dialog_content = "(Caramba... Cuidar de crianças pode ser uma verdadeira dor!)",
  ui_story_5033_50330702_16_dialog_content = "Viemos à procura de Raven's Blood... Bem, em vez disso, foram eles que nos procuraram.",
  ui_story_5033_50330702_17_dialog_content = "Estamos investigando um crime muito sério juntos.",
  ui_story_5033_50330702_18_dialog_content = "Que tipo de crime?",
  ui_story_5033_50330702_19_dialog_content = "Hum...",
  ui_story_5033_50330702_20_dialog_content = "(Eu tenho que pensar em uma maneira de assustá-los, para que eles não fiquem perguntando sobre isso!)",
  ui_story_5033_50330702_21_dialog_content = "<anim type=Shake><size=45>Um caso de assassinato muito assustador!!!</size></anim>",
  ui_story_5033_50330702_22_dialog_content = "...",
  ui_story_5033_50330702_23_dialog_content = "D-Isso não soa assustador para vocês?",
  ui_story_5033_50330702_24_dialog_content = "Nós somos da Euphoria... Você realmente acha que isso nos assusta?",
  ui_story_5033_50330702_25_dialog_content = "O que? Quero dizer, deveria... Desculpe, por um segundo eu esqueci.",
  ui_story_5033_50330702_26_dialog_content = "Hahaha! Esse cara pensa que somos apenas um bando de meninos e meninas normais! Que estranho!",
  ui_story_5033_50330702_27_dialog_content = "Sim! B-Além disso... Todo mundo odeia as criancinhas da Euphoria.",
  ui_story_5033_50330702_28_dialog_content = "Não há nada de estranho nisso!",
  ui_story_5033_50330702_29_dialog_content = "Eu não me importo quem você é ou de onde você veio. Aos meus olhos, vocês são apenas um bando de crianças normais.",
  ui_story_5033_50330702_30_dialog_content = "Tudo o que vocês devem pensar é comer, dormir e se divertir! Não se preocupe com nenhuma dessas coisas assustadoras ou perigosas.",
  ui_story_5033_50330702_31_dialog_content = "Pollux e os outros vão resolvê-los.",
  ui_story_5033_50330702_32_dialog_content = "PlayerName tem um ponto... mais Pollux e Casta nos disseram a mesma coisa também.",
  ui_story_5033_50330702_33_dialog_content = "OK tudo bem...",
  ui_story_5033_50330702_34_dialog_content = "Huh... Acho que você é realmente um cara legal, afinal.",
  ui_story_5033_50330702_35_dialog_content = "Não faremos mais perguntas. Cochile com a gente!",
  ui_story_5033_50330702_36_dialog_content = "Sim! Venha cochilar conosco, Sr. Navegador!",
  ui_story_5033_50330702_37_dialog_content = "Sr. Navegador, quero mais doces!",
  ui_story_5033_50330702_38_dialog_content = "H-Ei, não tudo de uma vez, pessoal! Estou prestes a cair!",
  ui_story_5033_50330702_39_dialog_content = "Você tem doce? Também queremos alguns...",
  ui_story_5033_50330702_40_dialog_content = "Eu faço, eu faço, está bem aqui. Nekoyashiki enfiou um monte no meu bolso.",
  ui_story_5033_50330702_41_dialog_content = "Um de cada vez, pessoal. Não precisa se apressar.",
  ui_story_5033_50330702_42_dialog_content = "Nekoyashiki aquele bastardo, com certeza sabe o que está acontecendo.",
  ui_story_5033_50330702_43_dialog_content = "E-eu não acho que uma criança deve falar sobre adultos assim...",
  ui_story_5033_50330702_44_dialog_content = "Afinal, Nekoyashiki é seu superior. Devias mostrar-lhe um pouco mais de respeito.",
  ui_story_5033_50330702_45_dialog_content = "Ei, o que dá?! Pare de pregar e me dê meu doce!",
  ui_story_5033_50330702_46_dialog_content = "Nekoyashiki deixou esse doce comigo, sabe? Se você não o respeita, por que eu deveria compartilhar um pouco com você?",
  ui_story_5033_50330702_47_dialog_content = "O que você está falando? Eu me dou muito bem com Nekoyashiki, e ele nunca me disse para \"respeitá-lo\"!",
  ui_story_5033_50330702_48_dialog_content = "Quer saber uma coisa? Quando Nekoyashiki veio pela primeira vez para Euphoria, ele teve uma atitude muito ruim.",
  ui_story_5033_50330702_49_dialog_content = "Mas então um bando de gângsteres deu uma surra nele!",
  ui_story_5033_50330702_50_dialog_content = "Ele apareceu aqui, todo ensanguentado e machucado. Foi apenas graças a Pollux e Casta que ele sobreviveu.",
  ui_story_5033_50330702_51_dialog_content = "Por que você está contando essa história como se tivesse visto por si mesmo? Você estava lá quando aconteceu?",
  ui_story_5033_50330702_52_dialog_content = "Espere... não me diga que você é realmente mais velho que ele?!",
  ui_story_5033_50330702_53_dialog_content = "Você é louco? Sim, eu estava lá, mas eu tinha apenas cinco anos de idade.",
  ui_story_5033_50330702_54_dialog_content = "Então, qual era o ponto de contar essa história?",
  ui_story_5033_50330702_55_dialog_content = "Para mostrar o quão perto eu e Nekoyashiki somos! Duh!",
  ui_story_5033_50330702_56_dialog_content = "Somos manos até o amargo fim! Por que precisaríamos ser todos enfadonhos e formais uns com os outros?",
  ui_story_5033_50330702_57_dialog_content = "S-Claro... Eu não fazia ideia de que Nekoyashiki passou por algo assim. Acho que isso explica por que ele parece estar tão bem com Raven's Blood.",
  ui_story_5033_50330702_58_dialog_content = "De certa forma, Nekoyashiki é muito parecido com vocês: outra criança acolhida e protegida pelo Raven's Blood.",
  ui_story_5033_50330702_59_dialog_content = "Heehe... exatamente. Ouvi dizer que Nekoyashiki era apenas um garotinho quando veio pela primeira vez à igreja.",
  ui_story_5033_50330702_60_dialog_content = "Pollux disse que, embora seu rosto estivesse todo inchado e sangrando na época, seus olhos estavam cheios de orgulho.",
  ui_story_5033_50330702_61_dialog_content = "Assim que os ferimentos de Nekoyashiki melhoraram, ele saiu sem dizer mais nada.",
  ui_story_5033_50330702_62_dialog_content = "Agora, sempre que ele vem, ele sempre nos traz muita comida e outros itens essenciais.",
  ui_story_5033_50330702_63_dialog_content = "Heh, e ele é nosso revendedor de doces confiável!",
  ui_story_5033_50330702_64_dialog_content = "Não importa o que aconteça, ele sempre faz questão de nos trazer muitos doces!",
  ui_story_5033_50330702_65_dialog_content = "Tudo bem garoto, entendi... Você só quer o seu doce, não é? Aqui, pegue.",
  ui_story_5033_50330702_66_dialog_content = "Doce!",
  ui_story_5033_50330702_67_dialog_content = "Ei, espera... Você pode ficar com seu doce, mas precisa me contar mais sobre Casta e Pollux?",
  ui_story_5033_50330702_68_dialog_content = "Já que vamos trabalhar juntos, gostaria de saber um pouco mais sobre eles.",
  ui_story_5033_50330702_69_dialog_content = "Claro, sem problemas! Latan pode lhe dizer qualquer coisa que você queira saber!",
  ui_story_5033_50330702_70_dialog_content = "Hmm, acho que vou começar com a misteriosa lenda sobre Pollux...",
  ui_story_5033_50330702_71_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5033_50330702_72_dialog_content = "Isso era uma arma agora mesmo?! veio de fora...",
  ui_story_5033_50330702_73_dialog_content = "Se não puder me fornecer provas suficientes para provar sua inocência... Não tenho escolha a não ser nomeá-lo o principal suspeito.",
  ui_story_5033_50330702_74_dialog_content = "Abaixe a lâmina, ou eu vou fazer você comer balas!",
  ui_story_5033_50330702_75_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5033_50330702_76_dialog_content = "Por que você está me dizendo para largar minha arma quando você já está atirando em mim?!",
  ui_story_5033_50330702_77_dialog_content = "Foi um tiro de advertência! Deixe-me repetir: largue sua arma.",
  ui_story_5033_50330702_78_dialog_content = "Como você pode acusar Pollux de ser o assassino?!",
  ui_story_5033_50330702_79_dialog_content = "Irmã Matilda significava o mundo para nós. Como você se atreve a sugerir que poderíamos matá-la!",
  ui_story_5033_50330702_80_dialog_content = "Só estou dizendo que é uma possibilidade. Afinal, tudo o que ouvi até agora é sua própria conta. Não tenho como saber a verdade por trás de seu relacionamento com a irmã Matilda.",
  ui_story_5033_50330702_81_dialog_content = "Desculpas. Pode ser difícil de aceitar, mas do ponto de vista racional, não tenho escolha a não ser tratá-lo como suspeito por enquanto.",
  ui_story_5033_50330702_82_dialog_content = "A única maneira de limpar seu nome é me fornecer provas suficientes de sua inocência.",
  ui_story_5033_50330702_83_dialog_content = "O que diabos está acontecendo aqui?! Por que vocês estão brigando?!",
  ui_story_5033_50330702_84_dialog_content = "PlayerName, Pollux acabou de admitir ser capaz de usar a mesma técnica de assassinato usada pelo serial killer.",
  ui_story_5033_50330702_85_dialog_content = "O quê?!",
  ui_story_5033_50330702_86_dialog_content = "Não... Não pode ser! Pollux nunca mataria ninguém!",
  ui_story_5033_50330702_87_dialog_content = "Chega, todos vocês!",
  ui_story_5033_50330702_88_dialog_content = "Nenhum de vocês deve sacar suas armas na frente de crianças.",
  ui_story_5033_50330702_89_dialog_content = "Pollux... Eles vão te levar embora?",
  ui_story_5033_50330702_90_dialog_content = "Eu não vou deixar eles te levarem! Eu protegerei você!",
  ui_story_5033_50330801_1_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5033_50330801_2_dialog_content = "<color=#e8d9bb>Em uma barra eufórica...</color>",
  ui_story_5033_50330801_3_dialog_content = "Você ouviu? Raven's Blood está ficando todo amigo com alguns idiotas da Umbraton.",
  ui_story_5033_50330801_4_dialog_content = "Quer saber o que eles estão fazendo?",
  ui_story_5033_50330801_5_dialog_content = "Nada de bom, aposto. Eu ouço o Umbraton tentando afundar suas garras fedorentas na Euforia em seguida.",
  ui_story_5033_50330801_6_dialog_content = "Umbraton já usa Euphoria como seu próprio depósito pessoal. Eles jogam todo o lixo deles aqui.",
  ui_story_5033_50330801_7_dialog_content = "Isso não é suficiente para eles?",
  ui_story_5033_50330801_8_dialog_content = "Agora eles querem tirar a terra debaixo dos nossos pés...",
  ui_story_5033_50330801_9_dialog_content = "Os antros de jogo e fábricas de armas que tinham muito medo de fazer negócios em Umbraton vieram aqui.",
  ui_story_5033_50330801_10_dialog_content = "Não será apenas mais do mesmo, então?",
  ui_story_5033_50330801_11_dialog_content = "Como o inferno. Pelo menos antes, esses negócios pertenciam à Euphoria.",
  ui_story_5033_50330801_12_dialog_content = "Agora, Umbraton quer controle total sobre tudo.",
  ui_story_5033_50330801_13_dialog_content = "Bem... eu digo que eles pertenciam à Euphoria, mas na verdade, eles pertenciam ao \"Chefe\".",
  ui_story_5033_50330801_14_dialog_content = "Nossa libertação não foi fácil de ganhar na Euforia, e eu me recuso a viver sob o controle de alguém novamente como nos velhos tempos...",
  ui_story_5033_50330801_15_dialog_content = "Podemos estar quebrados, mas pelo menos não vivemos mais com medo por nossas vidas.",
  ui_story_5033_50330801_16_dialog_content = "Isso mesmo! A euforia pertence a todas as gangues aqui! Essas são as regras.",
  ui_story_5033_50330801_17_dialog_content = "Abram caminho para o nosso chefe!",
  ui_story_5033_50330801_18_dialog_content = "Ah, minhas costas...",
  ui_story_5033_50330801_19_dialog_content = "Ouvi o Raven's Blood bater em vocês. Isso é verdade?",
  ui_story_5033_50330801_20_dialog_content = "Que tipo de pergunta idiota é essa?! Basta olhar para nós!!",
  ui_story_5033_50330801_21_dialog_content = "Eles chegaram ao ponto de brigar com a gente por aqueles malucos da Umbraton. Eu quero saber porque?",
  ui_story_5033_50330801_22_dialog_content = "Quem sabe que tipo de esquemas estão tramando com aqueles dois forasteiros...",
  ui_story_5033_50330801_23_dialog_content = "Eu posso responder isso. Meus meninos acabaram de me trazer algumas informações interessantes.",
  ui_story_5033_50330801_24_dialog_content = "Umbraton enviou aqueles dois aqui em uma investigação de assassinato. Aparentemente, o assassino é de Euphoria, então é para isso que eles estão aqui.",
  ui_story_5033_50330801_25_dialog_content = "Meu palpite é que Raven's Blood está apenas usando isso como uma chance de atrair nossos mestres potencialmente novos.",
  ui_story_5033_50330801_26_dialog_content = "Por que alguém pediria ao Raven's Blood para ajudar com uma investigação criminal?",
  ui_story_5033_50330801_27_dialog_content = "Além disso, toda essa \"investigação de assassinato\" pode ser apenas uma desculpa ruim para eles aparecerem e causarem problemas.",
  ui_story_5033_50330801_28_dialog_content = "Diga alguma coisa, sim Gustav? Você sabe quase tudo o que acontece em Euphoria!",
  ui_story_5033_50330801_29_dialog_content = "O que você quer me ouvir dizer?",
  ui_story_5033_50330801_30_dialog_content = "O que exatamente devemos fazer sobre tudo isso?",
  ui_story_5033_50330801_31_dialog_content = "Dizer a palavra \"exatamente\" não torna necessariamente sua pergunta menos vaga.",
  ui_story_5033_50330801_32_dialog_content = "Você está perguntando o que sua gangue deve fazer? Ou toda a Euforia?",
  ui_story_5033_50330801_33_dialog_content = "Ambos, obviamente!!!",
  ui_story_5033_50330801_34_dialog_content = "Claro que minha gangue é minha prioridade, mas também sou eufórico.",
  ui_story_5033_50330801_35_dialog_content = "Em Euphoria, a única coisa que importa é o poder de uma gangue.",
  ui_story_5033_50330801_36_dialog_content = "Se Raven's Blood pudesse derrotar todos os seus homens com apenas duas pessoas, temo que os outros já...",
  ui_story_5033_50330801_37_dialog_content = "Eu preciso chegar ao fundo disso!",
  ui_story_5033_50330801_38_dialog_content = "Nós não estávamos agrupados na época, e nenhum de nós tinha nossas armas... Sem mencionar que havia um monte de Eclipsites adicionados à mistura! Só assim eles conseguiram vencer.",
  ui_story_5033_50330801_39_dialog_content = "Vamos proceder de acordo com as regras da Euphoria.",
  ui_story_5033_50330801_40_dialog_content = "Se você e sua gangue querem recuperar sua reputação, você precisa desafiá-los para uma luta formal de gangues e vencer.",
  ui_story_5033_50330801_41_dialog_content = "Mas se você está com muito medo...",
  ui_story_5033_50330801_42_dialog_content = "E-eu não tenho medo de lutar... Apenas espere até que minhas feridas estejam curadas, e eu vou derrubar aqueles corvos da árvore deles!",
  ui_story_5033_50330801_43_dialog_content = "Não, chefe. Não deveríamos ter que fazer nada sozinhos.",
  ui_story_5033_50330801_44_dialog_content = "Afinal, os Sangue de Corvo foram os que trouxeram aqueles forasteiros da Umbraton para a Euforia primeiro e causaram problemas. Foram eles que quebraram as regras.",
  ui_story_5033_50330801_45_dialog_content = "Isso mesmo, eu sempre soube que aquelas garotas do Raven's Blood não eram boas.",
  ui_story_5033_50330801_46_dialog_content = "Eles até ferraram com os negócios da nossa gangue um tempo atrás.",
  ui_story_5033_50330801_47_dialog_content = "Eles estão sempre se escondendo em torno de sua preciosa igreja dia e noite, não deixando ninguém chegar perto dela.",
  ui_story_5033_50330801_48_dialog_content = "Bem, duh, esse é o território deles. Claro, eles não vão deixar você simplesmente entrar.",
  ui_story_5033_50330801_49_dialog_content = "A-De qualquer forma... eles apenas me esfregam do jeito errado!",
  ui_story_5033_50330801_50_dialog_content = "Porra certo!",
  ui_story_5033_50330801_51_dialog_content = "Gustav, vá e diga às outras gangues em Euphoria que finalmente é hora de se unir e acabar com o Sangue do Corvo, de uma vez por todas!",
  ui_story_5033_50330801_52_dialog_content = "Tudo bem, agora apenas se acalmem, todos vocês.",
  ui_story_5033_50330801_53_dialog_content = "Eu sei que todos vocês estão convencidos de que a única maneira de salvar Euphoria é se livrar do Sangue do Corvo.",
  ui_story_5033_50330801_54_dialog_content = "Mas você não deve simplesmente cobrar de forma imprudente.",
  ui_story_5033_50330801_55_dialog_content = "Ou você já esqueceu que Raven's Blood fez alguns novos amigos? Atacá-los agora pode provocar a retaliação de Umbraton.",
  ui_story_5033_50330801_56_dialog_content = "E daí?! Euphoria não tem medo de Umbraton!!",
  ui_story_5033_50330801_57_dialog_content = "Não é sobre se você está com medo ou não.",
  ui_story_5033_50330801_58_dialog_content = "O fato é que ainda não sabemos exatamente o que Umbraton está tramando. Eu digo para descobrirmos o que eles estão fazendo antes de fazer nossa jogada.",
  ui_story_5033_50331001_1_dialog_content = "Não há necessidade de se preocupar, crianças. Só tivemos um pequeno mal-entendido, só isso.",
  ui_story_5033_50331001_2_dialog_content = "Abaixe sua arma, Casta. Nunca mais dispare na frente das crianças.",
  ui_story_5033_50331001_3_dialog_content = "Desculpe, Pollux... Eu não estava pensando direito. Eu não pensei que as crianças viriam correndo.",
  ui_story_5033_50331001_4_dialog_content = "Corax, não acho que o serial killer possa ser alguém tão amado e confiável por essas crianças como eles.",
  ui_story_5033_50331001_5_dialog_content = "Já guardei minhas facas... Vou deixar você falar. Desculpe por pular a arma.",
  ui_story_5033_50331001_6_dialog_content = "E-Está tudo bem agora?",
  ui_story_5033_50331001_7_dialog_content = "Sim, está tudo bem agora. Agora todos voltem para a igreja antes que você pegue um resfriado.",
  ui_story_5033_50331001_8_dialog_content = "Isso mesmo, parece que vai chover em breve... Por que vocês não entram primeiro, crianças?",
  ui_story_5033_50331001_9_dialog_content = "Latan, traga-os todos de volta para dentro.",
  ui_story_5033_50331001_10_dialog_content = "Tá bom...",
  ui_story_5033_50331001_11_dialog_content = "Bem, sou todo ouvidos. Você pode começar explicando por que é capaz de usar a mesma técnica de assassinato de alto nível que o assassino.",
  ui_story_5033_50331001_12_dialog_content = "É verdade que sou capaz de usar essa técnica, mas não chega nem perto do grau em que você a descreve.",
  ui_story_5033_50331001_13_dialog_content = "Além disso, esta técnica requer o uso de um tipo muito especial de adaga.",
  ui_story_5033_50331001_14_dialog_content = "Eu já tinha prometido 14 anos atrás nunca mais usá-lo.",
  ui_story_5033_50331001_15_dialog_content = "Nekoyashiki e eu podemos atestar isso.",
  ui_story_5033_50331001_16_dialog_content = "Desculpe, mas seus testemunhos não têm peso.",
  ui_story_5033_50331001_17_dialog_content = "Eu preciso de mais se você quer que eu confie em você, Pollux.",
  ui_story_5033_50331001_18_dialog_content = "Só posso lhe oferecer tudo o que sei... Confiar ou não em mim é uma decisão sua.",
  ui_story_5033_50331001_19_dialog_content = "Então me diga, como você conseguiu aprender esse tipo de técnica de assassinato?",
  ui_story_5033_50331001_20_dialog_content = "Aprendi com o antigo dono da Euphoria. Todos o chamavam de <color=#FFB400>Chefe</color>.",
  ui_story_5033_50331001_21_dialog_content = "Sua <color=#FFB400>organização</color> já controlou todos os residentes e empresas em Euphoria.",
  ui_story_5033_50331001_22_dialog_content = "Naquela época, todos viviam com medo do Ceifador da organização.",
  ui_story_5033_50331001_23_dialog_content = "Eu pertencia a essa organização há muito tempo, onde fui forçado a aprender a técnica de matar do Grim Reaper também.",
  ui_story_5033_50331001_24_dialog_content = "Quem exatamente era esse personagem \"Boss\"?",
  ui_story_5033_50331001_25_dialog_content = "Sempre que estávamos em sua presença, ele sempre se sentava em uma cadeira vermelho-sangue de costas para nós.",
  ui_story_5033_50331001_26_dialog_content = "Ninguém sabia seu nome ou mesmo como ele se parecia.",
  ui_story_5033_50331001_27_dialog_content = "Por que você se juntaria a uma organização como essa?",
  ui_story_5033_50331001_28_dialog_content = "Quando uma pessoa está lutando para sobreviver, ela nem sempre pensa nas consequências de suas decisões.",
  ui_story_5033_50331001_29_dialog_content = "Então, quando alguém me disse que eu poderia ter minha própria cama e não teria que me preocupar com comida ou roupa nunca mais...",
  ui_story_5033_50331001_30_dialog_content = "Naturalmente aceitei a oferta.",
  ui_story_5033_50331001_31_dialog_content = "Foi só mais tarde que descobri que ele era o \"Chefe\" de quem todos falavam.",
  ui_story_5033_50331001_32_dialog_content = "Então é seguro assumir que o serial killer fazia parte desta organização, assim como você, correto?",
  ui_story_5033_50331001_33_dialog_content = "Mas a organização foi completamente exterminada dez anos atrás.",
  ui_story_5033_50331001_34_dialog_content = "Achei que era o único sobrevivente.",
  ui_story_5033_50331001_35_dialog_content = "É possível que houvesse mais sobreviventes, exceto que você não sabia deles.",
  ui_story_5033_50331001_36_dialog_content = "Agora que você examinou esses relatórios de autópsia, alguém em particular vem à mente?",
  ui_story_5033_50331001_37_dialog_content = "Existe uma pessoa...",
  ui_story_5033_50331001_38_dialog_content = "Ela seria a única habilidosa o suficiente para realizar esses assassinatos. Mas essa pessoa está morta.",
  ui_story_5033_50331001_39_dialog_content = "Como você tem tanta certeza?",
  ui_story_5033_50331001_40_dialog_content = "Porque fui eu que a matei... Minha melhor amiga.",
  ui_story_5033_50331001_41_dialog_content = "<color=#e8d9bb>14 anos atrás...</color>",
  ui_story_5033_50331001_42_dialog_content = "Isso é... Minha própria cama?",
  ui_story_5033_50331001_43_dialog_content = "Hum...",
  ui_story_5033_50331001_44_dialog_content = "Ahh! Q-Quem é você?! O que você está fazendo, se escondendo aí?!",
  ui_story_5033_50331001_45_dialog_content = "P-Por favor, não entenda errado! Eu não queria assustá-lo por estar tão quieto!",
  ui_story_5033_50331001_46_dialog_content = "É que... Você estava acariciando seu travesseiro agora, e foi fofo demais para interromper...",
  ui_story_5033_50331001_47_dialog_content = "Você está... tirando sarro de mim?!",
  ui_story_5033_50331001_48_dialog_content = "... Não importa. Ria se quiser, eu não me importo.",
  ui_story_5033_50331001_49_dialog_content = "Eu só vi travesseiros em vitrines antes. São tão macios ao toque...",
  ui_story_5033_50331001_50_dialog_content = "Parece que você é meu novo colega de quarto.",
  ui_story_5033_50331001_51_dialog_content = "Minhas costas estão doendo de tanto ficar parado. Se importa se sentarmos na sua cama e conversarmos?",
  ui_story_5033_50331001_52_dialog_content = "S-Sim, claro! Aqui, fique à vontade!",
  ui_story_5033_50331001_53_dialog_content = "Meu nome é Antares. O que é seu?",
  ui_story_5033_50331001_54_dialog_content = "Eu... realmente não tenho meu próprio nome. Estou usando o nome que uma freira me deu quando me encontrou vagando por Euphoria.",
  ui_story_5033_50331001_55_dialog_content = "O que você estaria fazendo em um lugar como esse? Você sabe onde estamos, não sabe?",
  ui_story_5033_50331001_56_dialog_content = "B-Bem, alguém me disse que eu poderia ser escolhido se me inscrevesse para isso.",
  ui_story_5033_50331001_57_dialog_content = "E se eu fosse escolhido, nunca mais precisaria me preocupar com comida ou roupas. Eu teria até minha própria cama!",
  ui_story_5033_50331001_58_dialog_content = "Então me inscrevi, fui selecionado e conheci você!",
  ui_story_5033_50331001_59_dialog_content = "Então você realmente não tem ideia do que eles fazem por aqui, hein...",
  ui_story_5033_50331001_60_dialog_content = "Acho que não... Qual é o problema, Antares? Suas mãos estão tão frias.",
  ui_story_5033_50331001_61_dialog_content = "Vou fechar a janela!",
  ui_story_5033_50331001_62_dialog_content = "Eu estou bem...",
  ui_story_5033_50331001_63_dialog_content = "Certo, mas se estiver com frio, é só me avisar.",
  ui_story_5033_50331001_64_dialog_content = "Então você está aqui há muito tempo? Que tipo de lugar é esse, afinal?",
  ui_story_5033_50331001_65_dialog_content = "Sim, vivo neste quarto desde que me lembro. Esse lugar...",
  ui_story_5033_50331001_66_dialog_content = "É uma instalação de treinamento subterrânea privada para mercenários eufóricos.",
  ui_story_5033_50331001_67_dialog_content = "Pollux... Acho que precisamos ter uma conversa séria agora.",
  ui_story_5033_50331001_68_dialog_content = "Uh... Eu sei o que você quer dizer, Antares! Eu prometo que vou prestar mais atenção da próxima vez, ok?",
  ui_story_5033_50331001_69_dialog_content = "Você diz isso toda vez... Quando você realmente vai cumprir sua promessa?!",
  ui_story_5033_50331001_70_dialog_content = "Toda vez que eu volto de uma missão, você tem um monte de novas feridas em seu corpo antes mesmo que as antigas tenham terminado de cicatrizar...",
  ui_story_5033_50331001_71_dialog_content = "Você tem ideia do quanto dói te ver assim? Para enfaixá-lo, apenas para encontrar novas feridas no dia seguinte?!",
  ui_story_5033_50331001_72_dialog_content = "Meus sentimentos não devem importar para você, de forma alguma...",
  ui_story_5033_50331001_73_dialog_content = "Desculpe, Antares... Só não sei o que há de errado comigo.",
  ui_story_5033_50331001_74_dialog_content = "Quando cheguei aqui, você já estava saindo em missões. Na época, eu sabia que havia uma enorme lacuna em nossos pontos fortes...",
  ui_story_5033_50331001_75_dialog_content = "Então estudei o máximo que pude, dia e noite... Até me forcei a treinar com mercenários que eram muito mais fortes e de alto escalão do que eu.",
  ui_story_5033_50331001_76_dialog_content = "Mas para eles, não sou nem de longe tão bom quanto você... Até os recrutas que vieram um ou dois anos depois de mim são mais promissores!",
  ui_story_5033_50331001_77_dialog_content = "Quero ser como você, Antares... Quero ser um forte mercenário também!",
  ui_story_5033_50331001_78_dialog_content = "Não é assim, Pólux. Ouço...",
  ui_story_5033_50331001_79_dialog_content = "Todo mundo sabe como suas notas são boas, certo? Eles até nos chamam de Gêmeos por causa de quão próximos somos!",
  ui_story_5033_50331001_80_dialog_content = "Você já é incrível, Pollux. Não há necessidade de se esforçar tanto...",
  ui_story_5033_50331001_81_dialog_content = "Então por que ainda estou preso aqui, enquanto você e os outros saem em missões?",
  ui_story_5033_50331001_82_dialog_content = "Me desculpe... Antares... eu sei que estou sendo teimosa e que você só está cuidando de mim...",
  ui_story_5033_50331001_83_dialog_content = "Você não precisa se desculpar comigo, Pollux. Não sou eu que você está machucando... Você é.",
  ui_story_5033_50331001_84_dialog_content = "Se eu pudesse fazer tudo de novo, eu escolheria minha própria vida.",
  ui_story_5033_50331001_85_dialog_content = "Uma vida sem culpa constante... Ou pesadelo para me acordar todas as noites.",
  ui_story_5033_50331001_86_dialog_content = "Uma vida... Sem \"missões\".",
  ui_story_5033_50331001_87_dialog_content = "Huh? Mas eu quero muito sair em missão, Antares...",
  ui_story_5033_50331001_88_dialog_content = "Eu quero lutar ao seu lado, para que possamos nos apoiar o tempo todo.",
  ui_story_5033_50331001_89_dialog_content = "Depois que me disseram, eu poderia finalmente sair em uma missão...",
  ui_story_5033_50331001_90_dialog_content = "O que você está fazendo aí, Pollux? É um segredo?",
  ui_story_5033_50331001_91_dialog_content = "E-Ei! Feche seus olhos! Sem espiar, ouviu?!",
  ui_story_5033_50331001_92_dialog_content = "Ugh, tudo bem... Vê? Eles estão fechados.",
  ui_story_5033_50331001_93_dialog_content = "E feito! Já pode abrir os olhos!",
  ui_story_5033_50331001_94_dialog_content = "É este <color=#FFB400>broche</color>... Para mim?",
  ui_story_5033_50331001_94X1_dialog_content = "Sim, a loja me disse que é hortênsia, e acho que combina perfeitamente com você.",
  ui_story_5033_50331001_95_dialog_content = "Sim! Eu só recebo uma pequena bolsa agora, então isso é tudo que eu posso pagar.",
  ui_story_5033_50331001_96_dialog_content = "Mas assim que eu terminar minha missão e receber meu pagamento, vou te dar algo ainda melhor! Algo que tenho certeza que você vai adorar!",
  ui_story_5033_50331001_97_dialog_content = "M-Missão...?",
  ui_story_5033_50331001_98_dialog_content = "Sim! Conheci o chefe há alguns dias, e ele me disse que em breve teria uma missão para mim!",
  ui_story_5033_50331001_99_dialog_content = "Então eu fiz isso para você comemorar meu desejo se tornando realidade, e para agradecer por sempre estar lá para mim.",
  ui_story_5033_50331001_100_dialog_content = "Agora, o que devo te dar a seguir...?",
  ui_story_5033_50331001_101_dialog_content = "...",
  ui_story_5033_50331001_102_dialog_content = "Qual é o problema, Antares? Você não gosta?",
  ui_story_5033_50331001_103_dialog_content = "Não, não é isso. Eu amo o quão bonitas as flores roxas parecem.",
  ui_story_5033_50331001_104_dialog_content = "Pólux...",
  ui_story_5033_50331001_105_dialog_content = "Claro?",
  ui_story_5033_50331001_106_dialog_content = "Obrigado por ser meu amigo. O tempo que passamos juntos foi o momento mais feliz da minha vida.",
  ui_story_5033_50331001_107_dialog_content = "Você não seria Antares se não saísse com algo brega.",
  ui_story_5033_50331001_108_dialog_content = "Eu também faço.",
  ui_story_5033_50331001_109_dialog_content = "Obrigado por ser meu amigo, Antares.",
  ui_story_5033_50331001_110_dialog_content = "Eu nunca poderia esperar que essa busca fosse assim.",
  ui_story_5033_50331001_111_dialog_content = "Eu, em uma arena, enfrentando meu melhor amigo...",
  ui_story_5033_50331001_112_dialog_content = "P-Por que...",
  ui_story_5033_50331001_113_dialog_content = "Por que VOCÊ é meu oponente...?",
  ui_story_5033_50331001_114_dialog_content = "Um é um droide de combate, criado em combate real.",
  ui_story_5033_50331001_115_dialog_content = "O outro era um promissor promissor e talento cuidadosamente aperfeiçoado no campo de treinamento.",
  ui_story_5033_50331001_116_dialog_content = "Esta dupla de dinamite é conhecida como Gemini! Mas hoje, apenas um deles estará saindo do ringue.",
  ui_story_5033_50331001_117_dialog_content = "Euphoria já testemunhou - ou testemunhará - uma partida tão emocionante e emocionante como essa?",
  ui_story_5033_50331001_118_dialog_content = "Antares, você...",
  ui_story_5033_50331001_119_dialog_content = "Levante sua adaga e venha até mim.",
  ui_story_5033_50331001_120_dialog_content = "Não é a missão que você estava esperando?",
  ui_story_5033_50331001_121_dialog_content = "Eu sei que você tem treinado duro para isso.",
  ui_story_5033_50331001_122_dialog_content = "Mas eu...",
  ui_story_5033_50331001_123_dialog_content = "O que você está esperando?",
  ui_story_5033_50331001_124_dialog_content = "Se isso fosse uma luta de verdade, você estaria morto uma dúzia de vezes agora.",
  ui_story_5033_50331001_125_dialog_content = "Eu simplesmente não posso levantar minha mão contra você...",
  ui_story_5033_50331001_126_dialog_content = "E se eu te dissesse que a única razão pela qual você está aqui, agora, é por minha causa?",
  ui_story_5033_50331001_127_dialog_content = "Não... Não, isso não pode ser verdade!",
  ui_story_5033_50331001_128_dialog_content = "Por que nos fazer lutar uns contra os outros? Você não acha um pouco estranho?",
  ui_story_5033_50331001_129_dialog_content = "Estranho? Nada é estranho em Euphoria, e contém muitos segredos que você nem consegue imaginar.",
  ui_story_5033_50331001_130_dialog_content = "Eu obviamente... o convenci muitas vezes no passado.",
  ui_story_5033_50331001_131_dialog_content = "Não há nenhuma maneira que eu possa fazer concessões para você.",
  ui_story_5033_50331001_132_dialog_content = "Você realmente levantaria a mão contra mim...?",
  ui_story_5033_50331001_133_dialog_content = "Correto. Eu nasci na batalha, e a primeira coisa que aprendi foi...",
  ui_story_5033_50331001_134_dialog_content = "Não mostre misericórdia a ninguém.",
  ui_story_5033_50331001_135_dialog_content = "Não... <size=45>Não quero brigar com você, Antares!</size>",
  ui_story_5033_50331001_136_dialog_content = "<size=45>Ou defenda-se ou MORRA!!</size>",
  ui_story_5033_50331001_137_dialog_content = "Quando eu vim para...",
  ui_story_5033_50331001_138_dialog_content = "Era tarde demais.",
  ui_story_5033_50331001_139_dialog_content = "Urgh...!",
  ui_story_5033_50331001_140_dialog_content = "Eu... eu... O que eu fiz?",
  ui_story_5033_50331001_141_dialog_content = "Antares... Por que você não correu?",
  ui_story_5033_50331001_142_dialog_content = "<anim type=Shake>Obrigado... Obrigado... Pollux...</anim>",
  ui_story_5033_50331001_143_dialog_content = "Antares! NÃO! Não me deixe... Desculpe... sinto muito...",
  ui_story_5033_50331001_144_dialog_content = "Por que... Por que você simplesmente não fugiu?",
  ui_story_5033_50331001_145_dialog_content = "<anim type=Shake>Dessa forma eu... posso ser livre...</anim>",
  ui_story_5033_50331001_146_dialog_content = "<anim type=Shake>Finalmente livre...</anim>",
  ui_story_5033_50331001_147_dialog_content = "Eu fiz isso. A morte de Antares é por minha conta... Matei meu único amigo no mundo inteiro com minhas próprias mãos.",
  ui_story_5033_50331001_148_dialog_content = "Não entendi até que o punhal em minha mão já havia penetrado no peito de Antares.",
  ui_story_5033_50331001_149_dialog_content = "Quão terrível era aquilo pelo qual eu realmente ansiava.",
  ui_story_5033_50331001_150_dialog_content = "É por isso que você não empunha mais punhais...",
  ui_story_5033_50331001_151_dialog_content = "Sim. Os eventos do dia continuam se repetindo na minha cabeça, tão reais que é como se eu estivesse de volta à arena.",
  ui_story_5033_50331001_152_dialog_content = "Perdi a consciência após a luta e queimei com febre alta por mais de uma semana.",
  ui_story_5033_50331001_153_dialog_content = "Quando finalmente acordei, estava sozinho no quarto.",
  ui_story_5033_50331001_154_dialog_content = "A roupa de Antares, o caderno... Todos os seus rastros haviam desaparecido completamente daquelas quatro paredes quadradas.",
  ui_story_5033_50331001_155_dialog_content = "Era tão limpo, tão estéril... Como se ela nunca tivesse existido neste mundo.",
  ui_story_5033_50331001_156_dialog_content = "Eu rapidamente saí daquele quarto também. Em menos de um mês, ambos os seus habitantes se foram.",
  ui_story_5033_50331001_157_dialog_content = "Você saiu dessa organização?",
  ui_story_5033_50331001_158_dialog_content = "Bem, não era tanto pular do navio, mas ser empurrado.",
  ui_story_5033_50331001_159_dialog_content = "Depois dessa luta, comecei a ter medo e achei difícil até mesmo segurar uma adaga.",
  ui_story_5033_50331001_160_dialog_content = "Para um mercenário, perder a habilidade de combate significa perder todo o valor.",
  ui_story_5033_50331001_161_dialog_content = "Então é natural que eu tenha sido expulso do time e mantido em cativeiro no porão.",
  ui_story_5033_50331001_162_dialog_content = "Até os Eclipsitas chegarem e arrasarem o lugar.",
  ui_story_5033_50331001_163_dialog_content = "Você tem alguma outra informação?",
  ui_story_5033_50331001_164_dialog_content = "Não me desculpe. Isso é tudo que eu sei...",
  ui_story_5033_50331001_165_dialog_content = "Eu prometo a você, no entanto, eu vou ajudá-lo a chegar ao fundo disso.",
  ui_story_5033_50331001_166_dialog_content = "<color=#e8d9bb>Dadá...</color>",
  ui_story_5033_50331001_167_dialog_content = "Resistir! Eu sinto um monte de gente indo nessa direção!",
  ui_story_5033_50331001_168_dialog_content = "Quem?",
  ui_story_5033_50331001_169_dialog_content = "Não sei, mas acho que eles querem... cercar a igreja?!",
  ui_story_5033_50331101_1_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5033_50331101_2_dialog_content = "Movam-se, rapazes! Se apresse!",
  ui_story_5033_50331101_3_dialog_content = "Armas prontas, preparem-se para atacar. Raven's Blood não é nada fácil!",
  ui_story_5033_50331101_4_dialog_content = "Prontos!",
  ui_story_5033_50331101_5_dialog_content = "No fundo, até estarmos em posição. Vou dar o sinal de fogo, entendeu?",
  ui_story_5033_50331101_6_dialog_content = "Entendido!",
  ui_story_5033_50331101_7_dialog_content = "Nossos caras estão todos presentes e corretos?",
  ui_story_5033_50331101_8_dialog_content = "Todo mundo está aqui, chefe! O Sangue do Corvo acabou por este tempo!",
  ui_story_5033_50331101_9_dialog_content = "Haha, excelente! Esperei muito tempo por este dia.",
  ui_story_5033_50331101_10_dialog_content = "Ei, espere um minuto... Gustav não nos disse para não nos apressarmos?",
  ui_story_5033_50331101_11_dialog_content = "<size=45>O que você sabe?</size>",
  ui_story_5033_50331101_12_dialog_content = "Esta é uma oportunidade perfeita para encontrar provas de conluio entre Raven's Blood e Umbraton.",
  ui_story_5033_50331101_13_dialog_content = "O que faremos se os deixarmos escapar, hmm?",
  ui_story_5033_50331101_14_dialog_content = "Negativo. Devo reportar ao Gustav.",
  ui_story_5033_50331101_15_dialog_content = "Quando você se tornou o fantoche de Gustav?",
  ui_story_5033_50331101_16_dialog_content = "Tudo bem então, saia daqui. Eu disse VAI! Não me incomode!",
  ui_story_5033_50331101_17_dialog_content = "Quem quer que sejam, eles definitivamente estão indo nessa direção.",
  ui_story_5033_50331101_18_dialog_content = "Quem se atreve a procurar problemas com Raven's Blood?",
  ui_story_5033_50331101_19_dialog_content = "Receio que não seja tão simples desta vez.",
  ui_story_5033_50331101_20_dialog_content = "Ninguém teria se aproximado tão precipitadamente da igreja antes.",
  ui_story_5033_50331101_21_dialog_content = "Desta vez é um grupo grande. Estou preocupado que eles tenham se unido para lançar um ataque.",
  ui_story_5033_50331101_22_dialog_content = "Porque agora?",
  ui_story_5033_50331101_23_dialog_content = "Parece que eles realmente têm uma coisa contra as pessoas de Umbraton que entram em Euphoria.",
  ui_story_5033_50331101_24_dialog_content = "É porque viemos aqui?",
  ui_story_5033_50331101_25_dialog_content = "Desculpe, Corax.",
  ui_story_5033_50331101_26_dialog_content = "Talvez nossa maneira de fazer as coisas irritasse as gangues locais.",
  ui_story_5033_50331101_27_dialog_content = "Temo que primeiro precisamos cuidar dessa briga de gangues local.",
  ui_story_5033_50331101_28_dialog_content = "Eles são apenas covardes, intimidando os fracos, mas temendo os fortes. Eles realmente acham que podem vencer nosso Raven's Blood, mesmo se unindo?",
  ui_story_5033_50331101_29_dialog_content = "Eu digo trazê-los, não importa quantos!",
  ui_story_5033_50331101_30_dialog_content = "Reinicie-o um pouco. Não há nenhum benefício para nós em piorar as coisas.",
  ui_story_5033_50331101_31_dialog_content = "Casta, Corax - leve as crianças para Nekoyashiki para abrigo.",
  ui_story_5033_50331101_32_dialog_content = "Eles estão atrás de Raven's Blood e da igreja. Vou tentar bloqueá-los aqui.",
  ui_story_5033_50331101_33_dialog_content = "OK. Vou manter as crianças seguras, prometo.",
  ui_story_5033_50331101_34_dialog_content = "E você? Ninguém pode lidar com tantos sozinho, nem mesmo você.",
  ui_story_5033_50331101_35_dialog_content = "Farei o meu melhor para ganhar tempo. Agora vá, pegue as crianças e saia daqui.",
  ui_story_5033_50331101_36_dialog_content = "... Entendido. É melhor você esperar até eu voltar!",
  ui_story_5033_50331101_37_dialog_content = "Eu ajudo. Algumas das crianças estão feridas, então precisamos cuidar delas na mudança.",
  ui_story_5033_50331101_38_dialog_content = "PlayerName.",
  ui_story_5033_50331101_39_dialog_content = "Huh? Aqui!",
  ui_story_5033_50331101_40_dialog_content = "Embora eu não saiba muito sobre você, acho que você pode encontrar uma rota segura para tirar todos daqui.",
  ui_story_5033_50331101_41_dialog_content = "Posso deixar para você liderar o caminho?",
  ui_story_5033_50331101_42_dialog_content = "Sem problemas!",
  ui_story_5033_50331101_43_dialog_content = "Nekoyashiki geralmente está em sua cabine. Você se lembra onde é?",
  ui_story_5033_50331101_44_option_content = "Sim.",
  ui_story_5033_50331101_45_dialog_content = "Nekoyashiki vive em uma cabana com grafite em forma de cicatriz.",
  ui_story_5033_50331101_46_dialog_content = "Atravesse o beco ao sul da igreja, vá mais alguns quarteirões e depois desça a viela estreita.",
  ui_story_5033_50331101_47_dialog_content = "Deve haver cerca de cinco ou seis voltas...",
  ui_story_5033_50331101_48_dialog_content = "Você precisará fazer seis voltas.",
  ui_story_5033_50331101_49_dialog_content = "Tudo bem, eu tenho. Deixe-me pensar no melhor caminho a seguir.",
  ui_story_5033_50331101_50_dialog_content = "OK. Pergunte a Casta se tiver mais alguma dúvida. Receio que ela e Corax precisem lidar com qualquer briga.",
  ui_story_5033_50331101_51_dialog_content = "Se necessário, você também pode perguntar ao Latan. Ela pode ser jovem, mas é confiável.",
  ui_story_5033_50331101_52_option_content = "Não.",
  ui_story_5033_50331101_53_dialog_content = "É aquela pequena cabana que você já esteve antes. Aquele com o grafite em forma de cicatriz do lado de fora.",
  ui_story_5033_50331101_54_dialog_content = "Quando você sair, primeiro atravesse o beco ao sul da igreja, depois vá mais alguns quarteirões.",
  ui_story_5033_50331101_55_dialog_content = "Se alguém estiver na rua, vá um pouco mais longe e procure um beco com adesivos de ursos na parede.",
  ui_story_5033_50331101_56_dialog_content = "Essas são as obras das crianças. Eles vão reconhecê-los, também Casta.",
  ui_story_5033_50331101_57_dialog_content = "Receio que Casta e Corax terão de lidar com qualquer luta. Caberá a você continuar com as crianças.",
  ui_story_5033_50331101_58_dialog_content = "Quando você chegar lá, conte tudo a Nekoyashiki. Ele poderá levá-lo a algum lugar seguro. Você tem tudo isso?",
  ui_story_5033_50331101_59_dialog_content = "Entendido.",
  ui_story_5033_50331101_60_dialog_content = "Excelente. Você é um bom garoto.",
  ui_story_5033_50331101_61_option_content = "Eu não sou uma criança.",
  ui_story_5033_50331101_62_dialog_content = "Você me deu o trabalho de nos levar até lá, e eu o farei sem problemas.",
  ui_story_5033_50331101_63_dialog_content = "Eu também posso ajudar Casta e Corax a lutar, para que nenhum mal aconteça às crianças. Você pode relaxar.",
  ui_story_5033_50331101_64_dialog_content = "Isso é maravilhoso. Vejo que minha fé em você não foi equivocada...",
  ui_story_5033_50331101_65_dialog_content = "Você é muito mais maduro do que eu pensava. Quando a poeira baixar de tudo isso, adoraria ouvir sua história.",
  ui_story_5033_50331101_66_dialog_content = "Tudo bem, isso é um acordo.",
  ui_story_5033_50331101_67_option_content = "Eu vou ser um bom garoto.",
  ui_story_5033_50331101_68_dialog_content = "Esses também são bons filhos. Tenho certeza que eles vão cooperar.",
  ui_story_5033_50331101_69_dialog_content = "Não há necessidade de se preocupar. Voltaremos logo, assim que os tivermos em algum lugar seguro.",
  ui_story_5033_50331101_70_dialog_content = "Tudo bem. Ouvir isso me deixa mais à vontade.",
  ui_story_5033_50331101_71_dialog_content = "É melhor esperar até voltarmos para ajudar, Pollux!",
  ui_story_5033_50331101_72_dialog_content = "Eu sei. Eu farei o meu melhor. Obrigada.",
  ui_story_5033_50331101_73_dialog_content = "Casta e as crianças estão chegando. Você tem que ir.",
  ui_story_5033_50331101_74_dialog_content = "Pollux, Casta disse que precisamos ir a algum lugar seguro. E você? Você não vem com a gente?",
  ui_story_5033_50331101_75_dialog_content = "Pólux...! Pollux... Vem com a gente!",
  ui_story_5033_50331101_76_dialog_content = "Agora agora, pessoal, não vamos mais incomodar Pollux. Nós não apenas concordamos em ouvir o plano?",
  ui_story_5033_50331101_77_dialog_content = "Mas...",
  ui_story_5033_50331101_78_dialog_content = "Não se preocupem comigo, crianças.",
  ui_story_5033_50331101_79_dialog_content = "Eu preciso ficar aqui um pouco, porque tem uma coisa que eu preciso cuidar.",
  ui_story_5033_50331101_80_dialog_content = "Vocês precisam ir para algum lugar seguro agora. Tente ficar longe daqui.",
  ui_story_5033_50331101_81_dialog_content = "Uh... Mas há montes de Eclipsitas fora da igreja. Se você não vem com a gente...",
  ui_story_5033_50331101_82_dialog_content = "Casta e Dr. Corax cuidarão de você, não se preocupe.",
  ui_story_5033_50331101_83_dialog_content = "PlayerName e Nekoyashiki estará lá também.",
  ui_story_5033_50331101_84_dialog_content = "Quando podemos voltar para a igreja?",
  ui_story_5033_50331101_85_dialog_content = "Está tudo bem mesmo que não possamos voltar para a igreja. Encontraremos outro abrigo.",
  ui_story_5033_50331101_86_dialog_content = "O mais importante é que todos estejam seguros e felizes juntos.",
  ui_story_5033_50331101_87_dialog_content = "Mas, mas você... Você ainda estará conosco, certo?",
  ui_story_5033_50331101_88_dialog_content = "Sim claro!",
  ui_story_5033_50331101_89_dialog_content = "Irei encontrá-lo, assim que cuidar disso.",
  ui_story_5033_50331101_90_dialog_content = "Agora vá, crianças.",
  ui_story_5033_50331202_1_dialog_content = "Saia daqui, Sangue de Corvo!",
  ui_story_5033_50331202_2_dialog_content = "Saia daqui e morra!",
  ui_story_5033_50331202_3_dialog_content = "Não pense que você pode simplesmente andar por toda a Euforia. Saia aqui AGORA!",
  ui_story_5033_50331202_4_dialog_content = "É melhor vocês ouvirem, vocês na igreja, mas especialmente aqueles dois de Umbraton!",
  ui_story_5033_50331202_5_dialog_content = "Eu não me importo por que você está aqui, mas na Euphoria, você joga pelas regras da Euphoria.",
  ui_story_5033_50331202_6_dialog_content = "Se você se atrever a conspirar com o Sangue do Corvo, então você é inimigo da Euforia.",
  ui_story_5033_50331202_7_dialog_content = "Se houver alguma coisa que você queira discutir, então você pode entrar na igreja.",
  ui_story_5033_50331202_8_dialog_content = "Daremos as boas vindas a todos, e tenho certeza que você ficará satisfeito com sua recepção, seja com arma ou lâmina.",
  ui_story_5033_50331202_9_dialog_content = "Ei chefe, essa é a voz do Pollux!",
  ui_story_5033_50331202_10_dialog_content = "O que eles estão fazendo aí?!",
  ui_story_5033_50331202_11_dialog_content = "eu... eu não sei...",
  ui_story_5033_50331202_12_dialog_content = "O que a gente faz agora?",
  ui_story_5033_50331202_13_dialog_content = "Que tal... Chefe, você entra primeiro?",
  ui_story_5033_50331202_14_dialog_content = "Você é estúpido, cabeça-dura?!",
  ui_story_5033_50331202_15_dialog_content = "Eu definitivamente não posso simplesmente entrar lá sozinho! Tem que ser uma armadilha.",
  ui_story_5033_50331202_16_dialog_content = "Chefe está certo! Se vamos entrar, devemos todos correr juntos.",
  ui_story_5033_50331202_17_dialog_content = "Apressar-se em quê, idiota?! Chame alguém para trazer os explosivos!",
  ui_story_5033_50331202_18_dialog_content = "Uh-oh... Sim, claro.",
  ui_story_5033_50331202_19_dialog_content = "Os outros estão todos esperando aqui. Faça com que cercam o local e assegure-se de que ninguém fuja.",
  ui_story_5033_50331202_20_dialog_content = "Boa ideia!",
  ui_story_5033_50331202_21_dialog_content = "Como é que ainda não há notícias do Gustav? Está ficando desesperador...",
  ui_story_5033_50331202_22_dialog_content = "Miau...",
  ui_story_5033_50331202_23_dialog_content = "Esse é o sinal! Finalmente...",
  ui_story_5033_50331202_24_dialog_content = "Hum... Você entendeu?",
  ui_story_5033_50331202_25_dialog_content = "Oh meu querido, você está esperando por este pedacinho de papel?",
  ui_story_5033_50331202_26_dialog_content = "Quem... Quem é você? Há quanto tempo você está atrás de mim?!",
  ui_story_5033_50331202_27_dialog_content = "Desde que você chegou aqui.",
  ui_story_5033_50331202_28_dialog_content = "A n-freira?! Estou acabado para...",
  ui_story_5033_50331202_29_dialog_content = "Isso mesmo. Você pode me chamar de Irmã Anne, ou <color=#FFB400>Antares</color>.",
  ui_story_5033_50331202_30_dialog_content = "Mas, novamente... Você não terá a chance de contar a ninguém.",
  ui_story_5033_50331202_31_dialog_content = "Não! Por favor, não me mate... eu... eu só faço recados... eu não sei de nada.",
  ui_story_5033_50331202_32_dialog_content = "Talvez eu não o mate, mas, novamente, talvez você possa me dizer quem é Gustav?",
  ui_story_5033_50331202_33_dialog_content = "Eu suspeito... Que ele te deu este pedaço de papel, certo?",
  ui_story_5033_50331202_34_dialog_content = "Eu não posso acreditar que é tão fácil.",
  ui_story_5033_50331202_35_dialog_content = "Diga-me, isso é algum tipo de armadilha para me atrair?",
  ui_story_5033_50331202_36_dialog_content = "O que você está falando...? Eu nem entendo o que você está dizendo!",
  ui_story_5033_50331202_37_dialog_content = "Ah não... Talvez a situação fosse tão volátil que ele não teve tempo de cobrir seus rastros...",
  ui_story_5033_50331202_38_dialog_content = "O que você está tentando dizer? Isso é loucura...",
  ui_story_5033_50331202_39_dialog_content = "Não se faça de bobo comigo! Eu sabia que você me reconheceu no primeiro segundo em que me viu.",
  ui_story_5033_50331202_40_dialog_content = "Além do mais, você sabe o que estou aqui para fazer, ou melhor... o que eu poderia estar aqui para fazer.",
  ui_story_5033_50331202_41_dialog_content = "As pessoas não mentem quando encaram a morte de frente.",
  ui_story_5033_50331202_42_dialog_content = "Ugh...",
  ui_story_5033_50331202_43_dialog_content = "Antares... Não te direi nada.",
  ui_story_5033_50331202_44_dialog_content = "Eu nem preciso mais.",
  ui_story_5033_50331202_45_dialog_content = "<color=#e8d9bb>Uau—!</color>",
  ui_story_5033_50331202_46_dialog_content = "Urgh... Você...",
  ui_story_5033_50331202_47_dialog_content = "Então... É assim que se sente... ser morto pelo Ceifador...",
  ui_story_5033_50331202_48_dialog_content = "Em agradecimento a você por me fornecer essa pista, farei o meu melhor para que você não sofra indevidamente.",
  ui_story_5033_50331202_49_dialog_content = "Você tem meus agradecimentos.",
  ui_story_5033_50331202_50_dialog_content = "E agora... Finalmente, posso encontrar Pollux.",
  ui_story_5033_50331202_51_dialog_content = "Chefe! Ei, chefe! Temos os explosivos!",
  ui_story_5033_50331202_52_dialog_content = "Pode não ser muito, mas é certo o suficiente para explodir aquela igreja.",
  ui_story_5033_50331202_53_dialog_content = "Excelente! Bem feito.",
  ui_story_5033_50331202_54_dialog_content = "Coloque-os em um círculo ao redor da igreja.",
  ui_story_5033_50331202_55_dialog_content = "Tenha cuidado ao colocá-los, principalmente se dispararem de dentro da igreja.",
  ui_story_5033_50331202_56_dialog_content = "Sem problemas!",
  ui_story_5033_50331202_57_dialog_content = "Com licença, com licença, preciso ir para a frente.",
  ui_story_5033_50331202_58_dialog_content = "De onde veio a freira? Saia do caminho, a menos que você esteja no mercado para um caixão...",
  ui_story_5033_50331202_59_dialog_content = "<color=#e8d9bb>Uau—!</color>",
  ui_story_5033_50331202_60_dialog_content = "<size=45>ARGH!! Assassinato!!</size>",
  ui_story_5033_50331202_61_dialog_content = "O que?! O que está acontecendo lá atrás?",
  ui_story_5033_50331202_62_dialog_content = "Não se preocupe, nada aconteceu... Afinal, as pessoas morrem em guerras de gangues.",
  ui_story_5033_50331202_63_dialog_content = "De onde você veio?!",
  ui_story_5033_50331202_64_dialog_content = "<color=#e8d9bb>Uau—!</color>",
  ui_story_5033_50331202_65_dialog_content = "Argh—! Minha mão... Minha mão!",
  ui_story_5033_50331202_66_dialog_content = "Chefe! Esta freira, ela tem uma faca...!",
  ui_story_5033_50331202_67_dialog_content = "EU SEI! Foi ela que me cortou! Vá atrás dela e derrube-a!!",
  ui_story_5033_50331202_68_dialog_content = "Eu aconselho você a não usar explosivos para tentar destruir a igreja, ou você enfrentará a ira do céu.",
  ui_story_5033_50331202_69_dialog_content = "<color=#e8d9bb>Uau—!</color>",
  ui_story_5033_50331202_70_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5033_50331202_71_dialog_content = "Explosões? Rapidamente, espalhe-se!",
  ui_story_5033_50331202_72_dialog_content = "Aquela freira abriu o cartucho explosivo. Ela é louca!",
  ui_story_5033_50331202_73_dialog_content = "Olhe para isso! A freira ainda está viva... Como ela conseguiu isso?",
  ui_story_5033_50331202_74_dialog_content = "Se todos pudessem ficar em silêncio por um minuto, por favor. Estou aqui porque tenho algo para fazer na igreja. Assim que terminar, deixo todos em paz.",
  ui_story_5033_50331202_75_dialog_content = "Eu aconselho contra qualquer ação precipitada antes disso.",
  ui_story_5033_50331202_76_dialog_content = "A menos que você queira conhecer o <color=#FFB400>Ceifador</color>...",
  ui_story_5033_50331301_1_dialog_content = "E-e agora... Devemos ouvir aquela freira?",
  ui_story_5033_50331301_2_dialog_content = "Várias pessoas já estavam mortas, você não viu?",
  ui_story_5033_50331301_3_dialog_content = "Se quiser subir, fique à vontade... Não tenho pressa.",
  ui_story_5033_50331301_4_dialog_content = "Ela... acabou de mencionar o Ceifador? Isso significa que essas lendas são realmente verdadeiras?",
  ui_story_5033_50331301_5_dialog_content = "Shh... Bem, se for verdade, esse é um nome que nunca devemos mencionar.",
  ui_story_5033_50331301_6_dialog_content = "Obrigado por sua cooperação.",
  ui_story_5033_50331301_7_dialog_content = "<color=#e8d9bb>Dentro da igreja</color>",
  ui_story_5033_50331301_8_dialog_content = "... O que exatamente está acontecendo lá fora?",
  ui_story_5033_50331301_9_dialog_content = "<color=#e8d9bb>Da, da...</color>",
  ui_story_5033_50331301_10_dialog_content = "Oi...",
  ui_story_5033_50331301_11_dialog_content = "O perímetro é bem guardado... Como você entrou aqui?",
  ui_story_5033_50331301_12_dialog_content = "Conversei com as pessoas lá fora e elas concordaram em me deixar passar.",
  ui_story_5033_50331301_13_dialog_content = "Eu não me importo quem você é, ou por que você está aqui.",
  ui_story_5033_50331301_14_dialog_content = "Mas, por favor, vá embora... Não há nenhum deus da luz aqui, irmã.",
  ui_story_5033_50331301_15_dialog_content = "... Você não me reconhece? Pólux.",
  ui_story_5033_50331301_16_dialog_content = "<size=45>Você...!</size>",
  ui_story_5033_50331301_17_dialog_content = "Já faz muito tempo.",
  ui_story_5033_50331301_18_dialog_content = "<color=#FFB400>Antares</color>, você é... Não... Como isso é possível?",
  ui_story_5033_50331301_19_dialog_content = "Desculpe, Pólux. Esta é a única maneira que eu poderia encontrá-lo novamente.",
  ui_story_5033_50331301_20_dialog_content = "Para ser honesto, eu pensei que você teria me esquecido.",
  ui_story_5033_50331301_21_dialog_content = "Como eu poderia esquecer?! Eu era o responsável na época...",
  ui_story_5033_50331301_22_dialog_content = "Não me dê esse olhar culpado, Pollux. Eu te imploro.",
  ui_story_5033_50331301_23_dialog_content = "Fiquei repetindo na minha cabeça: o que eu deveria dizer a você se nos encontrássemos novamente, como eu deveria enfrentá-lo.",
  ui_story_5033_50331301_24_dialog_content = "Mas agora que você está aqui, de pé na minha frente, não consigo me lembrar de uma única palavra.",
  ui_story_5033_50331301_25_dialog_content = "O que você está tentando dizer...?",
  ui_story_5033_50331301_26_dialog_content = "Seus olhos ainda são os mesmos de todos aqueles anos atrás. Eles não mudaram.",
  ui_story_5033_50331301_27_dialog_content = "Tão brilhante quanto as estrelas.",
  ui_story_5033_50331301_28_dialog_content = "Anne... Você está por trás de tudo? Mas por que?",
  ui_story_5033_50331301_29_dialog_content = "Mas como isso poderia ser? Como você sobreviveu?",
  ui_story_5033_50331301_30_dialog_content = "E por que você está... vestida como uma freira?",
  ui_story_5033_50331301_31_dialog_content = "Não se preocupe, Pollux, eu vou te dizer. Eu vou te contar tudo.",
  ui_story_5033_50331301_32_dialog_content = "Vou lhe dar a versão curta agora... Não temos muito tempo.",
  ui_story_5033_50331301_33_dialog_content = "<color=#e8d9bb>14 anos atrás...</color>",
  ui_story_5033_50331301_34_dialog_content = "Sim, apenas aqui. Agora, para jogá-lo no rio.",
  ui_story_5033_50331301_35_dialog_content = "Que pena! Como um dos Gêmeos, ela acabou de morrer assim.",
  ui_story_5033_50331301_36_dialog_content = "O chefe também não achava que ela faria essa escolha...",
  ui_story_5033_50331301_37_dialog_content = "<color=#e8d9bb>Resumo—</color>",
  ui_story_5033_50331301_38_dialog_content = "Ah, céus! Olhar! No Rio...",
  ui_story_5033_50331301_39_dialog_content = "Ajude-me... Tem uma criança aqui!",
  ui_story_5033_50331301_40_dialog_content = "Acenda o fogo, rápido! Ela ainda está viva! Alguém chame o médico!",
  ui_story_5033_50331301_41_dialog_content = "Ai... Dói...",
  ui_story_5033_50331301_42_dialog_content = "Eu ainda estou vivo?",
  ui_story_5033_50331301_43_dialog_content = "Quem é aquele do lado de fora da porta?",
  ui_story_5033_50331301_44_dialog_content = "É simplesmente monstruoso. Quem poderia fazer isso com uma criança?",
  ui_story_5033_50331301_45_dialog_content = "Ela com certeza é resiliente para sobreviver até mesmo a uma lesão como essa.",
  ui_story_5033_50331301_46_dialog_content = "Há mais para isso. Leve-a para a abadia em Umbraton. Prefiro não ter mais problemas...",
  ui_story_5033_50331301_47_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_5033_50331301_48_dialog_content = "Aqui está o jornal de hoje, Anne.",
  ui_story_5033_50331301_49_dialog_content = "Há uma carta também... Embora você não tenha ninguém chamado <color=#FFB400>Antares</color> aqui, não é?",
  ui_story_5033_50331301_50_dialog_content = "O quê?",
  ui_story_5033_50331301_51_dialog_content = "... Não. Ninguém aqui com esse nome.",
  ui_story_5033_50331301_52_dialog_content = "Talvez seja o nome errado. Você poderia descobrir para quem é?",
  ui_story_5033_50331301_53_dialog_content = "Para Antares.",
  ui_story_5033_50331301_54_dialog_content = "Eu sou um discípulo devoto do deus da luz. Desejo me arrepender em nome de alguém que cometeu um pecado imperdoável.",
  ui_story_5033_50331301_55_dialog_content = "Ela forjou sua própria morte e enganou sua família, tudo no interesse de ganhar uma falsa liberdade.",
  ui_story_5033_50331301_56_dialog_content = "Ela se aproveita das amizades, deixando aqueles que a amam carregarem o fardo da vida em seu nome e afundar em um mar de miséria.",
  ui_story_5033_50331301_57_dialog_content = "Ela deve se arrepender até a próxima carta de confissão chegar.",
  ui_story_5033_50331301_58_dialog_content = "Quem mandou isso...?",
  ui_story_5033_50331301_59_dialog_content = "Você está bem, Ana? Você ficou pálido.",
  ui_story_5033_50331301_60_dialog_content = "Deixe-me manter esta carta aqui por enquanto.",
  ui_story_5033_50331301_61_dialog_content = "Talvez alguém chamado Antares... viesse reclamá-lo.",
  ui_story_5033_50331301_62_dialog_content = "Então, por todos esses anos, você tem vivido como freira?",
  ui_story_5033_50331301_63_dialog_content = "Exatamente.",
  ui_story_5033_50331301_64_dialog_content = "Não faço ideia de como quem enviou a carta sabia minha verdadeira identidade...",
  ui_story_5033_50331301_65_dialog_content = "Mas independentemente disso, \"ele\" me tinha firmemente sob seu controle. Não ousei desobedecer a nenhuma ordem.",
  ui_story_5033_50331301_66_dialog_content = "Mas você nem teme a morte! Como alguém pode controlar você? Os fantasmas têm fraquezas, então?",
  ui_story_5033_50331301_67_dialog_content = "Sim... Minha única fraqueza era meu único amigo.",
  ui_story_5033_50331301_68_dialog_content = "Você está dizendo que é por minha causa?",
  ui_story_5033_50331301_69_dialog_content = "Sim. Ele disse que o incidente quase te destruiu, mas que Gêmeos deve continuar...",
  ui_story_5033_50331301_70_dialog_content = "\"Pólux é inútil se ela não puder mais empunhar uma faca.\"",
  ui_story_5033_50331301_71_dialog_content = "Se eu não cumprir minhas ordens, você será...",
  ui_story_5033_50331301_72_dialog_content = "Sempre achei que a organização não perseguia meu fracasso porque os Eclipsitas invadiram, e eles não tinham tempo de sobra...",
  ui_story_5033_50331301_73_dialog_content = "Mas a organização não nos deixará ir tão facilmente.",
  ui_story_5033_50331301_74_dialog_content = "Mesmo que toda a Euforia fosse destruída, ainda haveria aqueles na organização que continuariam a nos manipular.",
  ui_story_5033_50331301_75_dialog_content = "Então você realmente fez todas essas coisas, Anne?",
  ui_story_5033_50331301_76_dialog_content = "Não tive escolha, Pólux.",
  ui_story_5033_50331301_77_dialog_content = "Você não só sobreviveu a essa luta, mas até conseguiu fugir daquele lugar.",
  ui_story_5033_50331301_78_dialog_content = "Eu quero proteger sua liberdade.",
  ui_story_5033_50331301_79_dialog_content = "Mesmo que você não tenha saído da Euforia, você tem alguém para proteger, em quem confiar, não é?",
  ui_story_5033_50331301_80_dialog_content = "Você está falando das crianças?",
  ui_story_5033_50331301_81_dialog_content = "E aquela jovem com a arma. Ela parece bastante confiável.",
  ui_story_5033_50331301_82_dialog_content = "Com pessoas assim ao seu lado, você não tem nada a temer.",
  ui_story_5033_50331301_83_dialog_content = "Considerando que eu não sou nada além de um morto-vivo há muito desaparecido.",
  ui_story_5033_50331301_84_dialog_content = "Você também matou a Irmã Matilda?!",
  ui_story_5033_50331301_85_dialog_content = "...",
  ui_story_5033_50331301_86_dialog_content = "Responda-me, Ana!",
  ui_story_5033_50331301_87_dialog_content = "Sim.",
  ui_story_5033_50331301_88_dialog_content = "Por quê?",
  ui_story_5033_50331301_89_dialog_content = "Matá-la era apenas uma ordem de muitas. Eu nem sei por que a organização a atacou.",
  ui_story_5033_50331301_90_dialog_content = "Desculpe, Pólux.",
  ui_story_5033_50331301_91_dialog_content = "Você sabe o quanto ela era importante para mim.",
  ui_story_5033_50331301_92_dialog_content = "Eu não tive escolha...",
  ui_story_5033_50331301_93_dialog_content = "Você veio desarmado.",
  ui_story_5033_50331301_94_dialog_content = "O quê?",
  ui_story_5033_50331301_95_dialog_content = "Sua arma, Antares. Você vem antes de mim, me diga tudo isso, mas você está desarmado...",
  ui_story_5033_50331301_96_dialog_content = "Você está apostando que eu não vou levantar minha mão contra você?",
  ui_story_5033_50331301_97_dialog_content = "Parece que já estivemos aqui antes... Embora, Pollux, ESTOU armado.",
  ui_story_5033_50331301_98_dialog_content = "Porque minha missão final... é <color=#FFB400>matar você</color>.",
  ui_story_5033_50331301_99_dialog_content = "Então o que você está esperando?",
  ui_story_5033_50331301_100_dialog_content = "Você me conhece, Pólux. Você sabe que eu nunca poderia fazer isso.",
  ui_story_5033_50331301_101_dialog_content = "Não vim aqui só para contar essas velhas histórias...",
  ui_story_5033_50331301_102_dialog_content = "Vou cuidar dessa escória que tem me usado por tantos anos e remover a ameaça mais perigosa para você no processo.",
  ui_story_5033_50331301_103_dialog_content = "Você espera que eu seja grato?",
  ui_story_5033_50331301_104_dialog_content = "Nem um pouco. Vim apenas para te ver uma última vez, antes de nos despedirmos mais uma vez.",
  ui_story_5033_50331301_105_dialog_content = "Meu querido Pollux... Espero que quando tudo isso acabar, você saiba o que precisa ser feito.",
  ui_story_5033_50331301_106_dialog_content = "É...",
  ui_story_5033_50331301_107_dialog_content = "Você realmente é egoísta.",
  ui_story_5033_50331301_108_dialog_content = "Wormping seu caminho em minha amizade e minha faca em seu corpo... Mesmo \"morto\", você ainda de alguma forma conseguiu controlar meu destino...",
  ui_story_5033_50331301_109_dialog_content = "E agora você está diante de mim tão grandioso, suas palavras arrogantes.",
  ui_story_5033_50331301_110_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5033_50331301_111_dialog_content = "Parece que o tempo acabou.",
  ui_story_5033_50331301_112_dialog_content = "Gente... Não, Eclipsites, entrando por trás.",
  ui_story_5033_50331301_113_dialog_content = "Você está afiado agora, Pollux, muito afiado. Quase como uma pessoa totalmente diferente daquela época.",
  ui_story_5033_50331301_114_dialog_content = "O cabelo comprido também combina com você. Mas o que aconteceu com seus olhos?",
  ui_story_5033_50331301_115_dialog_content = "... Não tenho nada que queira compartilhar com você.",
  ui_story_5033_50331301_116_dialog_content = "Mas eu sim...",
  ui_story_5033_50331301_117_dialog_content = "E compartilharei com você, assim que terminar a primeira parte da minha expiação.",
  ui_story_5033_50331302_1_dialog_content = "Latan, Schewe...",
  ui_story_5033_50331302_2_dialog_content = "Bom, temos todos.",
  ui_story_5033_50331302_3_dialog_content = "Todo mundo precisa ficar aqui, e não sair correndo. Entendido?",
  ui_story_5033_50331302_4_dialog_content = "Eu posso ajudar! Pollux me ensinou a lutar!",
  ui_story_5033_50331302_5_dialog_content = "Eu também!",
  ui_story_5033_50331302_6_dialog_content = "Estabeleça-se. Não é...",
  ui_story_5033_50331302_7_dialog_content = "Por acaso, preciso de alguns guardas treinados aqui. Deus sabe se aquela gangue de bandidos vai aparecer.",
  ui_story_5033_50331302_8_dialog_content = "Se vocês pudessem ficar aqui e ficar de olho nas entradas e saídas, isso seria uma grande ajuda.",
  ui_story_5033_50331302_9_dialog_content = "Incrível! Vou montar uma força-tarefa especial imediatamente!!",
  ui_story_5033_50331302_10_dialog_content = "Mais algumas tábuas para pregar nas janelas também seria maravilhoso.",
  ui_story_5033_50331302_11_dialog_content = "Rogério. Vamos, Latão!",
  ui_story_5033_50331302_12_dialog_content = "Entendido!",
  ui_story_5033_50331302_13_dialog_content = "Tem certeza que está tudo bem para as crianças ficarem aqui?",
  ui_story_5033_50331302_14_dialog_content = "É muito perigoso mandá-los para outro lugar agora, de qualquer maneira.",
  ui_story_5033_50331302_15_dialog_content = "Eu nunca tive tantas pessoas aqui de uma vez, porém, e não sei quanto tempo nossas provisões vão durar.",
  ui_story_5033_50331302_16_dialog_content = "Não se preocupe. Este assunto não deve demorar muito.",
  ui_story_5033_50331302_17_dialog_content = "Gustavo. Você está aqui.",
  ui_story_5033_50331302_18_dialog_content = "Pense em algo, rapidamente, antes que tudo comece na igreja. Você sabe tudo sobre Euphoria, não é?",
  ui_story_5033_50331302_19_dialog_content = "Pelo que ouvi, a situação é crítica.",
  ui_story_5033_50331302_20_dialog_content = "Muitos dos que cercam a igreja são de uma gangue ou de outra. Tudo o que preciso fazer é entrar em contato com seus líderes, e devo ser capaz de resolver isso.",
  ui_story_5033_50331302_21_dialog_content = "Mas a questão-chave é o que fazer com os civis comuns.",
  ui_story_5033_50331302_22_dialog_content = "Todo mundo agora sabe que Pollux está abrigando pessoas de Umbraton na igreja. Receio que isso vai levar mais do que algumas palavras bonitas para resolver.",
  ui_story_5033_50331302_23_dialog_content = "...",
  ui_story_5033_50331302_24_dialog_content = "Você deve ser aquele rapaz da Umbraton, certo?",
  ui_story_5033_50331302_25_dialog_content = "Acho que Taki nunca nos mencionou para você?",
  ui_story_5033_50331302_26_dialog_content = "Ele me disse que você viria, mas nunca mencionou a enorme dor de cabeça que você traria com você.",
  ui_story_5033_50331302_27_dialog_content = "Agora toda a Euphoria pensa que o Shadowlord mandou vocês aqui para destruir o lugar.",
  ui_story_5033_50331302_28_dialog_content = "Mas não fizemos nada!",
  ui_story_5033_50331302_29_dialog_content = "Hmph! É um pouco tarde para você dizer isso agora.",
  ui_story_5033_50331302_30_dialog_content = "Investigar é investigar, mas você realmente tinha que provocar os locais e se envolver com o Sangue do Corvo?",
  ui_story_5033_50331302_31_dialog_content = "Você tem alguma ideia de quão antagônico Raven's Blood geralmente é?",
  ui_story_5033_50331302_32_dialog_content = "O status de gangue sempre foi definido pela força na Euphoria. Não fizemos nada contra a norma.",
  ui_story_5033_50331302_33_dialog_content = "Eu o avisei há muito tempo para não ofender muitas pessoas, ou você ganhará inimigos que guardam rancor. Mas você ouviu?",
  ui_story_5033_50331302_34_dialog_content = "E olha o que aconteceu! Agora todas as gangues se uniram para acabar com vocês, e eu não posso impedi-los.",
  ui_story_5033_50331302_35_dialog_content = "Pollux é bastante inteligente, de alguma forma tirando você de lá. Falando nisso, onde ela está?",
  ui_story_5033_50331302_36_dialog_content = "Ela ficou na igreja para nos dar algum tempo. Na verdade, temos que voltar para ela agora mesmo!",
  ui_story_5033_50331302_37_dialog_content = "Vamos lá! Eles podem até estar lutando já!",
  ui_story_5033_50331302_38_dialog_content = "Acalme-se, Casta. Tem uma coisa que eu preciso te dizer primeiro...",
  ui_story_5033_50331302_39_dialog_content = "Um indivíduo muito perigoso está aqui em Euphoria.",
  ui_story_5033_50331302_40_dialog_content = "Eu suspeito que ela é a que vocês dois vieram aqui procurar.",
  ui_story_5033_50331302_41_dialog_content = "Você quer dizer aqueles casos...?",
  ui_story_5033_50331302_42_dialog_content = "Por acaso havia uma freira, entre suas companheiras?",
  ui_story_5033_50331302_43_dialog_content = "Bem, sim, mas ela se despediu um tempo atrás.",
  ui_story_5033_50331302_44_dialog_content = "Não me diga que...",
  ui_story_5033_50331302_45_dialog_content = "Ela matou um dos meus vigias, na igreja. Ela está lá agora.",
  ui_story_5033_50331302_46_dialog_content = "O quê?!",
  ui_story_5033_50331302_47_dialog_content = "Você está me dizendo que aquele idiota, aquele que matou Matilda, está na igreja agora?!",
  ui_story_5033_50331302_48_dialog_content = "Sim. Tem as mesmas características do estojo Umbraton. Tem que ser ela.",
  ui_story_5033_50331302_49_dialog_content = "Espere um segundo, como você sabe de tudo isso?",
  ui_story_5033_50331302_50_dialog_content = "A inteligência é o meu pão com manteiga, rapaz.",
  ui_story_5033_50331302_51_dialog_content = "Isso não é tudo que eu sei, também. Também conheço um segredinho que tenho certeza que Pollux estaria muito interessado...",
  ui_story_5033_50331302_52_dialog_content = "Essa \"freira\" não é serva do deus da luz.",
  ui_story_5033_50331302_53_dialog_content = "Ela e Pollux costumavam ser chamados de Gêmeos como membros da organização, e seu nome é <color=#FFB400>Antares</color>.",
  ui_story_5033_50331302_54_dialog_content = "O que você disse?!",
  ui_story_5033_50331302_55_dialog_content = "Aguentar! A pessoa de quem você está falando não está morta?",
  ui_story_5033_50331302_56_dialog_content = "Isso mesmo! Isto é impossível. Pollux claramente...",
  ui_story_5033_50331302_57_dialog_content = "Eu estava tão cético quanto você quando esta informação chegou aos meus ouvidos. Mas asseguro-lhe que é verdade.",
  ui_story_5033_50331302_58_dialog_content = "Ela não apenas sobreviveu, mas está reunindo forças há anos. E agora, ela decidiu se vingar de Euphoria.",
  ui_story_5033_50331302_59_dialog_content = "O que estamos esperando? Pollux está fadado a estar em apuros!",
  ui_story_5033_50331302_60_dialog_content = "Sim... Se ela pode matar pessoas sem piscar, não consigo imaginar do que mais ela poderia ser capaz...",
  ui_story_5033_50331302_61_dialog_content = "Não podemos permitir que ela continue criando problemas.",
  ui_story_5033_50331302_62_dialog_content = "Tem certeza disso, Gustavo?",
  ui_story_5033_50331302_63_dialog_content = "Ouça, rapaz, eu lhe disse onde encontrar a pessoa que você procura. Se você pode ou não pegá-la, é com você.",
  ui_story_5033_50331302_64_dialog_content = "Isso explodiu...",
  ui_story_5033_50331302_65_dialog_content = "Por que você não vai com eles, Gustav? Você pode precisar controlar a situação, pois é difícil para eles lutarem com Antares...",
  ui_story_5033_50331302_66_dialog_content = "Hahaha, você não precisa se preocupar que eu consiga controlar a situação. Deixe para mim.",
  ui_story_5033_50331302_67_dialog_content = "Você apenas se concentra em encontrar o assassino e revelar a verdade a todos",
  ui_story_5033_50331302_68_dialog_content = "Vou tentar aliviar a raiva que Euphoria sente por você...",
  ui_story_5033_50331401_1_dialog_content = "<color=#e8d9bb>*Rumbles...*</color>",
  ui_story_5033_50331401_2_dialog_content = "Isso foi uma explosão? Ou trovão?",
  ui_story_5033_50331401_3_dialog_content = "Acelere o passo, Caelestita. Como você é mais lento do que esses ossos velhos?",
  ui_story_5033_50331401_4_dialog_content = "Sinto muito...",
  ui_story_5033_50331401_5_dialog_content = "Preciso falar com você, Casta.",
  ui_story_5033_50331401_6_dialog_content = "Eu sei o que você quer dizer.",
  ui_story_5033_50331401_7_dialog_content = "Ela tem que morrer.",
  ui_story_5033_50331401_8_dialog_content = "Você...",
  ui_story_5033_50331401_9_dialog_content = "Casta, eu sei que você e Pollux estão furiosos com Matilda.",
  ui_story_5033_50331401_10_dialog_content = "Mas não acho que seja uma situação tão simples. Você já pensou por que ela está fazendo tudo isso?",
  ui_story_5033_50331401_11_dialog_content = "Porque ela quer se vingar de Pollux e de toda a Euforia por sua \"morte\".",
  ui_story_5033_50331401_12_dialog_content = "Isso é possível. Mas por que agora, depois de tantos anos?",
  ui_story_5033_50331401_13_dialog_content = "Eu não posso dizer.",
  ui_story_5033_50331401_14_dialog_content = "Por que cometer tantos crimes de alto nível e só então ir à procura de Pollux?",
  ui_story_5033_50331401_15_dialog_content = "Não sei.",
  ui_story_5033_50331401_16_dialog_content = "E porque...",
  ui_story_5033_50331401_17_dialog_content = "<size=45>Não sei e não quero saber!</size>",
  ui_story_5033_50331401_18_dialog_content = "Pollux a matou uma vez, então ela matou a irmã Matilda, que salvou Pollux.",
  ui_story_5033_50331401_19_dialog_content = "Traz toda a suspeita para Pollux e depois volta para Euphoria enquanto você segue pistas.",
  ui_story_5033_50331401_20_dialog_content = "É difícil entender que tudo isso é para se vingar de Pollux?",
  ui_story_5033_50331401_21_dialog_content = "Acalme-se primeiro e pense no que Pollux faria!",
  ui_story_5033_50331401_22_dialog_content = "Pollux não cobriria Antares!",
  ui_story_5033_50331401_23_dialog_content = "Ela faria exatamente o que eu faria – cortá-la em pedaços!",
  ui_story_5033_50331401_24_dialog_content = "Casta!",
  ui_story_5033_50331401_25_dialog_content = "Ei, não coma isso! Desembucha...",
  ui_story_5033_50331401_26_dialog_content = "<color=#e8d9bb>Ding-dong, Ding-dong—</color>",
  ui_story_5033_50331401_27_dialog_content = "Escute, você não pode comer isso, entendeu? Agora corra e jogue em outro lugar.",
  ui_story_5033_50331401_28_dialog_content = "Ufa... Finalmente consegui resolver os pequenos.",
  ui_story_5033_50331401_29_dialog_content = "<color=#e8d9bb>Bata, bate, bate!</color>",
  ui_story_5033_50331401_30_dialog_content = "Quem é esse?",
  ui_story_5033_50331401_31_dialog_content = "Abra a porta, rápido! Eu sou Eho, agente especial da Umbraton Courier Union!",
  ui_story_5033_50331401_32_dialog_content = "Você me assustou até a morte! O que você está fazendo aqui? Você tem meu pacote?",
  ui_story_5033_50331401_33_dialog_content = "Hum, entrega super rápida da Umbraton!",
  ui_story_5033_50331401_34_dialog_content = "Mantenha-o baixo, você faria?! Dê aqui.",
  ui_story_5033_50331401_35_dialog_content = "<color=#e8d9bb>*Desdobramento de papel*</color>",
  ui_story_5033_50331401_36_dialog_content = "\"Aqui é Taki. Não consigo entrar em contato com Corax, então estou tentando a sorte com você.\"",
  ui_story_5033_50331401_37_dialog_content = "\"Uma vítima sobreviveu ao serial killer, e ele está acordado. Você tem que contar a Corax imediatamente...\"",
  ui_story_5033_50331401_38_dialog_content = "\"A suspeita é uma freira, com cabelos e olhos grisalhos. As fotos estão abaixo...\"",
  ui_story_5033_50331401_39_dialog_content = "\"Mas ela não é a cabeça! Ainda há alguém por trás dela puxando as cordas!\"",
  ui_story_5033_50331401_40_dialog_content = "O quê?",
  ui_story_5033_50331401_41_dialog_content = "<size=42>\"É <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_42_dialog_content = "<size=42>\"Nos bastidores, é tudo <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_43_dialog_content = "Expiação? Compartilhar? O que exatamente você está fazendo aqui...?",
  ui_story_5033_50331401_44_dialog_content = "Só estou aqui porque queria te dizer que descobri quem está puxando as cordas por trás de tudo isso.",
  ui_story_5033_50331401_45_dialog_content = "Espere que eu termine com ele e eu posso te dar sua vida de volta.",
  ui_story_5033_50331401_46_dialog_content = "Eu devo isso a você.",
  ui_story_5033_50331401_47_dialog_content = "Eu não preciso disso! Vou entregá-lo a Umbraton.",
  ui_story_5033_50331401_48_dialog_content = "Temo que isso não dê certo... Não quero morrer nas mãos de ninguém além das suas.",
  ui_story_5033_50331401_49_dialog_content = "Enlouqueceu?!",
  ui_story_5033_50331401_50_dialog_content = "Porque sim! Estou louco há muito tempo.",
  ui_story_5033_50331401_51_dialog_content = "Desde que nasci filho de Euphoria... Desde que entrei para aquela organização...",
  ui_story_5033_50331401_52_dialog_content = "No que me diz respeito, matar é tão natural quanto respirar.",
  ui_story_5033_50331401_53_dialog_content = "Eu nunca tinha estado realmente acordado.",
  ui_story_5033_50331401_54_dialog_content = "Até encontrar meu primeiro amigo... Você era como minha estrela guia, me mostrando o caminho...",
  ui_story_5033_50331401_55_dialog_content = "Feche! No segundo em que você matou a irmã Matilda, perdemos qualquer chance de sermos amigos.",
  ui_story_5033_50331401_56_dialog_content = "Não... No segundo em que levantei minha faca para você, você não era meu amigo.",
  ui_story_5033_50331401_57_dialog_content = "Não, Pollux, isso foi culpa da organização! Gustav é o culpado por tudo...",
  ui_story_5033_50331401_58_dialog_content = "Tudo vai acabar, contanto que eles se vão.",
  ui_story_5033_50331401_59_dialog_content = "<size=45>Gustav?</size>",
  ui_story_5033_50331401_60_dialog_content = "Sim. Como eu disse, finalmente descobri quem está puxando as cordas nos bastidores.",
  ui_story_5033_50331401_61_dialog_content = "Gustav... Ele fazia parte da organização e já foi o braço direito do chefe.",
  ui_story_5033_50331401_62_dialog_content = "Ele é realmente um membro?",
  ui_story_5033_50331401_63_dialog_content = "Você tem alguma prova?",
  ui_story_5033_50331401_64_dialog_content = "Lamento dizer que não.",
  ui_story_5033_50331401_65_dialog_content = "É tudo testemunho ouvido da boca de homens moribundos.",
  ui_story_5033_50331401_66_dialog_content = "<color=#e8d9bb>Falha—</color>",
  ui_story_5033_50331401_67_dialog_content = "<size=45>Você realmente está aqui, Antares!!</size>",
  ui_story_5033_50331401_68_dialog_content = "Hum...",
  ui_story_5033_50331401_69_dialog_content = "Pollux, tudo bem?!",
  ui_story_5033_50331401_70_dialog_content = "Estou bem. E as crianças? Você os trouxe a salvo?",
  ui_story_5033_50331401_71_dialog_content = "Essa mulher não é freira! Ela assassinou a Irmã Matilda!",
  ui_story_5033_50331401_72_dialog_content = "Se você não a vingar, eu vou!",
  ui_story_5033_50331401_73_dialog_content = "*Tosse*",
  ui_story_5033_50331401_74_dialog_content = "<size=45>Você matou Matilda...!!</size>",
  ui_story_5033_50331401_75_dialog_content = "Casta, você...",
  ui_story_5033_50331401_76_dialog_content = "Está tudo bem, Pólux. Ela é realmente uma criança muito promissora...",
  ui_story_5033_50331401_77_dialog_content = "<size=45>Onde está sua arma?! Desenhe agora!</size>",
  ui_story_5033_50331401_78_dialog_content = "<size=45>Vou fazer você pagar... por Matilda!</size>",
  ui_story_5033_50331401_79_dialog_content = "Você... você viu isso? Foi tão rápido, que simplesmente esmagou a parede!",
  ui_story_5033_50331401_80_dialog_content = "Olhar! Gustavo está aqui!",
  ui_story_5033_50331401_81_dialog_content = "Desculpem o atraso, pessoal.",
  ui_story_5033_50331401_82_dialog_content = "Gustavo, senhor! Diga-nos o que fazer, por favor! Pollux tem aquela escória de Umbraton...",
  ui_story_5033_50331401_83_dialog_content = "Todos, apenas se acalmem. Eu vou explicar tudo para você em pouco tempo.",
  ui_story_5033_50331401_84_dialog_content = "Mas antes disso, deixe esses caras passarem.",
  ui_story_5033_50331401_85_dialog_content = "...",
  ui_story_5033_50331401_86_dialog_content = "Huh? HÃ?!",
  ui_story_5033_50331401_87_dialog_content = "O que você está fazendo aqui? Quando você apareceu?",
  ui_story_5033_50331401_88_dialog_content = "Temos que chegar à igreja, PlayerName! Casta está perdendo o controle!",
  ui_story_5033_50331401_89_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5033_50331401_90_dialog_content = "Casta... Esse é o seu nome, certo?",
  ui_story_5033_50331401_91_dialog_content = "<size=45>Revida! Quem você pensa que está olhando para baixo?! Contra-ataque!</size>",
  ui_story_5033_50331401_92_dialog_content = "Ainda preciso de tempo para encerrar as coisas, então temo que não possa perecer aqui. Mas eu nunca vou levantar minha mão contra você...",
  ui_story_5033_50331401_93_dialog_content = "Já que você é importante para a Pollux...",
  ui_story_5033_50331401_94_dialog_content = "...",
  ui_story_5033_50331401_95_dialog_content = "Você NÃO pode falar esse nome, assassino!",
  ui_story_5033_50331401_96_dialog_content = "PARE, Casta!",
  ui_story_5033_50331401_97_dialog_content = "<size=45>Saia daqui!</size>",
  ui_story_5033_50331401_98_dialog_content = "Eu não vou deixar você sabotar minha missão... Este é o Decreto Supremo do Senhor das Sombras!",
  ui_story_5033_50331401_99_dialog_content = "Ela deve ser trazida de volta viva!",
  ui_story_5033_50331401_100_dialog_content = "<size=45>Eu disse SAIA DAQUI!!</size>",
  ui_story_5033_50331401_101_dialog_content = "Ajude-me a controlá-la, PlayerName!",
  ui_story_5033_50331402_1_dialog_content = "<color=#e8d9bb>Voz! Tum!</color>",
  ui_story_5033_50331402_2_dialog_content = "Você... Escória...",
  ui_story_5033_50331402_3_dialog_content = "Eu sinto Muito. Eu tive que lutar seriamente para detê-lo.",
  ui_story_5033_50331402_4_dialog_content = "Assassino! Por aqui! O assassino está aqui!",
  ui_story_5033_50331402_5_dialog_content = "Já chega, Casta.",
  ui_story_5033_50331402_6_dialog_content = "Acalmou?",
  ui_story_5033_50331402_7_dialog_content = "Pollux, ela matou Matilda...",
  ui_story_5033_50331402_8_dialog_content = "Eu sei.",
  ui_story_5033_50331402_9_dialog_content = "Ela matou Matilda...",
  ui_story_5033_50331402_10_dialog_content = "E eu vou vingá-la, mas não hoje.",
  ui_story_5033_50331402_11_dialog_content = "Sim, eu vou expiar... Assim que tudo isso acabar.",
  ui_story_5033_50331402_12_dialog_content = "Se alguém vai tirar a vida de Anne, serei eu. Voce entende?",
  ui_story_5033_50331402_13_dialog_content = "Temos um entendimento, ela e eu.",
  ui_story_5033_50331402_14_dialog_content = "Pólux...",
  ui_story_5033_50331402_15_dialog_content = "Ana, não, Antares.",
  ui_story_5033_50331402_16_dialog_content = "Nos encontramos novamente, PlayerName, Corax.",
  ui_story_5033_50331402_17_dialog_content = "Todas essas coisas foram suas, Antares?",
  ui_story_5033_50331402_18_dialog_content = "Você é responsável pela morte da Irmã Matilda?",
  ui_story_5033_50331402_19_dialog_content = "Parece que você tem tudo planejado.",
  ui_story_5033_50331402_20_dialog_content = "Isso mesmo, eu sou quem você está procurando.",
  ui_story_5033_50331402_21_dialog_content = "Odeio dizer isso a você, mas também não sou uma freira. Minhas desculpas por enganá-lo.",
  ui_story_5033_50331402_22_dialog_content = "Por que... Por que você matou aquelas pessoas? E por que você veio aqui?",
  ui_story_5033_50331402_23_dialog_content = "<size=42>O que?! Sério?</size>",
  ui_story_5033_50331402_24_dialog_content = "Por que essas pessoas estão fazendo barulho de novo? Gustav não deveria estar no controle?",
  ui_story_5033_50331402_25_dialog_content = "Espere, você o viu?",
  ui_story_5033_50331402_26_dialog_content = "Sim, ele veio conosco.",
  ui_story_5033_50331402_27_dialog_content = "Então, onde ele está agora?",
  ui_story_5033_50331402_28_dialog_content = "Não sei. Ele não veio conosco.",
  ui_story_5033_50331402_29_dialog_content = "Ele é perigoso! Ele é o cérebro por trás de tudo isso!",
  ui_story_5033_50331402_30_dialog_content = "O que? Mastermind?",
  ui_story_5033_50331402_31_dialog_content = "Eu posso explicar, Pólux.",
  ui_story_5033_50331402_32_dialog_content = "O que você está dizendo é real, Gustav?",
  ui_story_5033_50331402_33_dialog_content = "Isso mesmo. Ela é a amiga mais próxima de Pollux... Antares.",
  ui_story_5033_50331402_34_dialog_content = "Deve ser horrível, associar-se com alguém assim... Por que ela faria isso, afinal?",
  ui_story_5033_50331402_35_dialog_content = "Por que deliberadamente causar problemas com Umbraton?!",
  ui_story_5033_50331402_36_dialog_content = "Ela deve estar usando isso como pretexto para assumir as cadeias de lucro de Euphoria e Umbraton.",
  ui_story_5033_50331402_37_dialog_content = "Incluindo os investigadores da Umbraton, eles provavelmente estão apenas fazendo um show.",
  ui_story_5033_50331402_38_dialog_content = "Eu não ficaria surpreso se tudo em Euphoria já estivesse com preço e disponível.",
  ui_story_5033_50331402_39_dialog_content = "Mas como eles estão lutando aqui? É algum tipo de conflito interno?",
  ui_story_5033_50331402_40_dialog_content = "Com licença, todos. Sinto muito, mas preciso dar uma palavrinha com o Sr. Gustav.",
  ui_story_5033_50331402_41_dialog_content = "E então?",
  ui_story_5033_50331402_42_dialog_content = "Nem Pollux nem Casta conseguiram cuidar de Antares.",
  ui_story_5033_50331402_43_dialog_content = "Eles são incapazes? Ou apenas atrasado?",
  ui_story_5033_50331402_44_dialog_content = "Sinto muito, não posso dizer com certeza.",
  ui_story_5033_50331402_45_dialog_content = "Impossível... Esse nível de ódio e animosidade... Como pode ser... Tem certeza disso?",
  ui_story_5033_50331402_46_dialog_content = "No mínimo, Antares ainda está vivo, e...",
  ui_story_5033_50331402_47_dialog_content = "Continue.",
  ui_story_5033_50331402_48_dialog_content = "Ela parece ter contado tudo a eles.",
  ui_story_5033_50331402_49_dialog_content = "Parece que as coisas não podem ficar muito piores...",
  ui_story_5033_50331402_50_dialog_content = "Então, qual é o nosso próximo passo?",
  ui_story_5033_50331402_51_dialog_content = "Próximo movimento...",
  ui_story_5033_50331402_52_dialog_content = "<color=#e8d9bb>*Rumble—*</color>",
  ui_story_5033_50331402_53_dialog_content = "Só sei qual será o nosso último movimento.",
  ui_story_5033_50331402_54_dialog_content = "Diga a todos que é hora de fazer isso.",
  ui_story_5033_50331402_55_dialog_content = "Se não lidarmos com o Sangue do Corvo aqui e agora, a Euforia nunca verá um dia de paz.",
  ui_story_5033_50331501_1_dialog_content = "Pólux! Venha aqui! Seu traidor da Euforia!",
  ui_story_5033_50331501_2_dialog_content = "Pólux! PÓLUX!",
  ui_story_5033_50331501_3_dialog_content = "Po...",
  ui_story_5033_50331501_4_dialog_content = "Uau! Ela... Ela realmente saiu...",
  ui_story_5033_50331501_5_dialog_content = "Quem está me chamando?",
  ui_story_5033_50331501_6_dialog_content = "...",
  ui_story_5033_50331501_7_dialog_content = "O que, você finalmente se atreve a mostrar seu rosto?",
  ui_story_5033_50331501_8_dialog_content = "Você está bem, Gustav. Suponho que seu gin tônico diário é para agradecer.",
  ui_story_5033_50331501_9_dialog_content = "Na verdade, não. Eles são apenas para me entorpecer, já que essa Euforia já oferece amplas decepções, não?",
  ui_story_5033_50331501_10_dialog_content = "Você não correu. Prefiro admirar isso.",
  ui_story_5033_50331501_11_dialog_content = "E por que eu iria correr? Estou aqui para cuidar de tudo. Afinal, Euphoria precisa de alguém que possa assumir o comando.",
  ui_story_5033_50331501_12_dialog_content = "<color=#e8d9bb>Da, da—</color>",
  ui_story_5033_50331501_13_dialog_content = "Ei, é a freira?!",
  ui_story_5033_50331501_14_dialog_content = "G-Volte, Gustav diz que ela é uma maníaca...",
  ui_story_5033_50331501_15_dialog_content = "Todos, permitam-me apresentá-los a alguém.",
  ui_story_5033_50331501_16_dialog_content = "Assassino em série de Umbraton, pecador de Euphoria e ex-membro da organização, Gêmeos-Antares.",
  ui_story_5033_50331501_17_dialog_content = "...",
  ui_story_5033_50331501_18_dialog_content = "O que? Confessou prontamente?",
  ui_story_5033_50331501_19_dialog_content = "Isso é Pollux para você, se comportando de forma admirável mesmo em uma situação tão desesperadora.",
  ui_story_5033_50331501_20_dialog_content = "E você? Como o cérebro por trás de tudo isso, será mais fácil se você confessar também.",
  ui_story_5033_50331501_21_dialog_content = "Parece que você tem a história toda escrita, Gustav.",
  ui_story_5033_50331501_22_dialog_content = "É uma pena que meu prisioneiro aqui tenha uma confissão diferente. Você gostaria de ouvir?",
  ui_story_5033_50331501_23_dialog_content = "Honrado povo da Euforia! Você deseja saber a verdade?",
  ui_story_5033_50331501_24_dialog_content = "Este cavalheiro diante de você, Gustav, não é apenas o sabe-tudo da Euphoria...",
  ui_story_5033_50331501_25_dialog_content = "Ele também é um ex-funcionário de alto escalão da organização.",
  ui_story_5033_50331501_26_dialog_content = "Organização? Isso significa a... organização que o Chefe gerenciou há mais de uma década?",
  ui_story_5033_50331501_27_dialog_content = "Não era um grupo para criar assassinos? Gustav é apenas um agente de inteligência normal, certo?",
  ui_story_5033_50331501_28_dialog_content = "A organização desmoronou há doze anos, graças à invasão do Eclipsite. Mas para Gustav aqui, esta era uma oportunidade de ouro.",
  ui_story_5033_50331501_29_dialog_content = "Usando sua identidade na Casa de Inteligência, ele começou a cortejar e conquistar as gangues e restabelecer a ordem, na tentativa de gradualmente assumir o controle da Euforia.",
  ui_story_5033_50331501_30_dialog_content = "Mas o mais importante, ele também estava com as mãos em uma arma letal...",
  ui_story_5033_50331501_31_dialog_content = "<color=#FFB400>Antares</color>.",
  ui_story_5033_50331501_32_dialog_content = "O que? A freira trabalha para Gustav?",
  ui_story_5033_50331501_33_dialog_content = "Nos últimos anos, Antares vem executando suas ordens, eliminando qualquer um que ainda tivesse controle sobre as cadeias de lucro da Euphoria.",
  ui_story_5033_50331501_34_dialog_content = "A raiva de Umbraton precisava de um bode expiatório, então sua ordem final era que Anne voltasse aqui, para me matar...",
  ui_story_5033_50331501_35_dialog_content = "Ou melhor, faça com que nos matemos.",
  ui_story_5033_50331501_36_dialog_content = "Hmm... Eu meio que posso ver como isso faz sentido.",
  ui_story_5033_50331501_37_dialog_content = "Não não! Só temos a palavra dela!",
  ui_story_5033_50331501_38_dialog_content = "Mas Gustav é o mesmo, não? Também não devemos acreditar cegamente nele, só porque ele dirige a Casa da Inteligência...",
  ui_story_5033_50331501_39_dialog_content = "Droga... Nós realmente todos fomos enganados?",
  ui_story_5033_50331501_40_dialog_content = "<size=45>Pólux! Chega!</size>",
  ui_story_5033_50331501_41_dialog_content = "Essas pessoas boas não são tolas! Eles não serão enganados por suas mentiras.",
  ui_story_5033_50331501_42_dialog_content = "Você só quer me jogar debaixo do ônibus e me fazer assumir a culpa por planejar tudo isso.",
  ui_story_5033_50331501_43_dialog_content = "Você sabe perfeitamente o que fez e pagará por isso, mesmo sem provas concretas!",
  ui_story_5033_50331501_44_dialog_content = "Ouça o que você está dizendo, irmã. Eu me sinto envergonhado por você.",
  ui_story_5033_50331501_45_dialog_content = "Se você está contra a parede e você quer me matar, um velho, então venha para mim!",
  ui_story_5033_50331501_46_dialog_content = "Mas não vou concorrer se você puder apresentar uma prova sequer.",
  ui_story_5033_50331501_47_dialog_content = "<size=45>Tenho provas!</size>",
  ui_story_5033_50331501_48_dialog_content = "Eu tenho provas! Bem aqui!",
  ui_story_5033_50331501_49_dialog_content = "Nekoyashiki?!",
  ui_story_5033_50331501_50_dialog_content = "...?!",
  ui_story_5033_50331501_51_dialog_content = "Dá licença! Todos vocês, saiam da frente!",
  ui_story_5033_50331501_52_dialog_content = "Quer provas, Gustav? Eu tenho sua prova aqui!",
  ui_story_5033_50331501_53_dialog_content = "Este é apenas de Umbraton, o testemunho de um sobrevivente!",
  ui_story_5033_50331501_54_dialog_content = "Um... Sobrevivente?!",
  ui_story_5033_50331501_55_dialog_content = "...",
  ui_story_5033_50331501_56_dialog_content = "A assassina era uma freira — ela! E aquele que organizou tudo, planejou tudo—",
  ui_story_5033_50331501_57_dialog_content = "<size=45>Não era ninguém menos que você, Gustav!</size>",
  ui_story_5033_50331501_58_dialog_content = "De jeito nenhum... Impossível... Não há como alguém sobreviver a isso!",
  ui_story_5033_50331501_59_dialog_content = "Isso é prova falsa!",
  ui_story_5033_50331501_60_dialog_content = "Isso é uma informação falsa! Vocês estão todos se unindo para me bater, não estão?!",
  ui_story_5033_50331501_61_dialog_content = "\"Jimmy Odenkirk, 47 anos, acordou de um coma grave...\"",
  ui_story_5033_50331501_62_dialog_content = "\"... Segundo sua descrição, o suspeito estava vestido de freira, com cabelos grisalhos...\"",
  ui_story_5033_50331501_63_dialog_content = "O suficiente...",
  ui_story_5033_50331501_64_dialog_content = "\"Fui convidado para lá naquele dia por Gustav of Euphoria... Entramos em uma armadilha, e nenhum dos meus homens conseguiu sair...\"",
  ui_story_5033_50331501_65_dialog_content = "O SUFICIENTE!! Eu não preciso ouvir essa bobagem caluniosa!!",
  ui_story_5033_50331501_66_dialog_content = "Se você ainda não admite, vamos levar nossos casos para o Senhor das Sombras!",
  ui_story_5033_50331501_67_dialog_content = "Vamos ver quais desculpas vocês duplas de vilões inventam então!",
  ui_story_5033_50331501_68_dialog_content = "Eu não tenho tempo para ceder ao seu absurdo! Não fique aí parado, pegue Nekoyashiki e os outros traidores!",
  ui_story_5033_50331501_69_dialog_content = "Uhh...",
  ui_story_5033_50331501_70_dialog_content = "Você ouviu o que eu disse?!",
  ui_story_5033_50331501_71_dialog_content = "O que você está dizendo é real, Nekoyashiki?",
  ui_story_5033_50331501_72_dialog_content = "Talvez seja melhor esperar para ver, não ser tão rápido em tirar conclusões... As coisas estão muito fluidas...",
  ui_story_5033_50331501_73_dialog_content = "Rápido, olhe para a expressão hedionda de Gustav...",
  ui_story_5033_50331501_74_dialog_content = "Qual o significado disso...",
  ui_story_5033_50331501_75_dialog_content = "Seu bando inútil de inúteis! Você esqueceu quem é seu chefe?!",
  ui_story_5033_50331501_76_dialog_content = "Esqueceu o dano que Umbraton infligiu neste lugar?!",
  ui_story_5033_50331501_77_dialog_content = "O que esse cara está dizendo? Não tem como ele ser o nosso chefe!",
  ui_story_5033_50331501_78_dialog_content = "Oi, Gustavo! É melhor você nos dar uma boa explicação! O que está acontecendo?",
  ui_story_5033_50331501_79_dialog_content = "E todos os seus pequenos minions também, vocês estão todos juntos?",
  ui_story_5033_50331501_80_dialog_content = "Não não! Não é da minha conta... não tenho nada a ver com ele!",
  ui_story_5033_50331501_81_dialog_content = "Hehe... Hahaha!",
  ui_story_5033_50331501_82_dialog_content = "Muito bem. Vocês mesmos causaram isso.",
  ui_story_5033_50331501_83_dialog_content = "Você me forçou a fazer isso!",
  ui_story_5033_50331501_84_dialog_content = "<color=#e8d9bb>Cang... Clink...</color>",
  ui_story_5033_50331501_85_dialog_content = "Huh? Isso é Darkflow...?",
  ui_story_5033_50331501_86_dialog_content = "<anim type=Shake><size=45>Graaagh!</size></anim>",
  ui_story_5033_50331501_87_dialog_content = "Oh não! Eclipses!",
  ui_story_5033_50331501_88_dialog_content = "Vai! Corra como quiser... Chame seus amigos e faça algumas travessuras!",
  ui_story_5033_50331501_89_dialog_content = "<anim type=Shake><size=45>Graaagh—!</size></anim>",
  ui_story_5033_50331501_90_dialog_content = "Eclipses! Eclipses em todos os lugares!",
  ui_story_5033_50331501_91_dialog_content = "Maldições! Como eles conseguiram nos cercar? Não há saída!",
  ui_story_5033_50331501_92_dialog_content = "Você... Verme! Você soltou os Eclipses? Eles só vão atrair mais!",
  ui_story_5033_50331501_93_dialog_content = "D-Não chegue mais perto! Uaaaagh!!",
  ui_story_5033_50331501_94_dialog_content = "Gustavo! Salve-nos!",
  ui_story_5033_50331501_95_dialog_content = "Lamento terrivelmente, todos. Deixe a Euforia...",
  ui_story_5033_50331501_96_dialog_content = "Seja limpo.",
  ui_story_5033_50331502_1_dialog_content = "Argh! Ajuda! Me salve!!",
  ui_story_5033_50331502_2_dialog_content = "Minhas pernas! Eu não posso me mover!",
  ui_story_5033_50331502_3_dialog_content = "Pare de gritar. É apenas uma ferida superficial.",
  ui_story_5033_50331502_4_dialog_content = "Não há nenhum Eclipsite por aqui. Basta ir encontrar o seu companheiro.",
  ui_story_5033_50331502_5_dialog_content = "Ok, ok... Obrigado...",
  ui_story_5033_50331502_6_dialog_content = "Se você quer agradecer a alguém, agradeça a Pollux. Você quase incendiou a igreja, e ainda assim ela está disposta a se dar ao trabalho de salvá-lo.",
  ui_story_5033_50331502_7_dialog_content = "Corax! À sua esquerda!",
  ui_story_5033_50331502_8_dialog_content = "Droga! Como eles continuam vindo?!",
  ui_story_5033_50331502_9_dialog_content = "Não sei. Talvez alguns Eclipses locais também sejam atraídos?",
  ui_story_5033_50331502_10_dialog_content = "E quanto a Antares? Você viu ela?",
  ui_story_5033_50331502_11_dialog_content = "Deixe-me procurá-la com minha habilidade psíquica! É um caos total por aqui!",
  ui_story_5033_50331502_12_dialog_content = "Ei! Você já viu Pollux?",
  ui_story_5033_50331502_13_dialog_content = "Não... Também estamos procurando...",
  ui_story_5033_50331502_14_dialog_content = "Acabei de vê-la do outro lado da igreja! Bem ali!",
  ui_story_5033_50331502_15_dialog_content = "E o Gustavo? Ele não poderia ter escapado, poderia?",
  ui_story_5033_50331502_16_dialog_content = "Oi, Gustavo! Espere!",
  ui_story_5033_50331502_17_dialog_content = "Jogada! Saia do meu caminho...",
  ui_story_5033_50331502_18_dialog_content = "<anim type=Shake><size=45>Graaaugh...!</size></anim>",
  ui_story_5033_50331502_19_dialog_content = "Ugh!",
  ui_story_5033_50331502_20_dialog_content = "Antares.",
  ui_story_5033_50331502_21_dialog_content = "Você soltou esses Eclipses, Gustav?",
  ui_story_5033_50331502_22_dialog_content = "Você quer que todos morram com você?",
  ui_story_5033_50331502_23_dialog_content = "O que, você está me dizendo que tem pena desses caras?",
  ui_story_5033_50331502_24_dialog_content = "Pena? Desculpe, mas eu não poderia me importar menos com suas vidas.",
  ui_story_5033_50331502_25_dialog_content = "Você é realmente impiedoso, Antares. E verdadeiramente digno de ser um dos Gêmeos...",
  ui_story_5033_50331502_26_dialog_content = "Mas estou particularmente intrigado com suas ações agora.",
  ui_story_5033_50331502_27_dialog_content = "Você realmente ainda tem esperança de redenção?",
  ui_story_5033_50331502_28_dialog_content = "Você não pode pensar que pode ser perdoado por me citar publicamente e pregar o que você chama de justiça?",
  ui_story_5033_50331502_29_dialog_content = "... Oh não. Claro que não.",
  ui_story_5033_50331502_30_dialog_content = "Você vai pagar por isso! E você sozinho!",
  ui_story_5033_50331502_31_dialog_content = "TUDO que fiz foi por Euforia... Você não entende, não consegue compreender!",
  ui_story_5033_50331502_32_dialog_content = "Tudo o que você tem são aquelas amizades e vínculos tediosos e insignificantes! Você não pode ver o que eu vejo!",
  ui_story_5033_50331502_33_dialog_content = "A euforia está uma bagunça total há doze anos, Antares!",
  ui_story_5033_50331502_34_dialog_content = "Esses caras da Umbraton não se importam se vivemos ou morremos, enquanto os locais não têm coragem ou força para reconstruir!",
  ui_story_5033_50331502_35_dialog_content = "Só existe eu! Você sabe, eu sou o único que pode intensificar!",
  ui_story_5033_50331502_36_dialog_content = "Para restaurar um membro doente, é preciso extirpar a carne podre e retirar as larvas...",
  ui_story_5033_50331502_37_dialog_content = "E você, Antares, é meu bisturi. Uma excelente ferramenta para excisão ...",
  ui_story_5033_50331502_38_dialog_content = "Depois de hoje, a euforia também pode renascer.",
  ui_story_5033_50331502_39_dialog_content = "É só que nenhum de nós pode ver.",
  ui_story_5033_50331502_40_dialog_content = "...",
  ui_story_5033_50331502_41_dialog_content = "<color=#e8d9bb>Clique—</color>",
  ui_story_5033_50331502_42_dialog_content = "Abaixe sua arma, Gustav. Do jeito que as coisas estão, você não tem chance.",
  ui_story_5033_50331502_43_dialog_content = "Aqui está você finalmente, Pollux. Este é realmente um... desenvolvimento afortunado.",
  ui_story_5033_50331502_44_dialog_content = "Já é hora de você sair de sua pequena e aconchegante igrejinha, para as ruas repletas de cadáveres.",
  ui_story_5033_50331502_45_dialog_content = "O que você quer dizer?",
  ui_story_5033_50331502_46_dialog_content = "Hahaha...",
  ui_story_5033_50331502_47_dialog_content = "Não venda este lugar, Pollux, não o venda.",
  ui_story_5033_50331502_48_dialog_content = "Se você realmente quer...",
  ui_story_5033_50331502_49_dialog_content = "Pelo menos consiga um bom preço.",
  ui_story_5033_50331502_50_dialog_content = "O que você está planejando, Gustavo?!",
  ui_story_5033_50331502_51_dialog_content = "Eu não gostaria de incomodá-lo... Eu posso acabar com isso sozinho!",
  ui_story_5033_50331502_52_dialog_content = "Eu não vou morrer na ignomínia como o Chefe... Nunca...",
  ui_story_5033_50331502_53_dialog_content = "Ugh!",
  ui_story_5033_50331502_54_dialog_content = "Ele se matou.",
  ui_story_5033_50331502_55_dialog_content = "Eu tinha outros planos para ele. Ele desceu levemente.",
  ui_story_5033_50331502_56_dialog_content = "Mantenha esses planos em seu bolso por enquanto. Salve-os para <color=#FFB400>outros</color>.",
  ui_story_5033_50331502_57_dialog_content = "Outras?",
  ui_story_5033_50331502_58_dialog_content = "Pollux, você vê aquelas pessoas lá embaixo, segurando tochas e carregando molotovs?",
  ui_story_5033_50331502_59_dialog_content = "Não consigo ver seus rostos claramente. Para mim, todos parecem iguais: hediondos, tolos e sem esperança.",
  ui_story_5033_50331502_60_dialog_content = "Ana, acabou. Está pronto. Você só precisa voltar para Umbraton e enfrentar seu destino, então...",
  ui_story_5033_50331502_61_dialog_content = "Uma coisa que Gustav disse fazia sentido.",
  ui_story_5033_50331502_62_dialog_content = "Somos todos partes purulentas da Euforia, feridas sujas que nunca vão cicatrizar completamente.",
  ui_story_5033_50331502_63_dialog_content = "Somente removendo essas partes podres ele pode realmente renascer.",
  ui_story_5033_50331502_64_dialog_content = "O que você quer fazer?",
  ui_story_5033_50331502_65_dialog_content = "Cumprir minha missão como o Ceifador.",
  ui_story_5033_50331502_66_dialog_content = "Oh não, então nós... Salve-nos! Corre!",
  ui_story_5033_50331502_67_dialog_content = "Antares!",
  ui_story_5033_50331502_68_dialog_content = "Seu coração está tão suave como sempre, Pollux. É por isso que digo que você não mudou, mesmo depois de todos esses anos.",
  ui_story_5033_50331502_69_dialog_content = "Mas uma doença grave precisa de remédios potentes.",
  ui_story_5033_50331502_70_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5033_50331502_71_dialog_content = "O que é esse voo certo para nós?! Proteja-se-!",
  ui_story_5033_50331502_72_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5033_50331502_73_dialog_content = "Mulher louca... Como você pode envolver civis inocentes?!",
  ui_story_5033_50331502_74_dialog_content = "Casta! Ajuda! Pare esta freira, rapidamente!",
  ui_story_5033_50331502_75_dialog_content = "Pólux! Faça alguma coisa!",
  ui_story_5033_50331502_76_dialog_content = "Eu...",
  ui_story_5033_50331502_77_dialog_content = "Anne, eu sei o que você está fazendo. Mas não isso... Não há necessidade disso.",
  ui_story_5033_50331502_78_dialog_content = "Nós tinhamos um acordo.",
  ui_story_5033_50331502_79_dialog_content = "Você também ouviu a evidência de ferro que o cavalheiro apresentou publicamente agora mesmo...",
  ui_story_5033_50331502_80_dialog_content = "Mesmo que eu não tivesse interesse em limpar Euphoria, eu ainda não poderia deixar essas testemunhas vivas.",
  ui_story_5033_50331502_81_dialog_content = "Cale a boca, Anne... Apenas pare...",
  ui_story_5033_50331502_82_dialog_content = "E vou começar com a pessoa mais próxima de mim.",
  ui_story_5033_50331502_83_dialog_content = "Argh! De volta! Voltam!",
  ui_story_5033_50331502_84_dialog_content = "Você também é o único que pode me parar.",
  ui_story_5033_50331502_85_dialog_content = "Tá preparado?",
  ui_story_5033_50331502_86_dialog_content = "Você realmente tem que fazer isso?!",
  ui_story_5033_50331502_87_dialog_content = "<size=30>Não vou deixar você me levar, Pollux. Desejo ficar em Euphoria, embora do meu jeito.</size>",
  ui_story_5033_50331502_88_dialog_content = "<size=30>A única maneira que me resta é expiar meus pecados.</size>",
  ui_story_5033_50331502_89_dialog_content = "...",
  ui_story_5033_50331502_90_dialog_content = "É o bastante.",
  ui_story_5033_50331502_91_dialog_content = "Não tenho ideais tão grandiosos, Anne.",
  ui_story_5033_50331502_92_dialog_content = "Isso é só para Matilda.",
  ui_story_5033_50331502_93_dialog_content = "Claro, isso também é para Matilda.",
  ui_story_5033_50331502_94_dialog_content = "Vença-a, Pólux! Para euforia!",
  ui_story_5033_50331502_95_dialog_content = "Para euforia! Euforia!",
  ui_story_5033_50331502_96_dialog_content = "Vamos começar. Espero que você ainda tenha.",
  ui_story_5033_50331502_97_dialog_content = "Não se preocupe, eu me lembro do essencial. Esses eu nunca vou esquecer...",
  ui_story_5033_50331502_98_dialog_content = "Ainda tenho uma última pergunta, Anne.",
  ui_story_5033_50331502_99_dialog_content = "Heh. Perguntar.",
  ui_story_5033_50331502_100_dialog_content = "Se você tivesse uma segunda chance, você ainda faria isso?",
  ui_story_5033_50331502_101_dialog_content = "Você quer dizer com Gustav...",
  ui_story_5033_50331502_102_dialog_content = "Não. Quero dizer, naquela época, 14 anos atrás...",
  ui_story_5033_50331502_103_dialog_content = "Você ainda seria esfaqueado por mim?",
  ui_story_5033_50331502_104_dialog_content = "Sim. Se eu tivesse uma segunda chance, eu correria para você do mesmo jeito.",
  ui_story_5033_50331502_105_dialog_content = "E então eu te abraçaria forte e te daria adeus.",
  ui_story_5033_50331502_106_dialog_content = "Assim como agora...",
  ui_story_5033_50331502_107_dialog_content = "<color=#e8d9bb>*Esfaquear—*</color>",
  ui_story_5033_50331502_108_dialog_content = "...",
  ui_story_5033_50331502_109_dialog_content = "Seus olhos são muito mais resolutos do que eram naquela época.",
  ui_story_5033_50331502_110_dialog_content = "Você mudou, Pollux. É bom ver.",
  ui_story_5033_50331502_111_dialog_content = "E... Você realmente guardou... aquela adaga...",
  ui_story_5033_50331502_112_dialog_content = "Não mais. Vou enterrá-lo depois de hoje.",
  ui_story_5033_50331502_113_dialog_content = "Adeus, meu Pólux.",
  ui_story_5033_50331502_114_dialog_content = "Adeus... Antares, cheio de pecado.",
  ui_story_5033_50331502_115_dialog_content = "Agora, finalmente, eu sou o mesmo que você.",
  ui_story_5033_50331502_116_dialog_content = "Po—",
  ui_story_5033_50331502_117_dialog_content = "?!",
  ui_story_5033_50331502_118_dialog_content = "Este... Antares, e Gustav?!",
  ui_story_5033_50331502_119_dialog_content = "...",
  ui_story_5033_50331502_120_dialog_content = "Pólux! Você está bem?",
  ui_story_5033_50331502_121_dialog_content = "...",
  ui_story_5033_50331502_122_dialog_content = "Corax, você pode me ajudar a verificar?",
  ui_story_5033_50331502_123_dialog_content = "Gustavo está morto. Deixe-me ver como está Anne...",
  ui_story_5033_50331502_124_dialog_content = "Não precisa.",
  ui_story_5033_50331502_125_dialog_content = "O quê?",
  ui_story_5033_50331502_126_dialog_content = "Não há necessidade, doutor.",
  ui_story_5033_50331502_127_dialog_content = "Sua missão... <color=#FFB400>falhou</color>.",
  ui_story_5033_50331502_128_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5033_50331601_1_dialog_content = "<color=#e8d9bb>Várias horas depois</color>",
  ui_story_5033_50331601_2_dialog_content = "... Então, era realmente Gustav puxando as cordas.",
  ui_story_5033_50331601_3_dialog_content = "Eu venho dizendo há tempos que ele estava usando todo mundo, mas ninguém ouviu. Hmph.",
  ui_story_5033_50331601_4_dialog_content = "Parece que a freira assassina está morta. Retirado pela própria Pollux.",
  ui_story_5033_50331601_5_dialog_content = "Eu não esperava nada menos de Pollux... Temos sorte de tê-la...",
  ui_story_5033_50331601_6_dialog_content = "Ouvi dizer que eles cresceram juntos. Eu acho que era algo que ela não podia ignorar?",
  ui_story_5033_50331601_7_dialog_content = "Nada de fofocar pelas costas das pessoas.",
  ui_story_5033_50331601_8_dialog_content = "Se você realmente não tem mais nada para fazer, então você pode me ajudar a consertar as paredes e janelas da igreja. As crianças ainda precisam de um lugar para morar.",
  ui_story_5033_50331601_9_dialog_content = "Você tem idade suficiente para assumir parte da responsabilidade.",
  ui_story_5033_50331601_10_dialog_content = "Yeah, yeah...",
  ui_story_5033_50331601_11_dialog_content = "Nekoyashiki, por enquanto, todos voltaram para a igreja.",
  ui_story_5033_50331601_12_dialog_content = "Muito bem, Latan.",
  ui_story_5033_50331601_13_dialog_content = "Então, uh, e o Pollux? Estamos todos muito preocupados...",
  ui_story_5033_50331601_14_dialog_content = "Ela... Ela está amarrando algumas pontas soltas com Casta.",
  ui_story_5033_50331601_15_dialog_content = "Eles estão naquelas colinas atrás de nós e devem estar de volta em breve. Você vai para dentro, ainda está chovendo.",
  ui_story_5033_50331601_16_dialog_content = "A chuva parou há muito tempo, Nekoyashiki.",
  ui_story_5033_50331601_17_dialog_content = "\"... Seu difícil caminho chegou ao fim, e ainda uma nova jornada espera.\"",
  ui_story_5033_50331601_18_dialog_content = "\"Ela deve retornar à terra e se fundir com os lagos...\"",
  ui_story_5033_50331601_19_dialog_content = "\"E, finalmente, volte para a poeira estelar.\"",
  ui_story_5033_50331601_20_dialog_content = "...",
  ui_story_5033_50331601_21_dialog_content = "O céu está clareando, Pollux.",
  ui_story_5033_50331601_22_dialog_content = "Ah, é tão brilhante. O sol sempre foi tão deslumbrante...?",
  ui_story_5033_50331601_23_dialog_content = "Você vê que a névoa se foi também? Então é assim que Euphoria realmente é.",
  ui_story_5033_50331601_24_dialog_content = "Obrigada, PlayerName, por se oferecer para ler o elogio de Anne.",
  ui_story_5033_50331601_25_dialog_content = "Tenho vergonha de admitir que nem isso posso fazer, apesar de viver na igreja por tantos anos.",
  ui_story_5033_50331601_26_dialog_content = "Oh, talvez você simplesmente não consiga encontrar uma maneira de se expressar.",
  ui_story_5033_50331601_27_dialog_content = "Talvez o elogio ordinário, dado a tantas pessoas todos os dias, não seja adequado para Antares.",
  ui_story_5033_50331601_28_dialog_content = "De qualquer forma, sinto muito pela sua perda.",
  ui_story_5033_50331601_29_dialog_content = "Eu não estou de luto. Pelo contrário, estou bastante aliviado.",
  ui_story_5033_50331601_30_dialog_content = "É como acordar de um sonho caótico, tendo visto pessoas que você nunca mais verá.",
  ui_story_5033_50331601_31_dialog_content = "Mas agora que acordei do sonho, o céu está claro e devo continuar a trilhar meu próprio caminho.",
  ui_story_5033_50331601_32_dialog_content = "Então o que vem depois?",
  ui_story_5033_50331601_33_dialog_content = "Acho que vou ficar aqui por um tempo.",
  ui_story_5033_50331601_34_dialog_content = "Não apenas por causa das crianças na igreja, mas também porque é raro ver Euphoria tão claramente.",
  ui_story_5033_50331601_35_dialog_content = "Isso é provavelmente o que Antares também desejava ver.",
  ui_story_5033_50331601_36_dialog_content = "Talvez. Ou talvez ela quisesse expiar seus pecados pela minha mão.",
  ui_story_5033_50331601_37_dialog_content = "Ela era realmente complicada.",
  ui_story_5033_50331601_38_dialog_content = "Se ela realmente tivesse morrido quatorze anos atrás, e não tivesse sido usada por ninguém...",
  ui_story_5033_50331601_39_dialog_content = "Ou se não tivéssemos sido obrigados a matar uns aos outros, e Gêmeos tivesse continuado...",
  ui_story_5033_50331601_40_dialog_content = "Ou se nunca nos conhecêssemos?",
  ui_story_5033_50331601_41_dialog_content = "Antares e Pollux, apenas dois estranhos, vivendo suas vidas.",
  ui_story_5033_50331601_42_dialog_content = "A história seria diferente?",
  ui_story_5033_50331601_43_dialog_content = "Qual seria o novo destino de Euphoria?",
  ui_story_5033_50331601_44_dialog_content = "Vamos, Pólux. Não é como você ser tão nostálgico.",
  ui_story_5033_50331601_45_dialog_content = "Você tem razão. Estou pronto para dizer adeus ao passado.",
  ui_story_5033_50331601_46_dialog_content = "Aquela faca e o broche de hortênsia...",
  ui_story_5033_50331601_47_dialog_content = "Que descansem em paz junto com Antares.",
  ui_story_5033_50331601_48_dialog_content = "Isso me lembra que não prestamos nossos respeitos a Matilda este ano.",
  ui_story_5033_50331601_49_dialog_content = "Ah, isso mesmo. Deixe-me cuidar de tudo por aqui, então devemos encontrar um tempo para visitar Umbraton.",
  ui_story_5033_50331601_50_dialog_content = "Tudo bem, não vou incomodá-lo mais. Adeus, Pollux, Casta.",
  ui_story_5033_50331601_51_dialog_content = "Você está indo para o dirigível Shuttle Hub sozinho?",
  ui_story_5033_50331601_52_dialog_content = "Com todos correndo como galinhas sem cabeça, a estrada pode ser ainda mais difícil.",
  ui_story_5033_50331601_53_dialog_content = "Mas Corax voltou para Umbraton sozinho novamente, disse algo sobre fazer um relatório...",
  ui_story_5033_50331601_54_dialog_content = "Eu irei com voce.",
  ui_story_5033_50331601_55_dialog_content = "Sim, deixe Casta ir junto.",
  ui_story_5033_50331601_56_dialog_content = "Ainda tenho alguns... outros assuntos para tratar. Vocês vão em frente.",
  ui_story_5033_50331601_57_dialog_content = "Eu acredito que vamos nos encontrar novamente, PlayerName. Basta esperar que a Euphoria se torne um verdadeiro país das maravilhas.",
  ui_story_5033_50331601_58_dialog_content = "Claro, Pólux. Aguardo ansiosamente por esse dia.",
  ui_story_5033_50331601_59_dialog_content = "<color=#e8d9bb>Umbraton, dois dias depois</color>",
  ui_story_5033_50331601_60_dialog_content = "Li tudo sobre isso! Criminoso em assassinatos em série de Umbraton morto durante a captura!",
  ui_story_5033_50331601_61_dialog_content = "Quer um papel, Sr. Corax?",
  ui_story_5033_50331601_62_dialog_content = "Como você me reconheceu...?",
  ui_story_5033_50331601_63_dialog_content = "Afaste-se de mim, vá em frente.",
  ui_story_5033_50331601_64_dialog_content = "Tudo bem, não precisa ser tão mau. Li tudo sobre isso!",
  ui_story_5033_50331601_65_dialog_content = "...",
  ui_story_5033_50331601_66_dialog_content = "Você está atrasado.",
  ui_story_5033_50331601_67_dialog_content = "Casta não é um grande piloto de dirigível.",
  ui_story_5033_50331601_67X1_dialog_content = "Me siga.",
  ui_story_5033_50331601_68_dialog_content = "<color=#e8d9bb>*Virar a página*</color>",
  ui_story_5033_50331601_69_dialog_content = "O que é isso...?",
  ui_story_5033_50331601_70_dialog_content = "Caso encerrado. Shadowlord viu o arquivo, e o assunto está resolvido mais ou menos como descrito.",
  ui_story_5033_50331601_71_dialog_content = "Bom. Obrigado, Corax.",
  ui_story_5033_50331601_72_dialog_content = "Você realmente deveria estar me agradecendo!",
  ui_story_5033_50331601_73_dialog_content = "Eu estava claramente lá em uma missão, mas não consegui trazer de volta nenhum dos dois suspeitos, desculpe, dois criminosos.",
  ui_story_5033_50331601_74_dialog_content = "Haha, isso realmente é azar.",
  ui_story_5033_50331601_75_dialog_content = "Eu...",
  ui_story_5033_50331601_76_dialog_content = "Vamos deixar isso por enquanto. Continue indo, você encontrará outro documento.",
  ui_story_5033_50331601_77_dialog_content = "O plano do Shadowlord é reconstruir a Euphoria com você. Veja se há problemas.",
  ui_story_5033_50331601_78_dialog_content = "Com o Gustav morto, deve ser uma loucura lá.",
  ui_story_5033_50331601_79_dialog_content = "Existem muitas gangues de Umbraton que dependem da Euphoria para viver. Teremos que apresentar algumas ideias novas.",
  ui_story_5033_50331601_80_dialog_content = "Shadowlord não quer trilhar o mesmo caminho antigo. Caso contrário, não há diferença com esses miseráveis. Você entende?",
  ui_story_5033_50331601_81_dialog_content = "Concordo. Isso é o que eu estava pensando também.",
  ui_story_5033_50331601_82_dialog_content = "A carne podre já foi extirpada. É hora de começar de novo.",
  ui_story_5033_50331601_83_dialog_content = "Essa é uma boa analogia. Euphoria era o paciente gravemente doente que finalmente teve suas partes necróticas removidas...",
  ui_story_5033_50331601_84_dialog_content = "É hora de um novo tratamento que levará a um tecido saudável.",
  ui_story_5033_50331601_85_dialog_content = "Sim, e o novo tratamento é o plano de reconstrução da Umbraton.",
  ui_story_5033_50331601_86_dialog_content = "Essas crianças podem finalmente crescer como o tecido saudável da Euphoria.",
  ui_story_5033_50331601_87_dialog_content = "O que mais está no plano, Corax? Além da reestruturação industrial?",
  ui_story_5033_50331601_88_dialog_content = "Algo como bem-estar social?",
  ui_story_5033_50331601_89_dialog_content = "Você está pensando em um orfanato?",
  ui_story_5033_50331601_90_dialog_content = "Relaxar! Sinta-se à vontade para mencionar o que quiser. Eu não acho que Shadowlord irá rejeitar essas sugestões.",
  ui_story_5033_50331601_91_dialog_content = "Afinal, ele é um grande fã de crianças... Ahem.",
  ui_story_5033_50331601_92_dialog_content = "Parece que tenho algo em comum com ele, afinal, somos ambos pessimistas otimistas.",
  ui_story_5033_50331601_93_dialog_content = "Acho que entendi isso.",
  ui_story_5033_50331601_94_dialog_content = "Vocês dois podem acreditar que o mundo está além da ajuda, mas ainda têm esperança para a próxima geração.",
  ui_story_5033_50331601_95_dialog_content = "Os olhos das crianças não mentem, Corax. Basta ir a um orfanato ou escola, e você pode ver por si mesmo.",
  ui_story_5033_50331601_96_dialog_content = "Esses são os únicos lugares puros e bons que restam.",
  ui_story_5033_50331601_97_dialog_content = "Acredito que temos que confiar nessas crianças para que Euphoria volte a ser ensolarada.",
  ui_story_5033_50331601_98_dialog_content = "Assim como Matilda acreditou em nós, tantos anos atrás.",
  ui_story_5033_50331601_99_dialog_content = "...",
  ui_story_5033_50331601_100_dialog_content = "Chega de papo. Analisaremos os planos novamente e entraremos em contato com você.",
  ui_story_5033_50331601_101_dialog_content = "Se não houver mais nada, vou me despedir.",
  ui_story_5033_50331601_102_dialog_content = "Deixe-me vê-lo no Shuttle Hub.",
  ui_story_5033_50331601_103_dialog_content = "Não precisa, mas obrigado. Quero visitar o cemitério.",
  ui_story_5033_50331601_104_dialog_content = "Para prestar seus respeitos a Matilda? Eu acho que eu gostaria disso também, tudo bem?",
  ui_story_5033_50331601_105_dialog_content = "É claro. Obrigado, Corax.",
  ui_story_5033_50331601_106_dialog_content = "Vamos lá, o que há com todo o \"obrigado\" hoje? Não estou acostumada a você ser tão formal.",
  ui_story_5033_50331601_107_dialog_content = "<color=#e8d9bb>Colosso, Ponte</color>",
  ui_story_5033_50331601_108_dialog_content = "Tamanho certo para cortinas. Poderia ser uma saia, com mais alguns metros.",
  ui_story_5033_50331601_109_dialog_content = "*Suspira*",
  ui_story_5033_50331601_110_dialog_content = "Mesa de jantar, luminária de chão, tapete... Existe alguma aberração cromática com o tapete?",
  ui_story_5033_50331601_111_dialog_content = "*Suspira*",
  ui_story_5033_50331601_112_dialog_content = "Prateleira, verifique... Onde está a tábua de cortar de desenhos animados? Ai está.",
  ui_story_5033_50331601_113_dialog_content = "*Suspirar...*",
  ui_story_5033_50331601_114_dialog_content = "Você está bem, PlayerName? Tudo isso está te cansando?",
  ui_story_5033_50331601_115_dialog_content = "Estou me sentindo um pouco pra baixo, Vice.",
  ui_story_5033_50331601_116_dialog_content = "O que aconteceu nos últimos dias parece um sonho.",
  ui_story_5033_50331601_117_dialog_content = "Por que você está sempre fazendo essas aventuras bizarras quando estou fora, hmm?",
  ui_story_5033_50331601_118_dialog_content = "Qual é a história desta vez?",
  ui_story_5033_50331601_119_dialog_content = "Deixe-me organizar meus pensamentos. Eu nem sei por onde começar.",
  ui_story_5033_50331601_120_dialog_content = "Tudo bem. De qualquer forma, o que há com isso... \"Hortângea Saudável\"?",
  ui_story_5033_50331601_121_dialog_content = "Uma compra por impulso, da qual me arrependi imediatamente. Atrai muitos bugs.",
  ui_story_5033_50331601_122_dialog_content = "Ainda assim, deixe-o lá. Eu gosto de olhar para isso.",
  ui_story_5033_50331601_123_dialog_content = "Ah você. Parece que você tem o mundo em seus ombros.",
  ui_story_5033_50331601_124_dialog_content = "Tens de me dizer o que aconteceu desta vez.",
  ui_story_5033_50331601_125_dialog_content = "Multar. Você já ouviu falar em Euforia?",
  ui_story_5033_50331601_126_dialog_content = "Hmm... Toca uma campainha.",
  ui_story_5033_50331601_127_dialog_content = "Bem, tudo começa com este lugar chamado Euphoria..."
}
return config
